def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data.get('demands', [])

    # Build mappings: node -> route index, and collect all non-depot nodes
    node_to_route = {}
    all_nodes = set()
    for r_idx, route in enumerate(current_solution):
        for node in route:
            if node == 0:
                continue
            node_to_route[node] = r_idx
            all_nodes.add(node)

    # Precompute route-wise node lists (excluding depots)
    route_to_nodes = {}
    for r_idx, route in enumerate(current_solution):
        nodes = [n for n in route if n != 0]
        route_to_nodes[r_idx] = nodes

    scores = []
    all_nodes_list = list(all_nodes)

    for node in all_nodes_list:
        r = node_to_route[node]
        intra_nodes = route_to_nodes[r]
        # intra-route distance: sum to other nodes in the same route
        dist_within = 0.0
        for other in intra_nodes:
            if other == node:
                continue
            dist_within += dist[node][other]

        # cross-route distance: sum to all nodes not in the same route
        dist_cross = 0.0
        for other in all_nodes_list:
            if other == node:
                continue
            if node_to_route.get(other, None) != r:
                dist_cross += dist[node][other]

        demand_node = demands[node] if node < len(demands) else 0
        # score favors larger cross-distance and penalizes high demand slightly
        score = dist_cross - dist_within - 0.01 * demand_node
        # small random jitter to diversify tie outcomes
        score += rng.random() * 0.05 * (dist_cross + 1e-9)

        scores.append((node, score))

    # Determine number of nodes to remove (fractional and at least 1 if any nodes exist)
    total_nodes = len(all_nodes)
    if total_nodes <= 0:
        k = 0
    else:
        frs = [0.20, 0.25, 0.30]
        fr = frs[rng.integers(0, len(frs))]
        k = int(round(total_nodes * fr))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data.get('distance_matrix', [])
    scores = []
    for route in current_solution:
        if not route:
            continue
        for node in route:
            if node == 0:
                continue  # skip depot
            # compute average distance to other non-depot nodes in the same route
            sum_dist = 0.0
            count = 0
            for other in route:
                if other == 0 or other == node:
                    continue
                sum_dist += distance_matrix[node][other]
                count += 1
            avg_dist = (sum_dist / count) if count > 0 else 0.0
            score = avg_dist
            score += rng.random() * 0.1  # small random perturbation for diversity
            scores.append((node, score))

    N = len(scores)
    if N == 0:
        return [], 0

    k = max(1, int(round(N * 0.25)))
    if k > N:
        k = N

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data['demands']

    # determine max demand for normalization
    if isinstance(demands, dict):
        max_demand = max(demands.values()) if demands else 1
    else:
        max_demand = max(demands) if isinstance(demands, (list, tuple)) and len(demands) > 0 else 1

    scores = []

    for route in current_solution:
        if not route:
            continue
        # collect non-depot nodes in this route
        nodes = [n for n in route if n != 0]
        if not nodes:
            continue

        # find route centroid: minimize sum(distance(c, o) * weight(o)) over c in nodes
        best_centroid = nodes[0]
        best_cost = float('inf')
        for c in nodes:
            cost = 0.0
            for o in nodes:
                if o == c:
                    continue
                if isinstance(demands, dict):
                    w = demands.get(o, 0)
                else:
                    if isinstance(demands, (list, tuple)) and 0 <= o < len(demands):
                        w = demands[o]
                    else:
                        w = 0
                cost += distance_matrix[c][o] * w
            if cost < best_cost:
                best_cost = cost
                best_centroid = c

        centroid = best_centroid

        # score each node by its distance to centroid, weighted by demand
        for node in nodes:
            dist_to_centroid = distance_matrix[node][centroid]
            if isinstance(demands, dict):
                demand = demands.get(node, 0)
            else:
                if isinstance(demands, (list, tuple)) and 0 <= node < len(demands):
                    demand = demands[node]
                else:
                    demand = 0
            norm = demand / max_demand if max_demand > 0 else 0.0
            score = dist_to_centroid * (1.0 + 0.5 * norm)
            if hasattr(rng, 'random'):
                score += 0.01 * rng.random()
            scores.append((node, score))

    total_nodes = len(scores)
    if total_nodes == 0:
        return [], 0

    scores.sort(key=lambda x: x[1], reverse=True)

    base_k = max(1, int(round(total_nodes * 0.2)))
    jitter = int(round((rng.random() - 0.5) * max(1, int(total_nodes * 0.2))))
    k = base_k + jitter
    if k < 1:
        k = 1
    if k > total_nodes:
        k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data['demands']

    # Gather unique candidate nodes (non-depot)
    candidate_nodes = []
    seen = set()
    for route in current_solution:
        if not isinstance(route, (list, tuple)):
            continue
        for node in route:
            if node == 0:
                continue
            if node not in seen:
                seen.add(node)
                candidate_nodes.append(node)

    if not candidate_nodes:
        return [], 0

    # Precompute route lengths (cost of each route including depot at ends)
    route_lengths = {}
    for r_idx, route in enumerate(current_solution):
        if not route:
            continue
        cost = 0
        prev = 0
        for node in route:
            cost += dist[prev][node]
            prev = node
        cost += dist[prev][0]
        route_lengths[r_idx] = cost

    max_route_length = 0
    for val in route_lengths.values():
        if val > max_route_length:
            max_route_length = val
    if max_route_length <= 0:
        max_route_length = 1

    # Max demand among candidates
    max_demand = 0
    for n in candidate_nodes:
        if n < len(demands) and demands[n] > max_demand:
            max_demand = demands[n]
    if max_demand <= 0:
        max_demand = 1

    scores = []
    for node in candidate_nodes:
        # Diversity term: mean distance to a random sample of other candidates
        others = [n for n in candidate_nodes if n != node]
        if others:
            sample_size = min(8, len(others))
            sample = rng.choice(others, size=sample_size, replace=False)
            mean_dist = sum(dist[node][s] for s in sample) / sample_size
        else:
            mean_dist = 0.0

        # Demand term
        node_demand = demands[node] if node < len(demands) else 0
        demand_norm = node_demand / max_demand

        # Route-context term: how long the node's route is relative to max
        node_route_length = 0
        for route in current_solution:
            if not route:
                continue
            if node in route:
                cost = 0
                prev = 0
                for n in route:
                    cost += dist[prev][n]
                    prev = n
                cost += dist[prev][0]
                node_route_length = cost
                break
        route_factor = node_route_length / max_route_length if max_route_length > 0 else 0.0

        # Combine terms with a small jitter
        score = mean_dist * 1.0 + demand_norm * 0.6 + route_factor * 0.4
        score += rng.random() * 0.01

        scores.append((node, score))

    # Determine k: 25% of candidates with some jitter
    total_candidates = len(candidate_nodes)
    base = max(1, int(round(total_candidates * 0.25)))
    jitter = int(round((rng.random() - 0.5) * max(1, total_candidates * 0.2)))
    k = max(1, min(total_candidates, base + jitter))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data['demands']
    max_demand = max(demands) if demands else 0

    scores = []
    seen = set()

    # total non-depot nodes for k calculation
    total_nodes = 0
    for route in current_solution:
        for node in route:
            if node != 0:
                total_nodes += 1

    # Collect scores for unique non-depot nodes
    for route in current_solution:
        if not route:
            continue
        # non-depot nodes in this route
        route_nodes = [n for n in route if n != 0]
        L = len(route_nodes)
        center_node = route_nodes[L // 2] if L > 0 else None

        for idx, node in enumerate(route):
            if node == 0:
                continue
            if node in seen:
                continue
            seen.add(node)

            pred = route[idx - 1] if idx > 0 else 0
            nxt = route[idx + 1] if idx < len(route) - 1 else 0

            delta = dist[pred][node] + dist[node][nxt] - dist[pred][nxt]
            if delta < 0:
                delta = 0.0

            if center_node is not None:
                center_distance = dist[node][center_node]
                center_signal = 1.0 / (1.0 + center_distance)
            else:
                center_signal = 0.0

            demand = demands[node] if node < len(demands) else 0
            demand_norm = demand / max_demand if max_demand > 0 else 0.0

            score = delta * 1.0 + center_signal * 0.5 + demand_norm * 0.2
            score += rng.random() * 1e-6  # tiny jitter for diversification

            scores.append((node, score))

    if total_nodes <= 0:
        k = 0
    else:
        k = int(total_nodes * 0.25)
        if k < 1:
            k = 1
        if k > len(scores):
            k = len(scores)

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    # Build all edges between consecutive nodes in all routes
    edges = []
    for route in current_solution:
        if not route:
            continue
        for i in range(len(route) - 1):
            a = route[i]
            b = route[i + 1]
            edges.append((a, b))

    scores = []
    score_dict = {}

    # Compute delta for each non-depot node and its best insertion displacement value
    for route in current_solution:
        if not route:
            continue
        L = len(route)
        for idx, node in enumerate(route):
            if node == 0:
                continue
            prev_node = route[idx - 1] if idx > 0 else 0
            next_node = route[idx + 1] if idx < L - 1 else 0

            delta = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]

            best_value = -10**18  # large negative initial value
            for (a, b) in edges:
                insertion_cost = distance_matrix[a][node] + distance_matrix[node][b] - distance_matrix[a][b]
                value = insertion_cost - delta
                if value > best_value:
                    best_value = value

            if best_value == -10**18:
                best_value = 0.0

            score_dict[node] = best_value

    # Convert to list of (node, score)
    for n in sorted(score_dict.keys()):
        scores.append((n, score_dict[n]))

    total_nodes = len(scores)
    if total_nodes == 0:
        return [], 0

    # Randomized, small fraction of nodes to remove
    frac = 0.15 + 0.10 * rng.random()  # between 0.15 and 0.25
    k = int(total_nodes * frac)
    if k < 1:
        k = 1
    if k > total_nodes:
        k = total_nodes

    # Sort by score descending so the framework can remove top-k
    scores.sort(key=lambda x: x[1], reverse=True)

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # determine max demand for normalization
    max_demand = 1
    if isinstance(demands, dict):
        if demands:
            max_demand = max(demands.values()) if demands else 1
    else:
        if isinstance(demands, (list, tuple)) and len(demands) > 0:
            max_demand = max(demands)
        else:
            max_demand = 1

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        # non-depot nodes in this route
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue

        # compute average distance to peers for each node in this route
        node_avg = {}
        for i in non_dep:
            sum_dist = 0.0
            cnt = 0
            for j in non_dep:
                if j == i:
                    continue
                # safe distance retrieval
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0.0
                sum_dist += d
                cnt += 1
            avg = sum_dist / cnt if cnt > 0 else 0.0
            node_avg[i] = avg

        route_mean = sum(node_avg.values()) / len(node_avg) if node_avg else 0.0

        for i in non_dep:
            avg_dist = node_avg.get(i, 0.0)
            outlier_score = avg_dist - route_mean

            # retrieve demand for node i
            if isinstance(demands, dict):
                d = demands.get(i, 0)
            else:
                if isinstance(demands, (list, tuple)) and i < len(demands):
                    d = demands[i]
                else:
                    d = 0

            norm_demand = d / max_demand if max_demand > 0 else 0.0

            score = outlier_score * (1.0 - 0.6 * norm_demand)
            score += rng.random() * 0.01  # small random perturbation

            scores.append((i, score))
            total_nodes += 1

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data['demands']

    # Step 1: compute a center for each route (node with minimal sum of distances to other nodes in the same route)
    centers = {}
    candidate_nodes = []  # list of (node, route_index)
    for r_idx, route in enumerate(current_solution):
        nodes = [n for n in route if n != 0]
        if not nodes:
            continue
        best_center = None
        best_sum = None
        for c in nodes:
            s = 0
            row_c = distance_matrix[c]
            for o in nodes:
                if o == c:
                    continue
                s += row_c[o]
            if best_sum is None or s < best_sum:
                best_sum = s
                best_center = c
        centers[r_idx] = best_center
        for n in nodes:
            candidate_nodes.append((n, r_idx))

    total_candidates = len(candidate_nodes)
    if total_candidates == 0:
        return [], 0

    # Determine max demand for normalization
    max_demand = 1
    if isinstance(demands, dict):
        max_demand = max(demands.values()) if demands else 1
    else:
        max_demand = max(demands) if isinstance(demands, (list, tuple)) and demands else 1
    if max_demand <= 0:
        max_demand = 1

    # Step 2: compute score for each candidate node
    scores = []
    for node, r in candidate_nodes:
        own_center = centers.get(r, None)
        dist_to_own_center = distance_matrix[node][own_center] if own_center is not None else 0

        # distance to centers of other routes
        min_other_center_dist = None
        for other_r, other_center in centers.items():
            if other_r == r:
                continue
            d = distance_matrix[node][other_center]
            if min_other_center_dist is None or d < min_other_center_dist:
                min_other_center_dist = d
        if min_other_center_dist is None:
            min_other_center_dist = dist_to_own_center  # only one route exists

        # demand normalization
        demand_node = demands[node] if isinstance(demands, (list, tuple)) and node < len(demands) else 0
        norm = demand_node / max_demand

        score = (min_other_center_dist - dist_to_own_center) - 0.5 * norm
        score += rng.random() * 0.01  # small random jitter for diversification

        scores.append((node, score))

    # Step 3: determine k (fraction of candidates to remove)
    k_fraction = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
    k = max(1, int(round(total_candidates * k_fraction)))
    if k > total_candidates:
        k = total_candidates

    return scores, k

def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data['demands']

    # Determine max demand for normalization
    if isinstance(demands, dict):
        max_demand = max(demands.values()) if demands else 1
    else:
        max_demand = max(demands) if isinstance(demands, (list, tuple)) and len(demands) > 0 else 1

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        # collect non-depot nodes in this route
        nodes = [n for n in route if n != 0]
        if not nodes:
            continue

        total_nodes += len(nodes)

        # For each node, compute sum of distances to all other nodes in the same route
        for i, node in enumerate(nodes):
            sum_dist = 0.0
            for j, other in enumerate(nodes):
                if i == j:
                    continue
                sum_dist += dist[node][other]

            # obtain demand for this node
            if isinstance(demands, dict):
                demand = demands.get(node, 0)
            else:
                demand = demands[node] if node < len(demands) else 0

            # bias by demand magnitude
            factor = 1.0 + (demand / max_demand) if max_demand > 0 else 1.0

            score = sum_dist * factor

            # tiny random perturbation for diversification
            if hasattr(rng, 'random'):
                score += rng.random() * 1e-9

            scores.append((node, score))

    # Determine k: number of nodes to remove
    if total_nodes == 0:
        k = 0
    else:
        base = max(1, int(round(total_nodes * 0.25)))
        jitter = int(round((rng.random() - 0.5) * max(1, int(total_nodes * 0.2))))
        k = max(1, min(total_nodes, base + jitter))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data.get('demands', [])

    # Collect all non-depot nodes present in the solution
    nodes_set = set()
    for route in current_solution:
        for v in route:
            if v != 0:
                nodes_set.add(v)

    scores = []
    if not nodes_set:
        return scores, 0

    # Total demand among the non-depot nodes (for weighting)
    total_demand = 0
    for v in nodes_set:
        if v < len(demands):
            total_demand += demands[v]

    # Compute a global, demand-weighted distance influence for each node
    sorted_nodes = sorted(nodes_set)
    for v in sorted_nodes:
        s = 0.0
        if total_demand > 0:
            for j in nodes_set:
                wj = demands[j] / total_demand if j < len(demands) else 0.0
                s += dist[v][j] * wj
        else:
            for j in nodes_set:
                s += dist[v][j]
        # small random jitter for diversification
        s += rng.random() * 0.001
        scores.append((v, s))

    max_k = max(1, int(round(0.2 * len(nodes_set))))
    k = int(rng.random() * max_k)
    if k < 1:
        k = 1
    if k > len(nodes_set):
        k = len(nodes_set)

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    # Build mapping of node -> (route_index, position_in_route) and collect all non-depot nodes
    position = {}
    all_nodes = set()
    for r_idx, route in enumerate(current_solution):
        if not route:
            continue
        for idx, node in enumerate(route):
            if node == 0:
                continue
            if node not in position:
                position[node] = (r_idx, idx)
            all_nodes.add(node)

    if not all_nodes:
        return [], 0

    # Precompute an exposure score for each node: sum of distances from this node to all other non-depot nodes
    nodes_list = list(all_nodes)
    exposure = {}
    for node in nodes_list:
        total = 0.0
        for other in nodes_list:
            if other == node:
                continue
            total += distance_matrix[node][other]
        exposure[node] = total

    # Compute combined scores: local removal savings + small weight on global exposure
    alpha = 0.01  # weight for exposure (global influence)
    scores = []
    for node in nodes_list:
        ri, idx = position[node]
        route = current_solution[ri]
        m = len(route)

        # local removal savings
        if m == 1:
            savings = 0.0
        else:
            if idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                nxt = route[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][nxt] -
                           distance_matrix[prev_node][nxt])

        score = savings + alpha * exposure[node]
        scores.append((node, score))

    total_nodes = len(scores)
    if total_nodes == 0:
        return [], 0

    max_k = max(1, total_nodes // 4)
    k = int(rng.random() * max_k)
    if k < 1:
        k = 1
    if k > total_nodes:
        k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # determine max demand for normalization
    if isinstance(demands, dict):
        max_demand = max(demands.values()) if demands else 1
    else:
        max_demand = max(demands) if isinstance(demands, (list, tuple)) and len(demands) > 0 else 1

    scores = []
    total_nodes = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        m = len(non_dep)
        if m == 0:
            continue
        total_nodes += m

        for i in non_dep:
            # average distance to other nodes in the same route
            s = 0.0
            for j in non_dep:
                if j == i:
                    continue
                s += distance_matrix[i][j]
            avg_dist = s / (m - 1) if m > 1 else 0.0

            # local density: sum of 1/(1 + distance)
            density = 0.0
            for j in non_dep:
                if j == i:
                    continue
                dist_ij = distance_matrix[i][j]
                density += 1.0 / (1.0 + dist_ij)

            # demand-based normalization
            if isinstance(demands, dict):
                demand = demands.get(i, 0)
            else:
                demand = demands[i] if isinstance(demands, (list, tuple)) and 0 <= i < len(demands) else 0

            score = avg_dist - 0.5 * density
            score += 0.25 * (demand / max_demand) if max_demand > 0 else 0.0
            score += 0.01 * (rng.random() if hasattr(rng, 'random') else 0.0)

            scores.append((i, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.16 + rng.random() * 0.14  # between 0.16 and 0.30
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Gather unique non-depot candidate nodes
    candidate_nodes = []
    seen = set()
    for route in current_solution:
        for node in route:
            if node == 0:
                continue
            if node not in seen:
                seen.add(node)
                candidate_nodes.append(node)

    N = len(candidate_nodes)
    if N == 0:
        return [], 0

    # Compute max_demand for normalization
    max_demand = 1
    for node in candidate_nodes:
        if isinstance(demands, dict):
            d = demands.get(node, 0)
        else:
            if isinstance(demands, (list, tuple)) and node < len(demands):
                d = demands[node]
            else:
                d = 0
        if d > max_demand:
            max_demand = d
    if max_demand <= 0:
        max_demand = 1

    scores = []
    for node in candidate_nodes:
        # Build sample of other nodes
        others = [n for n in candidate_nodes if n != node]
        s = min(10, len(others))

        if len(others) == 0 or s == 0:
            avg_dist = 0.0
        else:
            if len(others) >= s:
                sample = rng.choice(others, size=s, replace=False)
                sample_nodes = sample.tolist()
            else:
                sample_nodes = others

            if sample_nodes:
                total = 0.0
                for nb in sample_nodes:
                    total += distance_matrix[node][nb]
                avg_dist = total / len(sample_nodes)
            else:
                avg_dist = 0.0

        # Demand normalization
        if isinstance(demands, dict):
            demand = demands.get(node, 0)
        else:
            if isinstance(demands, (list, tuple)) and node < len(demands):
                demand = demands[node]
            else:
                demand = 0
        norm_demand = demand / max_demand

        # Score: global centrality (avg distance) plus demand influence, plus jitter
        score = avg_dist * 1.0 + norm_demand * 0.6
        score += rng.random() * 0.01

        scores.append((node, score))

    # Determine k as a small random fraction of candidates
    frac = 0.15 + 0.25 * rng.random()  # 15% to 40%
    k = int(round(N * frac))
    if k < 1:
        k = 1
    if k > N:
        k = N

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    # Count non-depot nodes and compute removal gains
    total_non_depot = 0
    scores = []  # list of (node, score)

    if not current_solution:
        return scores, 0

    for route in current_solution:
        if not route:
            continue

        # Count non-depot nodes in this route
        for n in route:
            if n != 0:
                total_non_depot += 1

        # Compute gain for internal nodes (excluding depots at ends)
        for idx in range(1, len(route) - 1):
            node = route[idx]
            if node == 0:
                continue
            pred = route[idx - 1]
            succ = route[idx + 1]
            # Cost change if removing 'node': pred->node + node->succ replaced by pred->succ
            improvement = distance_matrix[pred][node] + distance_matrix[node][succ] - distance_matrix[pred][succ]
            if improvement < 0:
                improvement = 0
            scores.append((node, improvement))

    if total_non_depot == 0:
        return scores, 0

    k = max(1, int(round(0.2 * total_non_depot)))
    if k > len(scores):
        k = len(scores)
    if k == 0:
        return scores, 0

    # Break ties with randomness using rng
    scored = []
    for (node, score) in scores:
        scored.append((node, score, rng.random()))
    scored.sort(key=lambda t: (t[1], t[2]), reverse=True)

    # Return all scores and the number to remove
    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data.get('distance_matrix', [])
    demands = data.get('demands', [])
    # determine a sensible max demand for normalization
    max_demand = 0
    for idx in range(1, len(demands)):
        if demands[idx] > max_demand:
            max_demand = demands[idx]
    if max_demand <= 0:
        max_demand = 1

    scores_map = {}
    total_nodes = 0

    for route in current_solution:
        if not route or len(route) == 0:
            continue
        # assume route has a 0 (depot) at both ends; consider internal customers
        for i in range(1, len(route) - 1):
            node = route[i]
            if node == 0:
                continue
            prev_node = route[i - 1]
            next_node = route[i + 1]

            # compute potential savings by removing this node
            if (prev_node < len(distance_matrix) and node < len(distance_matrix) and next_node < len(distance_matrix)):
                saving = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]
            else:
                saving = 0

            total_nodes += 1
            d = demands[node] if node < len(demands) else 0
            noise = rng.random()
            # combine saving with a random perturbation and penalize high-demand nodes slightly
            score = saving + 0.5 * noise - 0.4 * (d / max_demand)
            scores_map[node] = score

    if total_nodes == 0:
        return [], 0

    scores = [(node, scores_map[node]) for node in sorted(scores_map.keys())]
    k = max(1, int(round(0.2 * total_nodes)))
    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance = data['distance_matrix']
    demands = data.get('demands', [])
    max_demand = max(demands) if demands else 0
    gamma = 0.5

    node_scores = {}

    for route in current_solution:
        if not route:
            continue
        for idx, node in enumerate(route):
            if node == 0:
                continue  # skip depot
            prev_node = route[idx - 1] if idx > 0 else 0
            next_node = route[idx + 1] if idx < len(route) - 1 else 0
            delta = distance[prev_node][node] + distance[node][next_node] - distance[prev_node][next_node]
            demand = demands[node] if node < len(demands) else 0
            score = delta + gamma * (demand / max_demand if max_demand > 0 else 0.0)

            if node in node_scores:
                if score > node_scores[node]:
                    node_scores[node] = score
            else:
                node_scores[node] = score

    scores = [(n, s) for n, s in node_scores.items()]
    if not scores:
        return [], 0

    n = len(scores)
    k = max(1, int(n * 0.25))

    scores_sorted = sorted(scores, key=lambda t: (-t[1], rng.random()))
    k = min(k, len(scores_sorted))
    return scores_sorted, k

def destroy_scoring(current_solution, data, rng):
    distance = data['distance_matrix']
    demands = data['demands']

    # Collect all nodes present in the current solution
    present_nodes = set()
    for route in current_solution:
        for node in route:
            present_nodes.add(node)

    # Score each node based on local detour savings
    scores = []
    for route in current_solution:
        for idx, node in enumerate(route):
            if node == 0:
                continue  # skip depot if present
            prev_node = route[idx - 1] if idx > 0 else 0
            next_node = route[idx + 1] if idx < len(route) - 1 else 0

            dist_prev_i = distance[prev_node][node]
            dist_i_next = distance[node][next_node]
            dist_prev_next = distance[prev_node][next_node]

            savings = dist_prev_i + dist_i_next - dist_prev_next
            if savings < 0:
                savings = 0.0

            demand_node = demands[node] if node < len(demands) else 0
            score = savings + 0.01 * demand_node

            scores.append((node, score))

    total_nodes = len(present_nodes)
    if total_nodes <= 0:
        k = 0
    else:
        k_base = int(round(total_nodes * 0.3))
        if k_base < 1:
            k_base = 1
        jitter = rng.integers(-1, 2)  # -1, 0, or 1
        k = k_base + jitter
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance = data['distance_matrix']
    # collect all non-depot nodes present in the solution
    all_nodes = set()
    for route in current_solution:
        if isinstance(route, list):
            for v in route:
                if isinstance(v, int) and v != 0:
                    all_nodes.add(v)

    # compute delta scores for each node
    node_to_score = {}
    for route in current_solution:
        if not isinstance(route, list) or len(route) < 2:
            continue
        has_depot = (len(route) >= 2 and route[0] == 0 and route[-1] == 0)
        if has_depot:
            indices = range(1, len(route) - 1)
        else:
            if len(route) < 3:
                continue
            indices = range(1, len(route) - 1)
        for idx in indices:
            node = route[idx]
            if node == 0:
                continue
            prev_node = route[idx - 1]
            next_node = route[idx + 1]
            dist_prev_node = distance[prev_node][node]
            dist_node_next = distance[node][next_node]
            dist_prev_next = distance[prev_node][next_node]
            delta = dist_prev_node + dist_node_next - dist_prev_next
            current = node_to_score.get(node, 0)
            if delta > current:
                node_to_score[node] = delta

    scores = []
    for n in all_nodes:
        scores.append((n, node_to_score.get(n, 0)))

    total_nodes = len(all_nodes)
    if total_nodes > 0:
        base_k = int(round(total_nodes * 0.25))
        if base_k < 1:
            base_k = 1
        jitter = rng.random()  # in [0, 1)
        factor = 0.8 + 0.4 * jitter  # [0.8, 1.2)
        k = int(round(base_k * factor))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes
    else:
        k = 0

    return scores, k

