            prev_node = route[idx - 1] if idx > 0 else 0
            next_node = route[idx + 1] if idx < len(route) - 1 else 0

            try:
                saving = distance[prev_node][node] + distance[node][next_node] - distance[prev_node][next_node]
            except Exception:
                saving = 0

            demand_i = demands[node] if node < len(demands) else 0
            score = saving - 0.01 * demand_i
            score += rng.random() * 0.1

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
