def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    # Collect all non-depot nodes present in the solution
    nodes_set = set()
    for route in current_solution:
        for v in route:
            if v != 0:
                nodes_set.add(v)

    node_savings = {}

    for route in current_solution:
        if not route:
            continue
        if 0 in route:
            ext = route[:]
        else:
            ext = [0] + route + [0]
        for i in range(1, len(ext) - 1):
            v = ext[i]
            if v == 0:
                continue
            a = ext[i - 1]
            b = ext[i + 1]
            savings = distance_matrix[a][v] + distance_matrix[v][b] - distance_matrix[a][b]
            node_savings[v] = node_savings.get(v, 0.0) + savings

    scores = []
    for v in sorted(nodes_set):
        s = node_savings.get(v, 0.0)
        jitter = rng.random() * 0.001
        scores.append((v, s + jitter))

    if len(nodes_set) > 0:
        k = max(1, int(round(0.2 * len(nodes_set))))
    else:
        k = 0

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance = data['distance_matrix']
    demands = data['demands']

    scores_dict = {}
    for route in current_solution:
        for idx, node in enumerate(route):
            pred = route[idx - 1] if idx > 0 else None
            succ = route[idx + 1] if idx < len(route) - 1 else None

            if pred is not None and succ is not None:
                delta = distance[pred][node] + distance[node][succ] - distance[pred][succ]
            elif pred is not None:
                delta = distance[pred][node]
            elif succ is not None:
                delta = distance[node][succ]
            else:
                delta = 0.0

            d = demands[node] if node < len(demands) else 0
            score = delta * 1.0 + d * 0.5

            if node in scores_dict:
