    temp = []
    for node, sc in scores_dict.items():
        temp.append((node, sc, rng.random()))
    temp.sort(key=lambda x: (-x[1], x[2]))
    scores = [(node, sc) for node, sc, _ in temp]

    k = max(1, int(0.25 * total_nodes))
    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance = data['distance_matrix']

    # Build all adjacent edges (including depot connections at route ends)
    edges = []
    for route in current_solution:
        if not route or len(route) == 0:
            continue
        for j in range(len(route) - 1):
            edges.append((route[j], route[j + 1]))
        if route[0] != 0:
            edges.append((0, route[0]))
        if route[-1] != 0:
            edges.append((route[-1], 0))

    # Collect all non-depot nodes present in the solution
    nodes = []
    seen = set()
    for route in current_solution:
        for n in route:
            if n != 0 and n not in seen:
                seen.add(n)
                nodes.append(n)
    nodes.sort()

    scores = []
    for i in nodes:
        min_delta = None
        for pred, succ in edges:
            delta = distance[pred][i] + distance[i][succ] - distance[pred][succ]
            if min_delta is None or delta < min_delta:
                min_delta = delta
        if min_delta is None:
            min_delta = 0.0
        # Tiny randomness to break ties
        rand_noise = rng.random() * 1e-6
        score = float(min_delta) + rand_noise
        scores.append((i, score))

    n = len(nodes)
    if n <= 0:
        k = 0
    else:
        k = max(1, int(round(n * 0.25)))
        if k > n:
            k = n

    return scores, k

def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data['demands']

    # Build mappings: node -> route, route non-zero length, and node positions
    node_to_route = {}
    route_nonzero_counts = []
    for r_idx, route in enumerate(current_solution):
        count = 0
        for node in route:
            if node != 0:
                count += 1
                node_to_route[node] = r_idx
        route_nonzero_counts.append(count)

    node_to_pos = {}
    for r_idx, route in enumerate(current_solution):
        for i, node in enumerate(route):
            if node != 0:
                node_to_pos[node] = (r_idx, i)

    # Compute per-route loads (sum of demands on the route)
    route_loads = []
    for route in current_solution:
        s = 0
        for node in route:
            if node != 0:
                s += demands[node]
        route_loads.append(s)

    # Score each node
    scores = []
    for node, (r_idx, pos) in node_to_pos.items():
        route = current_solution[r_idx]
        prev_node = route[pos-1] if pos > 0 else None
        next_node = route[pos+1] if pos < len(route) - 1 else None

        if prev_node is not None and next_node is not None:
            old_cost = dist[prev_node][node] + dist[node][next_node]
            new_cost = dist[prev_node][next_node]
            savings = old_cost - new_cost
        elif prev_node is not None:
            savings = dist[prev_node][node]
        elif next_node is not None:
            savings = dist[node][next_node]
        else:
            savings = 0.0

        r_len = route_nonzero_counts[r_idx]
        d = demands[node]
        load = route_loads[r_idx]
        jitter = rng.random() * 1e-6

        score = savings + 0.5 * r_len + 0.01 * d + 0.005 * (load - d) + jitter
        scores.append((node, score))

    # Number of nodes to remove (20% of nodes, at least 1)
    n_nodes = len(scores)
    k = max(1, int(round(n_nodes * 0.2)))
    if k > n_nodes:
        k = n_nodes

    return scores, k

