            savings = old_cost - new_cost
        elif prev_node is not None:
            savings = dist[prev_node][node]
        elif next_node is not None:
            savings = dist[node][next_node]
        else:
            savings = 0.0

        r_len = route_nonzero_counts[r_idx]
        d = demands[node]
        load = route_loads[r_idx]

        center = (r_len - 1) / 2.0 if r_len > 0 else 0.0
        centrality = abs(pos - center)

        slack = capacity - load
        balance_term = 0.0
        if slack > 0:
            balance_term = min(d, slack)

        jitter = rng.random() * 1e-6

        score = savings + 0.4 * r_len - 0.25 * centrality + 0.8 * balance_term + 0.01 * d + jitter
        scores.append((node, score))

    n_nodes = len(scores)
    k = max(1, int(round(n_nodes * 0.2)))
    if k > n_nodes:
        k = n_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # vehicle_capacities is not used in this heuristic but kept for compatibility
    _vehicle_capacities = data.get('vehicle_capacities', [])

    centers = []
    non_depot_total = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        non_depot_total += len(non_dep)
        if not non_dep:
            centers.append(0)
            continue

        best_center = None
        best_weighted_sum = None
        for n in non_dep:
            s = 0
            for m in non_dep:
                if m == n:
                    continue
                if n < len(distance_matrix) and m < len(distance_matrix[n]):
                    d = distance_matrix[n][m]
                else:
                    d = 0
                w = demands[m] if m < len(demands) else 0
                s += d * w
            if best_weighted_sum is None or s < best_weighted_sum:
                best_weighted_sum = s
                best_center = n
        centers.append(best_center if best_center is not None else 0)

    scores = []
    route_idx = 0
    for route in current_solution:
        center = centers[route_idx]
        route_idx += 1
        if not route:
            continue
        for node in route:
            if node == 0:
                continue
            if node < len(distance_matrix) and center < len(distance_matrix[node]):
                dist_to_center = distance_matrix[node][center]
            else:
                dist_to_center = 0
            demand = demands[node] if node < len(demands) else 0
            score = dist_to_center * (demand if demand is not None else 0)
            perturb = rng.random() * 0.01 * (dist_to_center + 1e-9) * (demand + 1e-9)
            score += perturb
            scores.append((node, score))

    if non_depot_total == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = max(1, int(round(non_depot_total * frac)))
