    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # determine max demand for normalization
    max_demand = 1
    if isinstance(demands, dict):
        if demands:
            max_demand = max(demands.values()) if demands else 1
    else:
        if isinstance(demands, (list, tuple)) and len(demands) > 0:
            max_demand = max(demands)
        else:
            max_demand = 1

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        # non-depot nodes in this route
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue

        node_avg = {}
        node_median = {}
        for i in non_dep:
            dists = []
            sum_dist = 0.0
            for j in non_dep:
                if j == i:
                    continue
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0.0
                dists.append(d)
                sum_dist += d
            cnt = len(dists)
            avg = sum_dist / cnt if cnt > 0 else 0.0
            node_avg[i] = avg

            # compute median of distances to peers
            if dists:
                sorted_d = sorted(dists)
                med = sorted_d[len(sorted_d) // 2]
            else:
                med = 0.0
            node_median[i] = med

        route_mean = sum(node_avg.values()) / len(node_avg) if node_avg else 0.0

        for i in non_dep:
            avg_dist = node_avg.get(i, 0.0)
            med_dist = node_median.get(i, 0.0)

            # retrieve demand for node i
            if isinstance(demands, dict):
                d = demands.get(i, 0)
            else:
                if isinstance(demands, (list, tuple)) and i < len(demands):
                    d = demands[i]
                else:
                    d = 0

            norm_demand = d / max_demand if max_demand > 0 else 0.0

            diff_mean = abs(avg_dist - route_mean)
            diff_med = abs(avg_dist - med_dist)

            # composite score: emphasize deviation from peers, dampened by demand
            score = diff_mean * 0.7 + diff_med * 0.3 - 0.4 * norm_demand
            score += rng.random() * 0.01  # small random perturbation

            scores.append((i, score))
            total_nodes += 1

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    # compute max demand for scaling
    max_demand = 0
    for d in demands:
        if d > max_demand:
            max_demand = d

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)
        if m == 0:
            continue
        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Compute local removal impact (savings) with a modified scheme
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]

            # Demand-based scaling
            demand = demands[node] if node < len(demands) else 0
            if max_demand > 0:
                demand_factor = 1.0 + 0.5 * (demand / max_demand)
            else:
                demand_factor = 1.0

            # Small random perturbation to diversify
            jitter = rng.random() * 0.01

            score = savings * demand_factor + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # Compute total demand on this route (ignore None/0 nodes)
        route_demand = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Local savings if removing this node
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]

            demand = demands[node] if node < len(demands) else 0
            slack = cap - route_demand
            if slack < 0:
                slack = 0
            factor = 1.0 / (slack + 1)
            jitter = rng.random() * 0.4 - 0.2  # small random perturbation in [-0.2, 0.2)
            score = savings * 0.9 + demand * 0.6 * factor + jitter
            scores.append((node, score))

    max_k = max(1, total_nodes // 4) if total_nodes > 0 else 0
    if total_nodes == 0:
        k = 0
    else:
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data['demands']
    scores = []
    seen = set()

    max_demand = max(demands) if demands else 0
    DEMAND_SENSITIVITY = 0.6  # parameter controlling how strongly demand affects the score

    for route in current_solution:
        if not route:
            continue
        for i, node in enumerate(route):
            if node == 0:
                continue
            if node in seen:
                continue
            seen.add(node)

            prev = route[i - 1] if i - 1 >= 0 else 0
            nxt = route[i + 1] if i + 1 < len(route) else 0

            saving = dist[prev][node] + dist[node][nxt] - dist[prev][nxt]
            if saving < 0:
                saving = 0.0

            demand = demands[node] if node < len(demands) else 0
            if max_demand > 0:
                scale = 1.0 + DEMAND_SENSITIVITY * (max_demand - demand) / float(max_demand)
            else:
                scale = 1.0

            score = saving * scale
            scores.append((node, score))

    total_nodes = len(scores)
    if total_nodes <= 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
        k = int(rng.random() * max_k)
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
