def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Route-length factor (larger routes have amplified influence)
        factor = 1.0 + 0.6 * ((L - 1) ** 0.5)

        for node in non_dep:
            # Compute sum of distances to the two nearest neighbors within the same route
            if L > 1:
                dists = []
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    dists.append(d)

                if len(dists) >= 2:
                    # find two smallest distances
                    min1, min2 = float('inf'), float('inf')
                    for d in dists:
                        if d < min1:
                            min2 = min1
                            min1 = d
                        elif d < min2:
                            min2 = d
                    sum_two_closest = min1 + min2
                elif len(dists) == 1:
                    sum_two_closest = dists[0]
                else:
                    sum_two_closest = 0.0
            else:
                sum_two_closest = 0.0

            depot_distance = distance_matrix[node][0]

            demand = demands[node] if node < len(demands) else 0

            denom = 1.0 + 0.4 * demand
            score = (sum_two_closest + depot_distance) * factor / denom

            perturb = rng.random() * 0.04 * (sum_two_closest + depot_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.13  # between 0.15 and 0.28
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # Build the list of all non-depot nodes across all routes
    all_nodes = []
    for route in current_solution:
        for n in route:
            if n != 0:
                all_nodes.append(n)
    total_all = len(all_nodes)

    scores = []
    # Compute scores per node using global-local distance mismatch
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        for node in non_dep:
            # Local mean distance within the route
            if L > 1:
                s = 0.0
                count = 0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                    count += 1
                local_mean = s / count if count > 0 else 0.0
            else:
                local_mean = 0.0

            # Global mean distance to all non-depot nodes
            if total_all > 1:
                s = 0.0
                count = 0
                for other in all_nodes:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                    count += 1
                global_mean = s / count if count > 0 else 0.0
            else:
                global_mean = 0.0

            # Distances for depot influence
            farthest_in_route = 0.0
            for other in non_dep:
                if other == node:
                    continue
                d = distance_matrix[node][other]
                if d > farthest_in_route:
                    farthest_in_route = d

            farthest_global = 0.0
            for other in all_nodes:
                if other == node:
                    continue
                d = distance_matrix[node][other]
                if d > farthest_global:
                    farthest_global = d

            denom = farthest_global if farthest_global > 0 else 1.0
            depot_distance = distance_matrix[node][0] if node < len(distance_matrix) else 0

            diff = global_mean - local_mean
            if diff < 0:
                diff = -diff

            score = diff * (1.0 + 0.3 * (depot_distance / denom))

            # Small random perturbation to diversify removal
            perturb = rng.random() * 0.05 * (local_mean + 1.0)
            score += perturb

            scores.append((node, score))

    total_non_dep = total_all
    if total_non_dep == 0:
        k = 0
    else:
        if len(scores) > 0:
            mean_score = sum(s for _, s in scores) / len(scores)
            var = 0.0
            for _, s in scores:
                d = s - mean_score
                var += d * d
            var /= max(1, len(scores))
            std = var ** 0.5
            max_score = max((s for _, s in scores), default=0.0)
            frac = 0.08 + 0.18 * (std / (1.0 + max_score))
            if frac < 0.05:
                frac = 0.05
            if frac > 0.25:
                frac = 0.25
            k = max(1, int(round(total_non_dep * frac)))
            if k > total_non_dep:
                k = total_non_dep
        else:
            k = 0

    return scores, k

