def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # Precompute max route length across all routes
    max_L = 0
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L > max_L:
            max_L = L

    max_demand = max(demands) if demands else 0

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route-size factor scaling with route length, distinct form
        if max_L > 1:
            factor = 1.0 + 0.25 * ((L - 1) / (max_L - 1))
        else:
            factor = 1.0

        for node in non_dep:
            # Inverse-distance centrality within the route
            if L > 1:
                sum_inv = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if d > 0:
                        sum_inv += 1.0 / d
            else:
                sum_inv = 0.0

            centrality = sum_inv / (L - 1) if L > 1 else 0.0

            demand = demands[node] if node < len(demands) else 0.0
            demand_norm = demand / (max_demand if max_demand > 0 else 1.0)

            score = centrality * (1.0 + 0.6 * demand_norm) * factor

            # Small random perturbation for diversification
            perturb = rng.random() * 0.03 * (sum_inv + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    # Build a candidate pivot set: non-depot nodes
    all_nodes = [i for i in range(1, len(distance_matrix))]
    P = max(3, min(12, int(len(all_nodes) * 0.15)))
    if P > len(all_nodes):
        P = len(all_nodes)

    pivots = []
    if P > 0 and len(all_nodes) > 0:
        pivots = list(rng.choice(all_nodes, size=P, replace=False))

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Route demand
        route_demand = sum(demands[n] if n < len(demands) else 0 for n in non_dep)

        # Remaining capacity ratio for the route
        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        if capacity > 0:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0
        else:
            remaining_ratio = 0.0

        for node in non_dep:
            # Mean distance to peers in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance_route = s / (L - 1)
            else:
                mean_distance_route = 0.0

            # Pivot proximity term
            if pivots:
                dist_to_pivots = 0.0
                for p in pivots:
                    dist_to_pivots += distance_matrix[node][p]
                avg_pivot_dist = dist_to_pivots / len(pivots)
            else:
                avg_pivot_dist = 0.0

            closeness = 1.0 / (1.0 + avg_pivot_dist)
            centrality_term = 1.0 / (1.0 + mean_distance_route) if L > 1 else 1.0

            # Score with a different weighting scheme and a jitter term
            score = 0.6 * closeness + 0.25 * centrality_term + 0.2 * remaining_ratio

            jitter = rng.random() * 0.05 * (avg_pivot_dist + mean_distance_route + 1.0)
            score += jitter

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.15  # between 0.10 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    N = len(distance_matrix)

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # Global mean distance for this node (to all nodes)
            if N > 1:
                global_sum = 0.0
                for j in range(N):
                    if j != node:
                        global_sum += distance_matrix[node][j]
                global_mean = global_sum / (N - 1)
            else:
                global_mean = 0.0

            # Mean distance to peers in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_route = s / (L - 1)
            else:
                mean_route = 0.0

            depot_distance = distance_matrix[node][0]
            demand = demands[node] if node < len(demands) else 0.0

            factor = 1.0 + 0.4 * ((L - 1) ** 0.5)
            score = abs(global_mean - mean_route) * factor

            if route_demand > 0.0:
                score *= 1.0 / (1.0 + 0.35 * (demand / route_demand))

            score += 0.3 * depot_distance

            perturb = rng.random() * 0.05 * (global_mean + depot_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.25  # between 0.12 and 0.37
        k = max(1, int(round(total_non_dep * frac)))
