    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Per-route demand information
        route_demands = []
        for n in non_dep:
            if n < len(demands):
                route_demands.append(demands[n])
            else:
                route_demands.append(0)
        total_dem = sum(route_demands)
        avg_dem = total_dem / L if L > 0 else 0

        route_min = min(route_demands) if route_demands else 0
        route_max = max(route_demands) if route_demands else 0

        for idx, node in enumerate(non_dep):
            # density: closeness to other nodes in the same route
            if L > 1:
                near_dist = None
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if near_dist is None or d < near_dist:
                        near_dist = d
                near_dist = near_dist if near_dist is not None else 0.0
            else:
                near_dist = 0.0

            density = 1.0 / (1.0 + near_dist)

            # route_factor grows with route length
            route_factor = 1.0 + 0.4 * (L - 1)

            demand = route_demands[idx]

            # diversity factor based on how far node's demand is from route average
            diversity = abs(demand - avg_dem)
            if route_max != route_min:
                diversity_factor = diversity / (route_max - route_min)
                if diversity_factor > 2.0:
                    diversity_factor = 2.0
            else:
                diversity_factor = 0.0

            score = density * route_factor * (1.0 + diversity_factor)

            perturb = rng.random() * 0.05 * (1.0 + near_dist)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.14  # between 0.08 and 0.22
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

