    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Route-size factor: grows with route length
        route_factor = 1.0 + 0.25 * (L - 1)

        for node in non_dep:
            # Farthest distance to another node in the same route
            if L > 1:
                farthest = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if d > farthest:
                        farthest = d
            else:
                farthest = 0.0

            # Local density proxy: sum of inverse distances to others in the route
            if L > 1:
                sum_inv = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    sum_inv += 1.0 / (1.0 + distance_matrix[node][other])
            else:
                sum_inv = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            # Score combines farthest distance, route size, and damping by demand
            base = 0.0
            if L > 1:
                base = farthest / (1.0 + sum_inv)
            score = base * route_factor
            score /= (1.0 + 0.7 * demand)

            # Small random perturbation to diversify removal
            perturb = rng.random() * 0.05 * (farthest + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
