    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # Build route-graph: nodes are all non-depot nodes plus depot 0; edges connect consecutive nodes in each route
    adj = {}

    def add_edge(a, b):
        if a not in adj:
            adj[a] = set()
        if b not in adj:
            adj[b] = set()
        adj[a].add(b)
        adj[b].add(a)

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        path = [0] + non_dep + [0]
        for i in range(len(path) - 1):
            add_edge(path[i], path[i + 1])

    if 0 not in adj:
        adj[0] = set()

    all_nodes = set(adj.keys())
    # Initialize propagation vector
    x = {}
    for v in all_nodes:
        x[v] = 1.0
    x[0] = 1.0  # keep depot value fixed

    # Two iterations of a simple graph-propagation update using edge weights (distances)
    for _ in range(2):
        x_new = {}
        for v in all_nodes:
            if v == 0:
                x_new[0] = x[0]
                continue
            neigh = adj.get(v, set())
            denom = 0.0
            total = 0.0
            for u in neigh:
                w = distance_matrix[v][u]
                denom += w
                total += w * x[u]
            if denom > 0.0:
                x_new[v] = total / denom
            else:
                x_new[v] = x[v]
        x = x_new

    # Compute scores for each non-depot node
    scores = []
    total_non_dep = 0
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue
        total_non_dep += L
        factor = 1.0 + 0.25 * max(0, (L - 1))  # route-length factor

        for node in non_dep:
            demand = demands[node] if node < len(demands) else 0
            centrality = x[node]
            score = centrality * factor - 0.4 * demand
            perturb = rng.random() * 0.05 * (centrality + 1.0)
            score += perturb
            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.16  # between 0.07 and 0.23
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

