    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Determine route center: node with minimal sum of distances to others in the same route
        center = None
        if L > 0:
            center_sums = []
            for i in non_dep:
                s = 0.0
                for j in non_dep:
                    if j == i:
                        continue
                    # guard against out-of-range indices
                    if i < len(distance_matrix) and j < len(distance_matrix[i]):
                        s += distance_matrix[i][j]
                    else:
                        s += 0.0
                center_sums.append((i, s))
            center, _ = min(center_sums, key=lambda t: t[1])

        # Route-size factor: non-linear amplification with route length
        factor = 1.0 + 0.3 * (L - 1) ** 0.8

        for node in non_dep:
            # distance to route center (peripheral indicator)
            if center is not None and node < len(distance_matrix) and center < len(distance_matrix[node]):
                d_to_center = distance_matrix[node][center]
            else:
                d_to_center = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            # Score sizing: peripheral nodes get higher scores, tempered by demand
            score = d_to_center * factor / (1.0 + demand)

            # Small random perturbation for diversification
            perturb = rng.random() * 0.04 * (d_to_center + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
