        center = None
        if L > 0:
            best_sum = None
            for n in non_dep:
                s = 0.0
                for m in non_dep:
                    if m == n:
                        continue
                    s += distance_matrix[n][m]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    center = n

        for n in non_dep:
            # Lever is distance to route center (0 if center is None or same node)
            if center is None or n == center:
                lever = 0.0
            else:
                lever = distance_matrix[n][center]

            # Radius: max distance from node to any other node in the route
            if L > 1:
                max_dist = 0.0
                for other in non_dep:
                    if other == n:
                        continue
                    d = distance_matrix[n][other]
                    if d > max_dist:
                        max_dist = d
                radius = max_dist
            else:
                radius = 0.0

            demand = demands[n] if n < len(demands) else 0.0

            # Route-size factor amplifying influence for larger routes
            route_factor = 1.0 + 0.4 * (L - 1)

            score = (lever + radius) * route_factor
            score /= (1.0 + demand)

            perturb = rng.random() * 0.03 * (lever + radius + 1.0)
            score += perturb

            scores.append((n, score))

    if total_non_dep == 0:
        k = 0
