    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        cap = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        route_load = sum(demands[node] if node < len(demands) else 0 for node in non_dep)
        remaining_ratio = (cap - route_load) / cap if cap > 0 else 0.0
        if remaining_ratio < 0.0:
            remaining_ratio = 0.0
        if remaining_ratio > 1.0:
            remaining_ratio = 1.0

        # Identify medoid: node with minimal sum of distances to peers in this route
        medoid = None
        if L > 0:
            min_sum = None
            for i in non_dep:
                s = 0.0
                for j in non_dep:
                    if j == i:
                        continue
                    s += distance_matrix[i][j]
                if (min_sum is None) or (s < min_sum):
                    min_sum = s
                    medoid = i

        for i in non_dep:
            if medoid is None or i == medoid:
                d_to_med = 0.0
            else:
                d_to_med = distance_matrix[i][medoid] if (i < len(distance_matrix) and medoid < len(distance_matrix[i])) else 0.0

            base = (d_to_med ** 1.2) if L > 1 else 0.0
            diversity_factor = 1.0 + 0.15 * (L - 1)
            score = base * diversity_factor * (1.0 + 0.8 * remaining_ratio)
            perturb = rng.random() * 0.04 * (d_to_med + 1.0)
            score += perturb

