def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    # Build per-route node lists and mappings
    routes = current_solution
    route_nodes = []
    route_of_node = {}
    total_non_dep = 0

    for r_idx, route in enumerate(routes):
        non_dep = [n for n in route if n != 0]
        route_nodes.append(non_dep)
        for n in non_dep:
            route_of_node[n] = r_idx
        total_non_dep += len(non_dep)

    n_routes = len(route_nodes)

    # Per-route total demands
    route_demand = [0.0] * n_routes
    for r_idx, nodes in enumerate(route_nodes):
        s = 0.0
        for n in nodes:
            if n < len(demands):
                s += demands[n]
        route_demand[r_idx] = s

    # Local mean distance within each route for each node
    local_mean = {}
    for r_idx, nodes in enumerate(route_nodes):
        L = len(nodes)
        if L <= 1:
            for n in nodes:
                local_mean[n] = 0.0
        else:
            for i, node in enumerate(nodes):
                s = 0.0
                for j, other in enumerate(nodes):
                    if i == j:
                        continue
                    s += distance_matrix[node][other]
                local_mean[node] = s / (L - 1)

    # Global mean distance to nodes in other routes for each node
    global_mean = {}
    for node in route_of_node.keys():
        r = route_of_node[node]
        count = total_non_dep - len(route_nodes[r])
        if count <= 0:
            global_mean[node] = 0.0
        else:
            s = 0.0
            for other in route_of_node.keys():
                if route_of_node[other] != r:
                    s += distance_matrix[node][other]
            global_mean[node] = s / count

    # Compute score per node
    for r_idx, nodes in enumerate(route_nodes):
        L = len(nodes)
        Rd = route_demand[r_idx]
        for node in nodes:
            gm = global_mean.get(node, 0.0)
            lm = local_mean.get(node, 0.0)
            demand_node = demands[node] if node < len(demands) else 0.0
            demand_ratio = demand_node / (Rd + 1e-9)

            # New scoring: emphasis on global dispersion, route size, and demand context
            score = (gm + 1.0) ** 1.25
            score *= (1.0 + 0.75 * (L - 1))
            score *= (1.0 / (1.0 + 0.6 * demand_ratio))
            score += lm * 0.15

            perturb = rng.random() * 0.05 * (gm + lm + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.20  # between 0.08 and 0.28
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

