                    m2 = float('inf')
                    for d in dists:
                        if d < m1:
                            m2 = m1
                            m1 = d
                        elif d < m2:
                            m2 = d
                    mean_nearest = (m1 + m2) / 2.0
                elif len(dists) == 1:
                    mean_nearest = dists[0]
                else:
                    mean_nearest = 0.0
            else:
                mean_nearest = 0.0

            demand = demands[node] if node < len(demands) else 0

            # Score: mean distance to two closest intra-route neighbors raised to 1.3,
            # multiplied by route-length dampening, dampened by demand, plus perturbation
            score = (mean_nearest ** 1.3) * factor
            score /= (1.0 + 0.4 * demand)

            perturb = rng.random() * 0.08 * (mean_nearest + 0.5)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.04 + rng.random() * 0.25  # between 0.04 and 0.29
        k = max(1, int(round(total_non_dep * frac)))
