def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    # Precompute route statistics: non-depot nodes, route length, and route load
    max_route_size = 0
    max_node_demand = 0.0
    routes_info = []

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        route_load = 0.0
        for n in non_dep:
            if n < len(demands):
                route_load += demands[n]

        routes_info.append({'non_dep': non_dep, 'L': L, 'route_load': route_load})
        total_non_dep += L

        if L > max_route_size:
            max_route_size = L

        for n in non_dep:
            if n < len(demands):
                if demands[n] > max_node_demand:
                    max_node_demand = demands[n]

    if total_non_dep == 0:
        return scores, 0

    JITTER_SCALE = 0.04

    # Compute scores per node
    for info in routes_info:
        non_dep = info['non_dep']
        L = info['L']
        if L == 0:
            continue

        for node in non_dep:
            # mean distance to others in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            centrality = 1.0 / (1.0 + mean_distance)

            density = L / max_route_size if max_route_size > 0 else 0.0

            demand = demands[node] if node < len(demands) else 0.0
            demand_ratio = (demand / max_node_demand) if max_node_demand > 0 else 0.0

            score = centrality * (1.0 + 0.8 * density) * (1.0 + 0.7 * demand_ratio)

            jitter = rng.random() * JITTER_SCALE * (centrality + density + demand_ratio + 1.0)
            score += jitter

            scores.append((node, score))

    frac = 0.12 + rng.random() * 0.25  # between 0.12 and 0.37
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

