    all_non_dep = []
    for route in current_solution:
        for n in route:
            if n != 0:
                all_non_dep.append(n)
    total_non_dep = len(all_non_dep)

    # compute global mean-distance for each node (to all other non-depot nodes)
    global_mean = {}
    if total_non_dep > 1:
        for n in all_non_dep:
            s = 0.0
            for m in all_non_dep:
                if m == n:
                    continue
                if n < len(distance_matrix) and m < len(distance_matrix[n]):
                    s += distance_matrix[n][m]
                else:
                    s += 0.0
            global_mean[n] = s / (total_non_dep - 1)
    else:
        for n in all_non_dep:
            global_mean[n] = 0.0

    scores = []
    # score each node within its route
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue
        route_len_factor = 1.0 + 0.3 * (L - 1)

        for idx, node in enumerate(non_dep):
            gmean = global_mean.get(node, 0.0)
            if L > 1:
                position_weight = 1.0 + (idx / (L - 1)) * 0.6
            else:
                position_weight = 1.0

            demand = demands[node] if node < len(demands) else 0.0
            score = gmean * route_len_factor * position_weight / (1.0 + 0.5 * demand)

            perturb = rng.random() * 0.04 * (gmean + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
