        for idx, node in enumerate(non_dep):
            # Mean distance to peers in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            # Coverage: number of peers within the node's mean-distance radius
            coverage = 0
            for other in non_dep:
                if other == node:
                    continue
                if distance_matrix[node][other] <= mean_distance:
                    coverage += 1

            demand = demands[node] if node < len(demands) else 0.0

            # Score construction: mean distance scaled by route length and inverse by coverage,
            # boosted by route demand, plus random perturbation
            score = 0.0
            if coverage + 1.0 > 0:
                score = mean_distance * (L / (coverage + 1.0))
            else:
                score = mean_distance

            score *= (1.0 + 0.01 * route_demand)

            perturb = rng.random() * 0.05 * (mean_distance + coverage + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.22  # between 0.12 and 0.34
        k = max(1, int(round(total_non_dep * frac)))
