    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Vehicle capacity for this route
        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else (
            max(1, max(demands) if demands else 1)
        )
        route_demand = sum(demands[node] if node < len(demands) else 0 for node in non_dep)
        remaining_ratio = 0.0
        if capacity > 0:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0

        # Find 1-median center within the route
        center = None
        if L > 0:
            best_center = None
            best_sum = None
            for c in non_dep:
                s = 0.0
                for other in non_dep:
                    if other == c:
                        continue
                    s += distance_matrix[c][other]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    best_center = c
            center = best_center

        for node in non_dep:
            if center is not None and L > 1:
                dispersion = distance_matrix[node][center]
            else:
                dispersion = 0.0

            node_demand = demands[node] if node < len(demands) else 0

            route_slack = remaining_ratio

            score = (dispersion ** 1.4) * (1.0 + 0.6 * route_slack)
            score /= (1.0 + 0.8 * node_demand)

            perturb = rng.random() * 0.05 * (dispersion + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.18  # between 0.07 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

