    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    # Collect all non-depot nodes across all routes
    all_nodes = []
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        all_nodes.extend(non_dep)

    total_non_dep = len(all_nodes)

    # Precompute per-node route length (L) and route total demand (route_demand)
    node_to_L = {}
    node_to_route_demand = {}
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        # route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]
        for n in non_dep:
            node_to_L[n] = L
            node_to_route_demand[n] = route_demand

    if total_non_dep > 0:
        denom = total_non_dep - 1
    else:
        denom = 0

    for node in all_nodes:
        L = node_to_L.get(node, 1)
        route_demand = node_to_route_demand.get(node, 0.0)

        # Global mean distance: average distance from this node to all other non-depot nodes
        if denom > 0:
            s = 0.0
            for other in all_nodes:
                if other == node:
                    continue
                s += distance_matrix[node][other]
            mean_global_distance = s / denom
        else:
            mean_global_distance = 0.0

        demand = demands[node] if node < len(demands) else 0.0

        # Route-length factor
        factor = 1.0 + 0.4 * (L ** 0.6)

        # Score components
        score = (mean_global_distance ** 1.25) * factor

        # Demand-based damping (downweight high-demand nodes within their route)
        if route_demand > 0.0:
            score /= (1.0 + 0.9 * (demand / route_demand))

        # Small random perturbation for diversification
        perturb = rng.random() * 0.04 * (mean_global_distance + 1.0)
        score += perturb

        scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.24  # between 0.12 and 0.36
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # Potential distance saving if removing this node and bypassing its neighbors
            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0

            # Mean distance from this node to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            # Bridge-based disruption term
            bridge_score = 0.0
            if L > 1:
                left_nodes = non_dep[:idx]
                right_nodes = non_dep[idx+1:]
                if left_nodes:
                    ls = 0.0
                    for other in left_nodes:
                        ls += distance_matrix[node][other]
                    left_mean = ls / len(left_nodes)
                else:
                    left_mean = 0.0
                if right_nodes:
                    rs = 0.0
                    for other in right_nodes:
                        rs += distance_matrix[node][other]
                    right_mean = rs / len(right_nodes)
                else:
                    right_mean = 0.0
                bridge_score = abs(left_mean - right_mean)
            else:
                bridge_score = 0.0

            depot_distance = distance_matrix[node][0]

            demand = demands[node] if node < len(demands) else 0.0

            # New scoring combination
            score = saving * (1.0 + 0.4 * (L - 1)) + 2.0 * bridge_score
            if route_demand > 0.0:
                score *= 1.0 / (1.0 + 0.4 * (demand / route_demand))
            # mean-distance penalty to favor nodes with large intra-route distances
            score *= (1.0 / (1.0 + 0.9 * mean_distance))
            # small depot influence
            score += 0.001 * depot_distance

            perturb = rng.random() * 0.04 * (saving + bridge_score + mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.22  # between 0.08 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

