    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    # Build set of all non-depot nodes present in the solution
    all_nodes_set = set()
    for route in current_solution:
        for n in route:
            if n != 0:
                all_nodes_set.add(n)
    all_nodes = sorted(all_nodes_set)
    n_all = len(all_nodes)

    # Precompute global mean distance to all other non-depot nodes for each node
    global_mean = {}
    if n_all > 1:
        for node in all_nodes:
            s = 0.0
            for other in all_nodes:
                if other == node:
                    continue
                s += distance_matrix[node][other]
            global_mean[node] = s / (n_all - 1)
    else:
        for node in all_nodes:
            global_mean[node] = 0.0

    # Compute scores per node within each route
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        for node in non_dep:
            # intra-route mean distance
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                intra_mean = s / (L - 1)
            else:
                intra_mean = 0.0

            # dispersion between global and local distances
            g_mean = global_mean.get(node, 0.0)
            dispersion = g_mean - intra_mean
            if dispersion < 0:
                dispersion = -dispersion

            # route size factor
            route_size_factor = 1.0 + 0.25 * ((L - 1) ** 0.5)

            # demand dampening
            node_demand = demands[node] if node < len(demands) else 0.0
            demand_damp = 1.0 / (1.0 + 0.6 * node_demand)

            score = dispersion * route_size_factor * demand_damp

            # small random perturbation
            perturb = rng.random() * 0.04 * (dispersion + intra_mean + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.06 + rng.random() * 0.18  # between 0.06 and 0.24
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

