        route_demand = sum(demands[node] if node < len(demands) else 0 for node in non_dep)
        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        if capacity <= 0:
            remaining_ratio = 0.0
        else:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0

        # For each node, compute sum of distances to its two closest peers in the same route
        for i in non_dep:
            min1 = float('inf')
            min2 = float('inf')
            for other in non_dep:
                if other == i:
                    continue
                d = distance_matrix[i][other]
                if d < min1:
                    min2 = min1
                    min1 = d
                elif d < min2:
                    min2 = d

            if min1 == float('inf'):
                sum_closest = 0.0
            elif min2 == float('inf'):
                sum_closest = min1
            else:
                sum_closest = min1 + min2

            demand = demands[i] if i < len(demands) else 0

            # Route-size factor: varies with route length
            size_factor = 1.0 + 0.6 * ((L - 1) ** 0.5)

            # Score combines neighborhood distance, route size, remaining capacity, and demand
            score = sum_closest * size_factor
            score *= (1.0 + 0.7 * (1.0 - remaining_ratio))
