    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # Potential distance saving if removing this node and bypassing its neighbors
            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0

            # Mean distance from this node to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            # Max distance to other nodes in route (for peripheral measure)
            max_dist = 0.0
            if L > 1:
                md = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if d > md:
                        md = d
                max_dist = md
            else:
                max_dist = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            # Peripheral (centrality) factor: higher when node is more peripheral in the route
            peripheral = 0.0
            if L > 1 and max_dist > 0.0:
                peripheral = (max_dist - mean_distance) / max_dist
            elif L > 1:
                peripheral = 1.0
            else:
                peripheral = 0.0

            # Route length factor
            route_factor = 1.0 + 0.8 * (L - 1)

            # Demand penalty factor: penalize removing high-demand nodes within high-demand routes
            demand_factor = 1.0 - (demand / (route_demand + 1e-12))

            score = saving * route_factor * demand_factor * (1.0 + 0.6 * peripheral)

            # Random jitter to diversify selection
            perturb = rng.random() * 0.05 * (saving + mean_distance + 1.0 + peripheral)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.18  # between 0.12 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    # compute average capacity for demand penalty normalization
    if capacities:
        avg_capacity = sum(capacities) / len(capacities)
    else:
        avg_capacity = 1.0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route-size factor (modified growth)
        factor = 1.0 + 0.5 * (L ** 0.6)

        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            demand = demands[node] if node < len(demands) else 0
            if demand > 0:
                demand_penalty = 1.0 + 0.6 * ((demand / avg_capacity) ** 0.8)
            else:
                demand_penalty = 1.0

            score = (mean_distance ** 0.9) * factor
            score /= demand_penalty

            perturb = rng.random() * 0.06 * (mean_distance + 1.0)
