    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Vehicle capacity for this route (cycle through capacities if needed)
        cap = 1
        if len(capacities) > 0:
            cap = capacities[min(r_idx, len(capacities) - 1)]
            if cap <= 0:
                cap = 1

        for node in non_dep:
            if L > 1:
                s = 0.0
                max_distance = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    s += d
                    if d > max_distance:
                        max_distance = d
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0
                max_distance = 0.0

            demand = demands[node] if node < len(demands) else 0
            demand_factor = demand / cap if cap > 0 else 0.0

            if L > 1:
                base = (max_distance / (mean_distance + 1.0)) ** 0.9
            else:
                base = 0.0

            factor = 1.0 + 0.3 * ((L - 1) ** 0.5)
            score = base * factor * (1.0 + demand_factor)

            perturb = rng.random() * 0.05 * (max_distance + 1.0)
            score += perturb

