def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for ridx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Route capacity: prefer per-route capacity if available, else use max capacity, else 1
        if ridx < len(vehicle_caps):
            capacity = vehicle_caps[ridx]
        elif len(vehicle_caps) > 0:
            capacity = max(vehicle_caps)
        else:
            capacity = 1

        # Total demand on this route
        total_demand_in_route = 0
        for n in non_dep:
            if n < len(demands):
                total_demand_in_route += demands[n]

        slack = 0.0
        if capacity > 0:
            slack = max(0.0, capacity - total_demand_in_route) / float(capacity)

        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)

                max_dist = max(distance_matrix[node][other] for other in non_dep if other != node)
            else:
                mean_distance = 0.0
                max_dist = 0.0

            demand = demands[node] if node < len(demands) else 0

            base = (mean_distance ** 0.85) * 0.6
            base += (max_dist ** 0.6) * 0.25
            base += slack * 1.0
            score = base - (demand * 0.15)

            perturb = rng.random() * 0.05 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.04 + rng.random() * 0.12  # between 0.04 and 0.16
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Gather non-depot nodes per route
    routes_non_dep = []
    total_non_dep = 0
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        routes_non_dep.append(non_dep)
        total_non_dep += len(non_dep)

    scores = []

    for r_idx, non_dep in enumerate(routes_non_dep):
        L = len(non_dep)
        if L == 0:
            continue

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for node in non_dep:
            # Cross-route isolation: sum of min distances to each other route
            cross_distance_sum = 0.0
            for other_r_idx, other_non_dep in enumerate(routes_non_dep):
                if other_r_idx == r_idx or len(other_non_dep) == 0:
                    continue
                min_to_route = None
                for other_node in other_non_dep:
                    d = distance_matrix[node][other_node]
                    if min_to_route is None or d < min_to_route:
                        min_to_route = d
                if min_to_route is None:
                    min_to_route = 0.0
                cross_distance_sum += min_to_route

            # Intra-route mean distance to others
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                intra_mean = s / (L - 1)
            else:
                intra_mean = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            # Damp by route demand (larger route demand reduces incentive to remove high-demand node)
            damp = 1.0 / (1.0 + 0.5 * (demand / route_demand)) if route_demand > 0.0 else 1.0

            # Score combining cross-route isolation (0.6) and intra-route proximity (0.3)
            score = cross_distance_sum * 0.6 + intra_mean * 0.3
            score *= damp

            # Small perturbation to diversify removals
            perturb = rng.random() * 0.04 * (cross_distance_sum + intra_mean + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.23  # between 0.07 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # Gather all non-depot nodes present in the solution
    all_nodes_set = set()
    for route in current_solution:
        for n in route:
            if n != 0:
                all_nodes_set.add(n)
    all_nodes = sorted(all_nodes_set)

    if not all_nodes:
        return scores, 0

    # Select a small set of random pivots ( Pivot-based global view )
    MAX_PIVOTS = 5
    P = min(MAX_PIVOTS, len(all_nodes))
    pivots = []
    if P > 0:
        pivots = list(rng.choice(all_nodes, size=P, replace=False))

    # Precompute average distance to pivots for each node
    node_to_pivot_avg = {}
    for node in all_nodes:
        if len(pivots) == 0:
            avg = 0.0
        else:
            s = 0.0
            for pv in pivots:
                if node < len(distance_matrix) and pv < len(distance_matrix[node]):
                    s += distance_matrix[node][pv]
            avg = s / len(pivots)
        node_to_pivot_avg[node] = avg

    ALPHA_ROUTE_LEN = 0.8  # route-length influence
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route total demand (used as a potential penalty)
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for node in non_dep:
            pivot_avg = node_to_pivot_avg.get(node, 0.0)
            factor = 1.0 + ALPHA_ROUTE_LEN * (L - 1)

            demand = demands[node] if node < len(demands) else 0.0

            # Score with a pivot-based global view, penalize high-demand nodes
            score = (pivot_avg * factor) / (1.0 + 0.7 * demand)

            # Small random jitter to diversify removals
            jitter = rng.random() * 0.25 * (pivot_avg + factor + 1.0)
            score += jitter

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Identify endpoints of the route's diameter (max distance pair) if possible
        if L >= 2:
            max_dist = -1.0
            end_a, end_b = non_dep[0], non_dep[1]
            for i_idx in range(L):
                i_node = non_dep[i_idx]
                row = distance_matrix[i_node]
                for j_idx in range(i_idx + 1, L):
                    j_node = non_dep[j_idx]
                    d = row[j_node]
                    if d > max_dist:
                        max_dist = d
                        end_a, end_b = i_node, j_node
        else:
            end_a = end_b = None

        # Route size factor
        if L >= 2:
            factor = 1.0 + 0.4 * (L - 1) ** 0.5
        else:
            factor = 1.0

        for node in non_dep:
            if L >= 2:
                mean_to_endpoints = (distance_matrix[node][end_a] + distance_matrix[node][end_b]) / 2.0
            else:
                mean_to_endpoints = 0.0

            demand = demands[node] if node < len(demands) else 0

            score = mean_to_endpoints * (factor ** 1.2)
            score /= (1.0 + 0.4 * demand)

            perturb = rng.random() * 0.05 * (mean_to_endpoints + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.24  # between 0.08 and 0.32
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    heat = {}
    sum_w = {}
    route_len = {}
    total_non_dep = 0

    # accumulate heat and per-node weight sums per route
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        for node in non_dep:
            if node not in heat:
                heat[node] = 0.0
            if node not in sum_w:
                sum_w[node] = 0.0
            route_len[node] = L

        for idx, i in enumerate(non_dep):
            for jdx, j in enumerate(non_dep):
                if idx == jdx:
                    continue
                d = distance_matrix[i][j]
                w = 1.0 / (1.0 + d)
                heat[i] += w
                sum_w[i] += w

    # compute scores for all nodes based on accumulated heat
    for node in heat:
        L = route_len.get(node, 1)
        d = demands[node] if node < len(demands) else 0
        base = heat[node]
        score = base * (1.0 + 0.3 * (L - 1)) / (1.0 + d)

        perturb = rng.random() * 0.05 * (sum_w.get(node, 0.0) + heat[node] + 1.0)
        score += perturb

        scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.06 + rng.random() * 0.24  # between 0.06 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Collect all non-depot nodes and route assignments
    all_nodes = []
    route_of_node = {}
    route_lengths = []

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        route_lengths.append(L)
        for node in non_dep:
            all_nodes.append(node)
            route_of_node[node] = r_idx

    N = len(all_nodes)
    if N == 0:
        return [], 0

    # Precompute total distance from each node to all other non-depot nodes
    total_to_others = {}
    for node in all_nodes:
        s = 0.0
        for other in all_nodes:
            if other == node:
                continue
            s += distance_matrix[node][other]
        total_to_others[node] = s

    # Precompute intra-route sums (distance to peers in the same route)
    intra_sum = {node: 0.0 for node in all_nodes}
    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        for node in non_dep:
            for other in non_dep:
                if other == node:
                    continue
                intra_sum[node] += distance_matrix[node][other]

    # Compute per-node statistics
    global_mean = {}
    intra_mean = {}
    outside_mean = {}
    for node in all_nodes:
        r_idx = route_of_node[node]
        L = route_lengths[r_idx]
        # global mean distance to all other nodes
        global_mean[node] = total_to_others[node] / max(1, N - 1)
        # mean distance to peers in the same route
        intra_mean[node] = intra_sum[node] / max(1, (L - 1))
        # mean distance to nodes not in the same route
        outside_sum = total_to_others[node] - intra_sum[node]
        outside_mean[node] = outside_sum / max(1, N - L)

    # Compute scores
    scores = []
    for node in all_nodes:
        r_idx = route_of_node[node]
        L = route_lengths[r_idx]
        diff = global_mean[node] - intra_mean[node]  # potential cross-route isolation
        score = diff * (1.0 + 0.6 * (L - 1)) + outside_mean[node] * 0.9
        perturb = rng.random() * 0.05 * (abs(diff) + outside_mean[node] + intra_mean[node] + 1.0)
        score += perturb
        scores.append((node, score))

    # Determine k: number of nodes to remove
    total_non_dep = N
    frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Collect all non-depot nodes present in the solution
    nodes = []
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        for n in non_dep:
            if n not in nodes:
                nodes.append(n)
    total_non_dep = len(nodes)

    if total_non_dep == 0:
        return [], 0

    # Build degree map from the route graph: connect consecutive non-depot nodes
    deg = {n: 0 for n in nodes}
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        for i in range(len(non_dep) - 1):
            a = non_dep[i]
            b = non_dep[i + 1]
            deg[a] = deg.get(a, 0) + 1
            deg[b] = deg.get(b, 0) + 1

    endpoint = {n: (deg[n] == 1) for n in nodes}

    scores = []
    # Compute scores based on global distance sums, with endpoint and demand adjustments
    for i in nodes:
        dist_sum = 0.0
        row = distance_matrix[i]
        for j in nodes:
            if i == j:
                continue
            dist_sum += row[j]

        demand_i = demands[i] if i < len(demands) else 0.0

        score = dist_sum
        if endpoint[i]:
            score *= 1.5  # endpoints are more influential to remove
        score /= (1.0 + demand_i)

        perturb = rng.random() * 0.2 * (dist_sum + 1.0)
        score += perturb

        scores.append((i, score))

    # Determine k: number of nodes to remove (a small random fraction of total non-depot nodes)
    frac = 0.04 + rng.random() * 0.10  # between 0.04 and 0.14
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    capacities = data.get('vehicle_capacities', [])
    max_capacity = max(capacities) if capacities else 0

    scores = []
    total_non_dep = 0

    # Collect all non-depot nodes across all routes
    all_non_dep = []
    for route in current_solution:
        for node in route:
            if node != 0:
                all_non_dep.append(node)
    total_non_dep = len(all_non_dep)

    # Pre-compute mean distance to all other non-depot nodes for each node
    mean_all_dist = {}
    if total_non_dep > 0:
        for node in all_non_dep:
            s = 0.0
            for other in all_non_dep:
                if other == node:
                    continue
                s += distance_matrix[node][other]
            mean_all_dist[node] = s / (total_non_dep - 1) if total_non_dep > 1 else 0.0

    # Compute scores per node based on global mean distance and route utilization
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for node in non_dep:
            mean_all = mean_all_dist.get(node, 0.0)

            # Route utilization factor dampens score for highly utilized routes
            if max_capacity > 0 and route_demand > 0:
                cap_ratio = route_demand / max_capacity
                utilization_factor = max(0.0, 1.0 - 0.6 * cap_ratio)
            else:
                utilization_factor = 1.0

            score = mean_all * utilization_factor

            # Small random perturbation for diversification
            perturb = rng.random() * 0.05 * (mean_all + 1.0)
            score += perturb

            scores.append((node, score))

    # Determine how many nodes to remove
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.20  # between 0.10 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route-length-oriented scaling factor
        factor = 1.0 + 0.3 * (L - 1)

        max_window = 2  # look at up to 2 neighbors on each side in the route order
        for idx, node in enumerate(non_dep):
            neighbor_nodes = []
            for d in range(1, max_window + 1):
                if idx - d >= 0:
                    neighbor_nodes.append(non_dep[idx - d])
                if idx + d < L:
                    neighbor_nodes.append(non_dep[idx + d])

            if neighbor_nodes:
                s = 0.0
                for other in neighbor_nodes:
                    s += distance_matrix[node][other]
                mean_local = s / len(neighbor_nodes)
            else:
                mean_local = 0.0

            demand = demands[node] if node < len(demands) else 0
            demand_penalize = 1.0 / (1.0 + (demand ** 0.5)) if demand > 0 else 1.0

            score = mean_local * factor * demand_penalize

            perturb = rng.random() * 0.05 * (mean_local + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.20  # between 0.10 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Total demand for this route
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # Distances from this node to peers in the same route (excluding itself)
            if L > 1:
                dists = []
                for other in non_dep:
                    if other == node:
                        continue
                    dists.append(distance_matrix[node][other])
                if len(dists) == 0:
                    mean_distance = 0.0
                    variance = 0.0
                else:
                    mean_distance = sum(dists) / len(dists)
                    var_sum = 0.0
                    for dist in dists:
                        diff = dist - mean_distance
                        var_sum += diff * diff
                    variance = var_sum / len(dists)
            else:
                mean_distance = 0.0
                variance = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            # Demand gap factor: how much of the route's demand would remain if removing this node
            if route_demand > 0.0:
                demand_gap = (route_demand - demand) / route_demand
            else:
                demand_gap = 0.0

            # Dispersion-based score: combine dispersion, mean distance, and demand gap
            score = (variance + mean_distance) * (1.0 + 0.5 * (L - 1))
            score *= (1.0 + demand_gap)

            # Small random perturbation for diversification
            perturb = rng.random() * 0.04 * (mean_distance + variance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.20  # between 0.12 and 0.32
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_nodes = 0

    # Precompute global list of all non-depot nodes
    global_nodes = []
    for route in current_solution:
        for node in route:
            if node != 0:
                global_nodes.append(node)

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_nodes += L

        # Route-size factor grows with route length
        factor = 1.0 + (L ** 0.5) * 0.5

        for node in non_dep:
            # Mean distance to peers within the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_in_route = s / (L - 1)
            else:
                mean_in_route = 0.0

            # Mean distance to all non-depot nodes globally (excluding itself)
            denom = len(global_nodes) - 1
            if denom > 0:
                s2 = 0.0
                for g in global_nodes:
                    if g == node:
                        continue
                    s2 += distance_matrix[node][g]
                mean_global = s2 / denom
            else:
                mean_global = 0.0

            demand = demands[node] if node < len(demands) else 0

            base = mean_in_route - mean_global
            if base < 0.0:
                base = 0.0

            score = base * factor
            score /= (1.0 + 0.4 * demand)

            perturb = rng.random() * 0.05 * (mean_in_route + mean_global + 1.0)
            score += perturb

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.20  # between 0.05 and 0.25
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

