            continue

        cap = vehicle_capacities[idx] if idx < len(vehicle_capacities) else 1
        demand_sum = 0
        for n in non_dep:
            demand_sum += demands[n] if n < len(demands) else 0
        utilization = 0.0 if cap == 0 else (demand_sum / cap)
        utilization = max(0.0, min(1.0, utilization))

        factor = 0.4 + 0.6 * (1.0 - utilization)

        for node in non_dep:
            distances = []
            for other in non_dep:
                if other == node:
                    continue
                distances.append(distance_matrix[node][other])

            if len(distances) == 0:
                mean_nearest = 0.0
            else:
                min1 = float('inf')
                min2 = float('inf')
                for d in distances:
                    if d < min1:
                        min2 = min1
                        min1 = d
                    elif d < min2:
                        min2 = d
                if len(distances) >= 2:
                    mean_nearest = (min1 + min2) / 2.0
                else:
                    mean_nearest = min1

            demand = demands[node] if node < len(demands) else 0
            score = (mean_nearest ** 1.05) * factor
            score /= (1.0 + 0.4 * demand)

            perturb = rng.random() * 0.05 * (mean_nearest + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
