        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Route demand and capacity
        route_demand = 0
        for node in non_dep:
            if node < len(demands):
                route_demand += demands[node]

        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        if capacity <= 0:
            remaining_ratio = 0.0
        else:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0

        # Medoid-based center for the route
        center_node = None
        if L > 0:
            best_center = non_dep[0]
            best_sum = float('inf')
            for cand in non_dep:
                s = 0.0
                for other in non_dep:
                    if other == cand:
                        continue
                    s += distance_matrix[cand][other]
                if s < best_sum:
                    best_sum = s
                    best_center = cand
            center_node = best_center

        # Diversity-like factor (different form from original)
        diversity = 1.0 + 0.04 * (L - 1)

        Lm1 = L - 1
        for node in non_dep:
