                    s += distance_matrix[node][other]
                mean_to_others = s / Lm1

            node_demand = demands[node] if node < len(demands) else 0

            load_factor = 1.0 + 0.8 * (1.0 - remaining_ratio)

            base = (distance_to_center + 0.5) * (mean_to_others + 1.0)
            score = base * diversity * load_factor
            score /= (1.0 + 0.6 * node_demand)

            perturb = rng.random() * 0.04 * (distance_to_center + mean_to_others + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.25  # between 0.10 and 0.35
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

