        total_non_dep += L

        if L == 0:
            continue

        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # Determine route center (centroid-like) as node with minimum sum distance to others
        if L > 1:
            best_center = non_dep[0]
            min_sum = None
            for c in non_dep:
                s = 0.0
                for o in non_dep:
                    if o == c:
                        continue
                    s += distance_matrix[c][o]
                if (min_sum is None) or (s < min_sum):
                    min_sum = s
                    best_center = c
            center_node = best_center
        else:
            center_node = non_dep[0]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0

            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
