                mean_distance = 0.0

            distance_to_center = distance_matrix[node][center_node] if center_node is not None else 0.0

            demand = demands[node] if node < len(demands) else 0.0

            score = saving * (1.0 + 0.75 * (L - 1))

            if route_demand > 0.0:
                score += 0.9 * (demand / route_demand)

            score *= (1.0 / (1.0 + mean_distance * 0.8 + distance_to_center * 0.6))

            perturb = rng.random() * 0.04 * (saving + mean_distance + distance_to_center + 1.0)
            score += perturb

