def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Build per-route non-depot lists and a mapping from node to its route index
    route_non_dep = []
    node_to_route = {}
    total_non_dep = 0
    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        route_non_dep.append(non_dep)
        for node in non_dep:
            node_to_route[node] = r_idx
        total_non_dep += len(non_dep)

    scores = []

    # Compute scores for each node
    for r_idx, non_dep in enumerate(route_non_dep):
        L = len(non_dep)
        if L == 0:
            continue

        # Precompute mean intra-route distances for nodes in this route
        mean_intra = {}
        if L > 1:
            for node in non_dep:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_intra[node] = s / (L - 1)
        else:
            mean_intra[non_dep[0]] = 0.0

        # Compute score for each node in this route
        for node in non_dep:
            # Cross-route isolation: minimum distance to any node in a different route
            cross_min = float('inf')
            for other_node, other_route in node_to_route.items():
                if other_route != r_idx:
                    d = distance_matrix[node][other_node]
                    if d < cross_min:
                        cross_min = d
            if cross_min == float('inf'):
                cross_min = 0.0

            mean_intra_val = mean_intra[node]
            demand = demands[node] if node < len(demands) else 0
            route_factor = 1.0 + 0.25 * (L - 1)

            score = (mean_intra_val * cross_min) * route_factor
            score = score / (1.0 + demand)

            perturb = rng.random() * 0.05 * (mean_intra_val + cross_min + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.20  # between 0.10 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

