def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []

    # Map each non-depot node to its route and collect all non-depot nodes
    route_of = {}
    all_nodes = []
    for r_idx, route in enumerate(current_solution):
        for node in route:
            if node == 0:
                continue
            route_of[node] = r_idx
            all_nodes.append(node)

    total_non_dep = len(all_nodes)

    if total_non_dep == 0:
        return scores, 0

    # Compute mean distance among all non-depot node pairs to define radius R
    sum_dist = 0.0
    count = 0
    for a_idx in range(total_non_dep):
        i = all_nodes[a_idx]
        for b_idx in range(a_idx + 1, total_non_dep):
            j = all_nodes[b_idx]
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                d = distance_matrix[i][j]
            else:
                d = 0.0
            sum_dist += d
            count += 1
    mean_dist = (sum_dist / count) if count > 0 else 0.0
    R = mean_dist * 0.75

    # Compute cross-route scores
    for i in all_nodes:
        s = 0.0
        ri = route_of[i]
        for j in all_nodes:
            if j == i:
                continue
            if route_of.get(j, -1) == ri:
                continue
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                d = distance_matrix[i][j]
            else:
                d = 0.0
            demand_j = demands[j] if j < len(demands) else 0
            contrib = R - d
            if contrib < 0:
                contrib = 0.0
            s += contrib / (1.0 + demand_j)

        perturb = rng.random() * 0.01 * (s + 1.0)
        s += perturb
        scores.append((i, s))

    frac = 0.05 + rng.random() * 0.25  # between 0.05 and 0.30
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    routes = current_solution

    N = len(distance_matrix)
    if N == 0:
        return [], 0

    # First pass: compute per-route non-depot lists, lengths, total count, and max route length
    route_info = []
    total_non_dep = 0
    max_route_len = 0
    for route in routes:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        route_info.append((route, non_dep, L))
        total_non_dep += L
        if L > max_route_len:
            max_route_len = L

    scores = []

    # Second pass: compute scores for each non-depot node
    for route, non_dep, L in route_info:
        if L == 0:
            continue

        diversity = 1.0
        if max_route_len > 0:
            if L > 1:
                diversity = 1.0 + 0.5 * ((L - 1) / max_route_len)
            else:
                diversity = 1.0

        for node in non_dep:
            if N > 1:
                sum_dist = 0.0
                for j in range(N):
                    if j == node:
                        continue
                    if node < N and j < N:
                        d = distance_matrix[node][j]
                    else:
                        d = 0.0
                    sum_dist += d
                mean_distance = sum_dist / (N - 1)
            else:
                mean_distance = 0.0

            node_demand = demands[node] if node < len(demands) else 0
            score = mean_distance * diversity / (1.0 + node_demand)
            perturb = rng.random() * 0.05 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # Collect all non-depot nodes (unique) to compute global means
    all_nodes = []
    seen = set()
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        for n in non_dep:
            if n not in seen:
                seen.add(n)
                all_nodes.append(n)
    N_all = len(all_nodes)

    # Precompute global mean distance to all other non-depot nodes
    global_mean_dist = {}
    for i in all_nodes:
        if N_all <= 1:
            global_mean_dist[i] = 0.0
        else:
            s = 0.0
            for j in all_nodes:
                if j == i:
                    continue
                d = distance_matrix[i][j] if (i < len(distance_matrix) and j < len(distance_matrix[i])) else 0.0
                s += d
            global_mean_dist[i] = s / (N_all - 1)

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue
        total_non_dep += L

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # Potential distance saving if removing this node and bypassing its neighbors
            saving = 0.0
            if prev_node is not None and next_node is not None:
                d_prev_i = distance_matrix[prev_node][node] if (prev_node < len(distance_matrix) and node < len(distance_matrix[prev_node])) else 0.0
                d_i_next = distance_matrix[node][next_node] if (node < len(distance_matrix) and next_node < len(distance_matrix[node])) else 0.0
                d_prev_next = distance_matrix[prev_node][next_node] if (prev_node < len(distance_matrix) and next_node < len(distance_matrix[prev_node])) else 0.0
                saving = d_prev_i + d_i_next - d_prev_next
                if saving < 0.0:
                    saving = 0.0

            # Mean distance from this node to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other] if (node < len(distance_matrix) and other < len(distance_matrix[node])) else 0.0
                    s += d
                mean_dist_in_route = s / (L - 1)
            else:
                mean_dist_in_route = 0.0

            demand = demands[node] if node < len(demands) else 0.0
            g_mean = global_mean_dist.get(node, 0.0)

            # Score components (differs from prior schemes to emphasize cross-route and local-global contrasts)
            score = 0.9 * saving
            score += 0.8 * (mean_dist_in_route - g_mean)
            if route_demand > 0.0:
                score += 0.6 * (demand / (route_demand + 1e-9))

            # Small random perturbation for diversification
            perturb = rng.random() * 0.03 * (saving + mean_dist_in_route + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.25  # between 0.10 and 0.35
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # Determine route center by minimal sum of distances to others
        if L > 0:
            sum_dist = {}
            for node in non_dep:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                sum_dist[node] = s
            center_node = min(non_dep, key=lambda x: sum_dist[x])
        else:
            center_node = None

        for idx, node in enumerate(non_dep):
            # Mean distance to peers
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            dist_to_center = distance_matrix[node][center_node] if center_node is not None else 0.0

            # Score components (new form: peripheral emphasis + demand balance + randomness)
            periphery = dist_to_center + 1.0
            score = (periphery ** 0.8)
            score *= (1.0 / (1.0 + mean_distance * 0.5))

            if route_demand > 0.0:
                denom = route_demand + 1e-9
                r = demands[node] / denom
                score *= (1.0 / (1.0 + (r) ** 0.9))

            perturb = rng.random() * 0.05 * (dist_to_center + mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.1 + rng.random() * 0.15  # between 0.1 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    all_nodes = []

    # collect all non-depot nodes
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        if non_dep:
            all_nodes.extend(non_dep)

    total_non_dep = len(all_nodes)

    if total_non_dep == 0:
        return scores, 0

    # precompute sum of inverse distances to all other non-depot nodes
    node_to_sum_inv = {}
    for node in all_nodes:
        s = 0.0
        for other in all_nodes:
            if other == node:
                continue
            d = distance_matrix[node][other]
            s += 1.0 / (d + 1e-6)
        node_to_sum_inv[node] = s

    # compute per-route statistics and scores
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        # route demand
        route_demand = 0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # route max distance within the route
        max_dist = 0.0
        for i in range(L):
            a = non_dep[i]
            for j in range(i + 1, L):
                b = non_dep[j]
                d = distance_matrix[a][b]
                if d > max_dist:
                    max_dist = d

        # route centroid: node with minimal sum of distances to others in the route
        centroid = None
        best_sum = None
        if L > 1:
            for i in range(L):
                n = non_dep[i]
                s = 0.0
                for j in range(L):
                    if i == j:
                        continue
                    s += distance_matrix[n][non_dep[j]]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    centroid = n
        else:
            centroid = non_dep[0]

        # route_size_factor grows with route length
        route_size_factor = 1.0
        if L > 1:
            route_size_factor = 1.0 + 0.4 * ((L - 1) ** 0.5)

        # per-node scores
        for node in non_dep:
            sum_inv = node_to_sum_inv.get(node, 0.0)
            dist_to_centroid = distance_matrix[node][centroid] if centroid is not None else 0.0
            if max_dist > 0.0:
                coherence = 1.0 - (dist_to_centroid / (max_dist + 1e-6))
                if coherence < 0.0:
                    coherence = 0.0
                if coherence > 1.0:
                    coherence = 1.0
            else:
                coherence = 1.0

            demand = demands[node] if node < len(demands) else 0
            demand_factor = 1.0 / (1.0 + demand)

            score = sum_inv * (1.0 + 0.5 * coherence) * route_size_factor * demand_factor

            perturb = rng.random() * 0.05 * (sum_inv + 1.0)
            score += perturb

            scores.append((node, score))

    # compute k
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.16  # between 0.12 and 0.28
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Prepare per-route non-depot node lists
    non_dep_per_route = []
    total_non_dep = 0
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        non_dep_per_route.append(non_dep)
        total_non_dep += len(non_dep)

    scores = []

    for i, route in enumerate(current_solution):
        non_dep = non_dep_per_route[i]
        L = len(non_dep)
        if L == 0:
            continue

        # For each node in this route, compute cross-route and intra-route components
        for node in non_dep:
            # Cross-route component: sum of distances to nearest node in each other route
            cross_sum = 0.0
            for j, other_nodes in enumerate(non_dep_per_route):
                if j == i:
                    continue
                if not other_nodes:
                    # Fallback to depot distance if the other route has no non-depot nodes
                    cross_sum += distance_matrix[node][0]
                else:
                    # distance to nearest node in other route
                    md = distance_matrix[node][other_nodes[0]]
                    for other in other_nodes[1:]:
                        d = distance_matrix[node][other]
                        if d < md:
                            md = d
                    cross_sum += md

            # Intra-route locality: distance to the two nearest neighbors within the same route
            if L > 1:
                dists = []
                for other in non_dep:
                    if other == node:
                        continue
                    dists.append(distance_matrix[node][other])
                if len(dists) >= 2:
                    dists.sort()
                    intra = (dists[0] + dists[1]) / 2.0
                elif len(dists) == 1:
                    intra = dists[0]
                else:
                    intra = 0.0
            else:
                intra = 0.0

            depot_dist = distance_matrix[node][0]
            node_demand = demands[node] if node < len(demands) else 0.0

            # Score combination and damping by demand
            score = cross_sum * 0.5 + intra * 0.4 + depot_dist * 0.2
            score /= (1.0 + 0.8 * node_demand)

            # Small random perturbation
            perturb = rng.random() * 0.05 * (cross_sum + intra + depot_dist + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.35  # between 0.15 and 0.50
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    capacities = data.get('vehicle_capacities', [])
    max_capacity = max(capacities) if capacities else 1

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Compute total demand for this route
        route_demand = 0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # Find route center: node with minimal sum of distances to other nodes in the route
        if L > 0:
            center = non_dep[0]
            min_sum = None
            for cand in non_dep:
                s = 0.0
                for other in non_dep:
                    if other == cand:
                        continue
                    s += distance_matrix[cand][other]
                if (min_sum is None) or (s < min_sum):
                    min_sum = s
                    center = cand
        else:
            center = None

        for node in non_dep:
            dist_to_center = distance_matrix[node][center] if center is not None else 0.0
            score = dist_to_center * dist_to_center  # squared distance to center

            if max_capacity > 0:
                score *= (1.0 + route_demand / max_capacity)

            perturb = rng.random() * 0.05 * (dist_to_center + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.24  # between 0.08 and 0.32
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Gather all non-depot nodes present in the current solution and track routes with nodes
    all_nodes = []
    routes_with_nodes = 0
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        if non_dep:
            routes_with_nodes += 1
            all_nodes.extend(non_dep)

    total_non_dep = len(all_nodes)
    if total_non_dep == 0:
        return [], 0

    # Initialize each node as its own cluster
    clusters = [ {node} for node in all_nodes ]
    target_clusters = routes_with_nodes
    if target_clusters <= 0:
        return [], 0
    if target_clusters > len(all_nodes):
        target_clusters = len(all_nodes)

    merges = len(clusters) - target_clusters
    if merges < 0:
        merges = 0

    # Agglomeratively merge clusters (no while loops used)
    for _ in range(merges):
        best_i, best_j, best_value = None, None, None
        for i in range(len(clusters) - 1):
            ci = clusters[i]
            for j in range(i + 1, len(clusters)):
                cj = clusters[j]
                sum_dist = 0.0
                for a in ci:
                    for b in cj:
                        sum_dist += distance_matrix[a][b]
                mean_dist = sum_dist / (len(ci) * len(cj))
                if best_value is None or mean_dist < best_value:
                    best_value = mean_dist
                    best_i, best_j = i, j
        if best_i is None:
            break
        clusters[best_i] = clusters[best_i] | clusters[best_j]
        del clusters[best_j]

    # Map each node to its cluster index
    node_to_cluster = {}
    for idx, cl in enumerate(clusters):
        for node in cl:
            node_to_cluster[node] = idx

    # Compute scores for each node
    scores = []
    for node in all_nodes:
        cluster_idx = node_to_cluster[node]
        cl = clusters[cluster_idx]
        cluster_size = len(cl)

        if cluster_size > 1:
            sum_dist = 0.0
            for other in cl:
                if other == node:
                    continue
                sum_dist += distance_matrix[node][other]
            mean_distance = sum_dist / (cluster_size - 1)
        else:
            mean_distance = 0.0

        score = mean_distance * (1.0 + 0.5 * (cluster_size - 1))
        perturb = rng.random() * 0.01 * (mean_distance + 1.0)
        score += perturb

        scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.20  # between 0.12 and 0.32
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    # collect all non-depot nodes
    all_non_dep = []
    for route in current_solution:
        for node in route:
            if node != 0:
                all_non_dep.append(node)
    total_non_dep = len(all_non_dep)

    # determine global centroid (min-sum-of-distances to other non-depots)
    centroid = None
    if total_non_dep > 0:
        min_sum = None
        for i in all_non_dep:
            s = 0.0
            for j in all_non_dep:
                if j == i:
                    continue
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0.0
                s += d
            if (min_sum is None) or (s < min_sum):
                min_sum = s
                centroid = i

    # compute scores per node
    for route_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        # route capacity and remaining capacity ratio
        route_demand = sum(demands[n] if n < len(demands) else 0 for n in non_dep)
        capacity = vehicle_capacities[route_idx] if route_idx < len(vehicle_capacities) else 0
        remaining_ratio = 0.0
        if capacity > 0:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0

        for node in non_dep:
            # distance to centroid
            if centroid is not None and node < len(distance_matrix) and centroid < len(distance_matrix[node]):
                dist_to_centroid = distance_matrix[node][centroid]
            else:
                dist_to_centroid = 0.0

            demand = demands[node] if node < len(demands) else 0

            # score: distance to centroid scaled by route residual and dampened by demand
            score = (dist_to_centroid ** 1.5) * (1.0 + 0.8 * remaining_ratio)
            score /= (1.0 + 0.4 * demand)

            # random perturbation to diversify
            perturb = rng.random() * 0.07 * (dist_to_centroid + 1.0)
            score += perturb

            scores.append((node, score))

    # determine k: number of nodes to remove
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.28  # between 0.12 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0
    max_cap = max(vehicle_capacities) if vehicle_capacities else 1.0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # Mean distance to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            depot_distance = distance_matrix[node][0]

            node_demand = demands[node] if node < len(demands) else 0.0

            # Distance-driven penalty component
            distance_penalty = (1.0 + mean_distance * 0.6) * (1.0 + depot_distance * 0.25)

            # Route-capacity slack factor
            if max_cap > 0 and route_demand < max_cap:
                slack = 1.0 + 0.5 * (max_cap - route_demand) / max_cap
            else:
                slack = 1.0

            # Node-demand influence (moderate)
            if route_demand > 0.0:
                demand_influence = 1.0 + 0.5 * (node_demand / route_demand)
            else:
                demand_influence = 1.0

            score = distance_penalty * slack * demand_influence

            # Small random perturbation to diversify removals
            perturb = rng.random() * 0.05 * (mean_distance + depot_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.18  # between 0.12 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []

    # Gather all non-depot nodes and per-route groupings
    routes_non_dep = []
    all_nodes = []
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        routes_non_dep.append(non_dep)
        for n in non_dep:
            all_nodes.append(n)

    total_non_dep = len(all_nodes)
    if total_non_dep == 0:
        return scores, 0

    # Precompute per-node route lengths and demands
    route_len_by_node = {}
    route_demand_by_node = {}
    for non_dep in routes_non_dep:
        L = len(non_dep)
        rd = 0
        for n in non_dep:
            if n < len(demands):
                rd += demands[n]
        for n in non_dep:
            route_len_by_node[n] = L
            route_demand_by_node[n] = rd

    # Sampling size (max 4, and not exceed total-1)
    S = 4
    if total_non_dep - 1 < S:
        S = max(0, total_non_dep - 1)

    # Compute scores for each non-depot node
    for non_dep in routes_non_dep:
        L = len(non_dep)
        if L == 0:
            continue
        for i in non_dep:
            avg_dist = 0.0
            if total_non_dep > 1 and S > 0:
                sample_nodes = []
                for _ in range(S):
                    idx = int(rng.random() * total_non_dep)
                    if all_nodes[idx] == i:
                        idx = (idx + 1) % total_non_dep
                    sample_nodes.append(all_nodes[idx])
                ssum = 0.0
                for j in sample_nodes:
                    if i < len(distance_matrix) and j < len(distance_matrix[i]):
                        d = distance_matrix[i][j]
                    else:
                        d = 0.0
                    ssum += d
                avg_dist = ssum / S if S > 0 else 0.0

            dist_to_depot = 0.0
            if i < len(distance_matrix) and 0 < len(distance_matrix[i]):
                dist_to_depot = distance_matrix[i][0]

            demand_i = demands[i] if i < len(demands) else 0
            route_len = route_len_by_node[i]

            # Cross-route isolation style scoring (distinct form)
            if route_len > 0:
                route_len_factor = 1.0 + 0.6 * ((route_len - 1) / route_len)
            else:
                route_len_factor = 1.0

            score = 0.0
            score += avg_dist * (1.0 + 0.4 * ((route_len - 1) / route_len)) if route_len > 0 else 0.0
            score += 0.3 * dist_to_depot
            if demand_i > 0:
                score += 0.05 * demand_i
            else:
                score += 0.0

            perturb = rng.random() * 0.05 * (avg_dist + dist_to_depot + 1.0)
            score += perturb

            scores.append((i, score))

    # Determine k (number to remove)
    frac = 0.08 + rng.random() * 0.24  # between 0.08 and 0.32
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    # Build mappings: node -> route, route -> its non-depot nodes, and route demands
    node_to_route = {}
    route_nodes_map = {}
    route_demands = {}

    total_non_dep = 0
    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        route_nodes_map[r_idx] = non_dep
        L = len(non_dep)
        total_non_dep += L
        demand_sum = 0.0
        for n in non_dep:
            node_to_route[n] = r_idx
            if n < len(demands):
                demand_sum += demands[n]
        route_demands[r_idx] = demand_sum

    scores = []
    if total_non_dep == 0:
        k = 0
        return scores, k

    all_nodes = list(node_to_route.keys())

    # Precompute route load ratios (route_demand / capacity)
    route_load_ratio = {}
    for r_idx, non_dep in route_nodes_map.items():
        cap = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0.0
        denom = cap
        denom = denom if denom > 0 else 0.0
        rd = route_demands.get(r_idx, 0.0)
        ratio = (rd / denom) if denom > 0 else 0.0
        if ratio > 1.0:
            ratio = 1.0
        route_load_ratio[r_idx] = ratio

    # Compute scores for each node
    for node in all_nodes:
        r = node_to_route[node]

        # Global mean distance to all other non-depot nodes
        if total_non_dep > 1:
            s = 0.0
            for other in all_nodes:
                if other == node:
                    continue
                s += distance_matrix[node][other]
            global_mean_distance = s / (total_non_dep - 1)
        else:
            global_mean_distance = 0.0

        # Distance to nearest neighbor within its own route
        route_list = route_nodes_map.get(r, [])
        neighbor_distance = 0.0
        if route_list:
            try:
                idx = route_list.index(node)
            except ValueError:
                idx = -1
            if idx != -1:
                candidates = []
                if idx > 0:
                    candidates.append(distance_matrix[node][route_list[idx - 1]])
                if idx < len(route_list) - 1:
                    candidates.append(distance_matrix[node][route_list[idx + 1]])
                if candidates:
                    neighbor_distance = min(candidates)

        # Route load ratio and a global score combining both components
        load = route_load_ratio.get(r, 0.0)
        score = global_mean_distance * (1.0 + 1.5 * (1.0 - load))
        score += neighbor_distance * 0.5

        # Small jitter to diversify removals
        perturb = rng.random() * 0.01 * (global_mean_distance + neighbor_distance + 1.0)
        score += perturb

        scores.append((node, score))

    frac = 0.09 + rng.random() * 0.22  # between 0.09 and 0.31
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

