                        continue
                    d = distance_matrix[node][other]
                    if d > max_distance:
                        max_distance = d
            else:
                max_distance = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            # Score computation with a different formulation
            base = saving * (1.0 + 0.5 * (L - 1))
            if route_demand > 0.0:
                base += (demand / route_demand) * 0.8
            base /= (1.0 + max_distance * 0.4)
            perturb = rng.random() * 0.04 * (saving + max_distance + 1.0)
            score = base + perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.24  # between 0.12 and 0.36
        k = max(1, int(round(total_non_dep * frac)))
