    capacities = data.get('vehicle_capacities', [])
    max_capacity = max(capacities) if capacities else 1

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Precompute depot distances for diversity metric
        depot_dists = []
        for node in non_dep:
            if 0 <= node < len(distance_matrix):
                depot_dists.append(distance_matrix[node][0])
            else:
                depot_dists.append(0.0)
        if depot_dists:
            min_dep = min(depot_dists)
            max_dep = max(depot_dists)
            if max_dep > 0:
                diversity = 1.0 + 0.25 * (max_dep - min_dep) / max_dep
            else:
                diversity = 1.0
        else:
            diversity = 1.0

        # Route demand (sum of demands for non-depot nodes in this route)
        route_demand = 0
        for n in non_dep:
            if 0 <= n < len(demands):
                route_demand += demands[n]

        for node in non_dep:
            if L > 1:
                sum_to_others = 0.0
                max_to_others = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    sum_to_others += d
                    if d > max_to_others:
                        max_to_others = d
                mean_distance = sum_to_others / (L - 1)
            else:
                mean_distance = 0.0
                max_to_others = 0.0

            depot_distance = distance_matrix[node][0]

            node_demand = demands[node] if 0 <= node < len(demands) else 0

            # New scoring formula: reweighted intra-route, depot proximity, and load with diversity
            base = 0.4 * mean_distance + 0.6 * max_to_others + 0.25 * depot_distance
            score = base * (1.0 + (route_demand / max_capacity) * 0.3 + (diversity - 1.0) * 0.5)

            score /= (1.0 + node_demand)

            perturb = rng.random() * 0.04 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

