    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # Route centroid (as a simple index-based center)
        center_idx = sum(non_dep) / L

        for node in non_dep:
            # Mean distance to peers
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_dist = s / (L - 1)
            else:
                mean_dist = 0.0

            # Center distance
            center_dist = abs(node - center_idx)

            # Demands
            node_demand = demands[node] if node < len(demands) else 0.0

            # Farthest distance to peers
            if L > 1:
                farthest = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if d > farthest:
                        farthest = d
            else:
                farthest = 0.0

            # Components of the score (designed to be distinct from prior methods)
            comp1 = 1.0 / (mean_dist + 1.0)
            comp_center = 1.0 + (center_dist / (L + 1))
            if route_demand > 0.0:
                demand_factor = 1.0 + 0.3 * ((route_demand - node_demand) / route_demand)
            else:
                demand_factor = 1.0
            comp3 = 1.0 + 0.4 * (farthest / (farthest + 1.0))

            score = comp1 * comp_center * demand_factor * comp3

            perturb = rng.random() * 0.01 * (mean_dist + 1.0 + farthest)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

