    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue
        total_non_dep += L

        for node in non_dep:
            # Internal mean distance to peers within the same route
            if L > 1:
                s_int = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s_int += distance_matrix[node][other]
                internal_mean = s_int / (L - 1)
            else:
                internal_mean = 0.0

            # External mean distance to nodes in other routes
            s_ext = 0.0
            count_ext = 0
            for r in current_solution:
                for other in r:
                    if other == 0 or other == node:
                        continue
                    if other in non_dep:
                        continue
                    s_ext += distance_matrix[node][other]
                    count_ext += 1
            external_mean = (s_ext / count_ext) if count_ext > 0 else 0.0

            demand = demands[node] if node < len(demands) else 0
            route_factor = 1.0 + 0.4 * (L - 1)
            denom = 1.0 + (demand ** 0.5 if demand >= 0 else 0.0)
            score = (internal_mean - external_mean) * route_factor / denom

            perturb = rng.random() * 0.05 * (internal_mean + external_mean + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
