def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # Build per-route information and mappings
    routes_info = []  # list of dicts: {'nodes': [...], 'demand': float}
    node_to_route = {}  # map node -> route index
    for r_id, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]
        routes_info.append({'nodes': non_dep, 'demand': route_demand})
        for n in non_dep:
            node_to_route[n] = r_id
        total_non_dep += L

    # All non-depot nodes present
    all_nodes = [n for r in current_solution for n in r if n != 0]

    # Precompute mean distance to all other non-depot nodes
    mean_to_others = {}
    for node in all_nodes:
        others = [m for m in all_nodes if m != node]
        if len(others) > 0:
            s = 0.0
            for o in others:
                s += distance_matrix[node][o]
            mean_to_others[node] = s / len(others)
        else:
            mean_to_others[node] = 0.0

    # Compute score per node: global centrality + local demand balance + jitter
    for node in all_nodes:
        route_id = node_to_route.get(node, None)
        route_demand = routes_info[route_id]['demand'] if route_id is not None else 0.0
        mean_dist = mean_to_others[node]
        demand = demands[node] if node < len(demands) else 0.0

        if route_demand > 0:
            ratio = demand / route_demand
            term_demand = 1.0 - min(1.0, ratio)
        else:
            term_demand = 0.0

        jitter = rng.random() * 0.5
        score = mean_dist * 0.5 + term_demand * 1.2 + jitter

        scores.append((node, score))

    # Determine how many to remove
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.22  # between 0.12 and 0.34
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue
        total_non_dep += L

        # Route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # Sum of reciprocals of distances to other nodes in the same route
            sum_inv = 0.0
            for other in non_dep:
                if other == node:
                    continue
                d = distance_matrix[node][other]
                if d > 0.0:
                    sum_inv += 1.0 / d

            # Position factor: ends have lower impact, middle nodes have higher factor
            if L > 1:
                pos = min(idx, L - 1 - idx)
                pos_factor = 1.0 + 0.5 * (pos / (L - 1))
            else:
                pos_factor = 1.0

            # Demand penalty relative to route demand
            demand = demands[node] if node < len(demands) else 0.0
            if route_demand > 0.0:
                demand_ratio = demand / route_demand
            else:
                demand_ratio = 0.0

            # Score computation
            score = sum_inv * pos_factor
            score *= 1.0 / (1.0 + 1.4 * demand_ratio)

            # Random perturbation for diversification
            perturb = rng.random() * 0.05 * (sum_inv + pos_factor + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.18  # between 0.10 and 0.28
        k = max(1, int(round(total_non_dep * frac)))
