            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])
    max_cap = max(vehicle_capacities) if vehicle_capacities else 1

    scores = []
    total_non_dep = 0

    # Gather all non-depot nodes and their route membership
    all_nodes = []
    node_to_route = {}
    for rid, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        for n in non_dep:
            all_nodes.append(n)
            node_to_route[n] = rid

    total_non_dep = len(all_nodes)

    # Precompute global mean distance to all other non-depot nodes for each node
    global_mean = {}
    if total_non_dep > 0:
        for node in all_nodes:
            s = 0.0
            for other in all_nodes:
                if other == node:
                    continue
                s += distance_matrix[node][other]
            global_mean[node] = s / (total_non_dep - 1) if total_non_dep > 1 else 0.0

    # For each route and each node, compute intra-route mean distance
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        # Route demand (sum of demands for nodes in this route)
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_intra = s / (L - 1)
            else:
                mean_intra = 0.0

            global_mean_node = global_mean.get(node, 0.0)
            base_diff = global_mean_node - mean_intra
            if base_diff < 0.0:
                base_diff = 0.0

            # Nonlinear-ish amplification of the global-intra disparity
            score = 1.6 * base_diff

            # Depot proximity boost
            depot_dist = distance_matrix[node][0] if node < len(distance_matrix) else 0.0
            score += 0.6 * depot_dist

            # Route load contribution (normalized by max capacity)
            load_frac = 0.0
            if max_cap > 0:
                load_frac = route_demand / max_cap
            score += 0.9 * load_frac

            # Random perturbation to diversify choices
            perturb = rng.random() * 0.5
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.20  # between 0.07 and 0.27
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # Build mappings: node -> route index
    node_to_route = {}
    for ridx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        for node in non_dep:
            node_to_route[node] = ridx

    # Precompute route demands
    route_demands = {}
    for ridx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        rd = 0.0
        for n in non_dep:
            if n < len(demands):
                rd += demands[n]
        route_demands[ridx] = rd

    # Compute scores per node
    for ridx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        route_demand = route_demands.get(ridx, 0.0)

        for idx, node in enumerate(non_dep):
            # Mean dispersion to two nearest peers in the same route
            if L > 1:
                dists = []
                for other in non_dep:
                    if other == node:
                        continue
                    dists.append(distance_matrix[node][other])
                if len(dists) >= 2:
                    dists.sort()
                    mean_dist_two = (dists[0] + dists[1]) / 2.0
                elif len(dists) == 1:
                    mean_dist_two = dists[0]
                else:
                    mean_dist_two = 0.0
            else:
                mean_dist_two = 0.0

            # Cross-route proximity: minimum distance to any node in other routes
            cross_min = None
            for other_node in range(len(distance_matrix)):
                if other_node == node:
                    continue
                if node_to_route.get(other_node) == ridx:
                    continue
                dist = distance_matrix[node][other_node]
                if cross_min is None or dist < cross_min:
                    cross_min = dist
            if cross_min is None:
                cross_min = 0.0

            demand = demands[node] if node < len(demands) else 0.0
            # Score: high dispersion, boosted if close to other routes, adjusted by route demand, plus jitter
            score = mean_dist_two
            # Route-length influence
            score *= (1.0 + 0.25 * (L - 1))

            # Damp or boost by how large the node's demand is relative to route demand
            if route_demand > 0.0:
                score /= (1.0 + 0.3 * (demand / route_demand))

            # Proximity to other routes boosts the score (more likely to be removed to improve integration)
            score *= (1.0 + 0.5 * (1.0 / (1.0 + cross_min)))

            # Random perturbation for diversification
            perturb = rng.random() * 0.05 * (mean_dist_two + cross_min + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.16  # between 0.07 and 0.23
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        route_demand = 0
        for node in non_dep:
            if node < len(demands):
                route_demand += demands[node]
        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        if capacity <= 0:
            remaining_ratio = 0.0
        else:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            elif remaining_ratio > 1.0:
                remaining_ratio = 1.0

        for j, node in enumerate(non_dep):
            local_span = 0.0
            if L > 1:
                if j > 0:
                    prev_node = non_dep[j - 1]
                    local_span += distance_matrix[node][prev_node]
                if j < L - 1:
                    next_node = non_dep[j + 1]
                    local_span += distance_matrix[node][next_node]
            if L > 1:
                middle_dist = abs(2 * j - (L - 1))
                max_term = max(1, (L - 1))
                diversity = 1.0 + 0.04 * ((L - 1) - middle_dist) / max_term
            else:
                diversity = 1.0

            node_demand = demands[node] if node < len(demands) else 0

            load_factor = 1.0 + 0.6 * (1.0 - remaining_ratio)

            score = (local_span ** 1.25) * diversity * load_factor
            score /= (1.0 + 0.5 * node_demand)

            perturb = (rng.random() - 0.5) * 0.07 * (local_span + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']  # not used in this new form but kept for compatibility
    demands = data.get('demands', [])
    scores = []

    # Build intra-route adjacency and the set of all non-depot nodes
    adj = {}
    all_nodes_set = set()
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        for idx, node in enumerate(non_dep):
            if node not in adj:
                adj[node] = []
            if idx > 0:
                prev_node = non_dep[idx - 1]
                if prev_node not in adj[node]:
                    adj[node].append(prev_node)
            if idx < L - 1:
                next_node = non_dep[idx + 1]
                if next_node not in adj[node]:
                    adj[node].append(next_node)
            all_nodes_set.add(node)

    all_nodes = sorted(all_nodes_set)

    if not all_nodes:
        return scores, 0

    # Initialize visit counts
    visit = {node: 0 for node in all_nodes}

    # Parameters for stochastic walks (totally different form from prior methods)
    total_nodes = len(all_nodes)
    N_walks = max(3, min(12, total_nodes * 2))    # 3 to 12 walks
    WALK_LEN = max(2, int(round(total_nodes * 0.4)))  # each walk length ~40% of total nodes

    # Perform multiple short random walks on the intra-route graph
    for _ in range(N_walks):
        current = rng.choice(all_nodes)
        visit[current] += 1
        for _step in range(WALK_LEN - 1):
            neighbors = adj.get(current, [])
            if not neighbors:
                break
            current = rng.choice(neighbors)
            visit[current] += 1

    # Build scores: per-node visitation counts with a tiny jitter
    for node in all_nodes:
        score = visit[node] + rng.random() * 0.01
        scores.append((node, score))

    # Determine k as a random fraction of total non-depot nodes
    k = 0
    if total_nodes > 0:
        frac = 0.08 + rng.random() * 0.24  # between 0.08 and 0.32
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

