            if n < len(demands):
                route_demand += demands[n]

        # Determine medoid (node with minimal sum distance to others) and max pair distance
        if L == 1:
            medoid = non_dep[0]
            max_pair_distance = 0.0
        else:
            s_to_others = {}
            max_pair_distance = 0.0
            for node in non_dep:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    s += d
                    if d > max_pair_distance:
                        max_pair_distance = d
                s_to_others[node] = s
            medoid = min(s_to_others, key=lambda x: s_to_others[x])

        for node in non_dep:
            dist_to_medoid = distance_matrix[node][medoid]
            dist_to_depot = distance_matrix[node][0]

            dispersion_norm = 0.0
            if L > 1:
                dispersion_norm = dist_to_medoid / (1.0 + max_pair_distance)

            depot_norm = dist_to_depot / (1.0 + max_pair_distance)
            demand_ratio = route_demand / max_capacity if max_capacity > 0 else 0.0

            # New scoring components with a distinct weighting
            score = 0.5 * dispersion_norm + 0.25 * depot_norm + 0.25 * demand_ratio

            jitter = rng.random() * 0.25 * (dist_to_medoid + dist_to_depot + 1.0)
            score += jitter

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.12  # between 0.12 and 0.24
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    # Build per-route list of non-depot nodes
    routes_non_dep = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        routes_non_dep.append(non_dep)
        total_non_dep += len(non_dep)

    # For each route, compute scores for its nodes
    for r_idx, non_dep in enumerate(routes_non_dep):
        L = len(non_dep)
        if L == 0:
            continue

        # Nodes in other routes
        other_nodes = []
        for idx, other_route in enumerate(routes_non_dep):
            if idx == r_idx:
                continue
            other_nodes.extend(other_route)

        for node in non_dep:
            # Local mean distance to peers in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other] if (node < len(distance_matrix) and other < len(distance_matrix[node])) else 0.0
                    s += d
                local_mean = s / (L - 1)
            else:
                local_mean = 0.0

            # Cross-route proximity: minimum distance to any node in other routes
            if other_nodes:
                min_cross = float('inf')
                for other in other_nodes:
                    d = distance_matrix[node][other] if (node < len(distance_matrix) and other < len(distance_matrix[node])) else float('inf')
                    if d < min_cross:
                        min_cross = d
                cross_term = 1.0 / (1.0 + min_cross)
                cross_min_value = min_cross
            else:
                cross_term = 1.0
                cross_min_value = 0.0

            # Score combination with a small random perturbation
            score = (local_mean ** 1.15) * (1.0 + 0.4 * (L - 1)) * cross_term
            perturb = rng.random() * 0.05 * (local_mean + cross_min_value + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # total demand on this route
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # base local saving for each node
        base = {}
        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0
            else:
                neighbor = prev_node if prev_node is not None else next_node
                if neighbor is not None:
                    saving = distance_matrix[neighbor][node]
                else:
                    saving = 0.0

            base[node] = saving

        # diffusion passes to create a global influence
        diff = base.copy()
        if L > 1:
            # forward diffusion from left to right
            for i in range(1, L):
                left = non_dep[i - 1]
                node = non_dep[i]
                diff[node] += 0.4 * diff[left]
            # backward diffusion from right to left
            for i in range(L - 2, -1, -1):
                right = non_dep[i + 1]
                node = non_dep[i]
                diff[node] += 0.4 * diff[right]

        # compute final scores for nodes in this route
        for idx, node in enumerate(non_dep):
            val = diff[node]
            d = demands[node] if node < len(demands) else 0.0

            term = 0.0
            if route_demand > 0.0:
                term = 0.35 * (d / route_demand)

            score = val + term

            # jitter for diversification
            score += rng.random() * 0.08

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.20  # between 0.05 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

