                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # mean distance to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            mean_distance_score = 1.0 / (1.0 + mean_distance)

            # projection-based density along the route
            if L > 1:
                pos = idx / (L - 1)
            else:
                pos = 0.5
            proj_noise = rng.random() * 0.12
            projection = 1.0 - abs((pos + proj_noise) - 0.5)
            if projection < 0.0:
                projection = 0.0
            if projection > 1.0:
                projection = 1.0

            # node demand
            demand = demands[node] if node < len(demands) else 0.0
            route_demand_safe = route_demand if route_demand > 0.0 else 1.0
            demand_ratio = demand / route_demand_safe

            # combined score with fixed weights (different form from previous approaches)
            score = 0.45 * mean_distance_score + 0.35 * projection + 0.20 * demand_ratio

            # small random perturbation to diversify removals
            jitter = rng.random() * 0.08 * (mean_distance + projection + 1.0)
            score += jitter

            if score < 0.0:
                score = 0.0

