        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        for idx, node in enumerate(non_dep):
            # max/min distance to other nodes in the same route
            if L > 1:
                max_to_others = 0.0
                min_to_others = float('inf')
                for other in non_dep:
                    if other == node:
                        continue
                    d = 0.0
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        d = distance_matrix[node][other]
                    if d > max_to_others:
                        max_to_others = d
                    if d < min_to_others:
                        min_to_others = d
                if min_to_others == float('inf'):
                    min_to_others = 0.0
            else:
                max_to_others = 0.0
                min_to_others = 0.0

