            if max_to_others + min_to_others > 0:
                diversity = 1.0 + 0.25 * ((max_to_others - min_to_others) / (max_to_others + min_to_others))
            else:
                diversity = 1.0

            score = 0.0
            if max_to_others > 0:
                score += max_to_others ** 1.25
            score += depot_distance * 0.5
            score *= (1.0 + 0.65 * (route_demand / max_capacity))
            score *= diversity

            perturb = rng.random() * 0.08 * (max_to_others + depot_distance + 1.0)
            score += perturb

            if score < 0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
