                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            score = centrality * CENTRALITY_WEIGHT
            score -= mean_distance * PERIPHERAL_DECAY
            if route_demand > 0.0:
                score -= (demand / route_demand) * 0.1

            attenuation = 1.0 / (1.0 + (mean_distance ** 2) * ATTENUATION_COEFF)
            score *= attenuation

            perturb = rng.random() * JITTER_SCALE * (centrality + mean_distance +
                    (demand / route_demand if route_demand > 0.0 else 0.0) + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.1 + rng.random() * 0.15  # between 0.1 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

