            continue
        non_dep_total += len(non_dep)

        for i in non_dep:
            farthest = 0.0
            for j in non_dep:
                if j == i:
                    continue
                d = 0.0
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                if d > farthest:
                    farthest = d

            demand = demands[i] if i < len(demands) else 0
            route_length_factor = 1.0 + 0.40 * (len(route) - 1)
            denom = 1.0 + (demand ** 0.5 if demand >= 0 else 0.0)
            score = (farthest ** 0.6) * route_length_factor / denom
            score += rng.random() * 0.15 * (farthest + 1.0)
            scores.append((i, score))

    if non_dep_total == 0:
        k = 0
    else:
        frac = 0.06 + rng.random() * 0.36
        k = max(1, int(round(non_dep_total * frac)))
