def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        route_demand = sum(demands[node] if node < len(demands) else 0 for node in non_dep)
        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        if capacity <= 0:
            remaining_ratio = 0.0
        else:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0

        # Diveristy factor grows more slowly (stronger emphasis on remaining capacity)
        diversity = 1.0 + 0.05 * (L - 1)

        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            node_demand = demands[node] if node < len(demands) else 0

            # Stronger load penalty as remaining capacity shrinks
            load_factor = 1.0 + 0.8 * (1.0 - remaining_ratio)

            score = (mean_distance ** 1.25) * diversity * load_factor
            score /= (1.0 + 0.4 * node_demand)

            perturb = rng.random() * 0.05 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # precompute sum of distances to others and mean distance to others
        sum_to_others = {}
        mean_to_others = {}
        for i, node in enumerate(non_dep):
            s = 0.0
            for j, other in enumerate(non_dep):
                if i == j:
                    continue
                s += distance_matrix[node][other]
            sum_to_others[node] = s
            mean_to_others[node] = (s / (L - 1)) if L > 1 else 0.0

        # centroid: node with minimal sum_to_others
        centroid = None
        min_sum = None
        for node in non_dep:
            if centroid is None or sum_to_others[node] < min_sum:
                centroid = node
                min_sum = sum_to_others[node]

        for node in non_dep:
            dist_to_centroid = (distance_matrix[node][centroid]
                                if (node < len(distance_matrix) and centroid < len(distance_matrix[node]))
                                else 0.0)

            mean_dist = mean_to_others[node]

            base = dist_to_centroid - mean_dist

            # clamp base to [-5, 5] and map to [0,1]
            if base < -5.0:
                base_clamped = -5.0
            elif base > 5.0:
                base_clamped = 5.0
            else:
                base_clamped = base

            norm = (base_clamped + 5.0) / 10.0

            # demand factor
            demand = demands[node] if node < len(demands) else 0.0
            if route_demand > 0.0:
                norm *= (1.0 + 0.5 * (demand / route_demand))

            # depot bias
            distance_to_depot = (distance_matrix[node][0]
                                 if (node < len(distance_matrix) and len(distance_matrix[node]) > 0)
                                 else 0.0)
            depot_bias = max(0.2, 1.0 - 0.003 * distance_to_depot)

            score = norm * depot_bias

            # perturbation for diversification
            perturb = rng.random() * 0.25 * (1.0 + abs(base_clamped))
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.03 + rng.random() * 0.15  # between 0.03 and 0.18
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for node in non_dep:
            max_dist = 0.0
            sum_dist = 0.0

            if L > 1:
                for other in non_dep:
                    if other == node:
                        continue
                    d = 0.0
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        d = distance_matrix[node][other]
                    sum_dist += d
                    if d > max_dist:
                        max_dist = d
                mean_dist = sum_dist / (L - 1)
            else:
                mean_dist = 0.0

            peripheral_gap = max_dist - mean_dist
            if peripheral_gap < 0.0:
                peripheral_gap = 0.0

            route_factor = 1.0 + 1.3 * (L - 1)

            node_demand = demands[node] if node < len(demands) else 0.0
            demand_ratio = 0.0
            if route_demand > 0.0:
                demand_ratio = node_demand / route_demand

            score = peripheral_gap * route_factor * (1.0 + demand_ratio)

            jitter = rng.random() * 0.2 * (peripheral_gap + mean_dist + 1.0)
            score += jitter

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.13  # between 0.07 and 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Collect all non-depot nodes in the current solution
    all_nodes = []
    node_to_route = {}
    route_lengths = {}
    for r, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        route_lengths[r] = L
        for n in non_dep:
            all_nodes.append(n)
            node_to_route[n] = r

    total_non_dep = len(all_nodes)
    if total_non_dep == 0:
        return [], 0

    # Compute per-route demands
    route_demand = {}
    for r, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        rd = 0.0
        for n in non_dep:
            if n < len(demands):
                rd += demands[n]
        route_demand[r] = rd

    # Precompute mean distance to all other non-depot nodes
    N = total_non_dep
    mean_to_others = {}
    for i in all_nodes:
        if N > 1:
            s = 0.0
            for j in all_nodes:
                if j == i:
                    continue
                s += distance_matrix[i][j]
            mean_to_others[i] = s / (N - 1)
        else:
            mean_to_others[i] = 0.0

    max_dep = 0.0
    for i in all_nodes:
        d = distance_matrix[i][0]
        if d > max_dep:
            max_dep = d
    max_dep = max_dep if max_dep > 0 else 1.0

    max_mean = 0.0
    for i in all_nodes:
        if mean_to_others[i] > max_mean:
            max_mean = mean_to_others[i]
    max_mean = max_mean if max_mean > 0 else 1.0

    max_demand = 0.0
    for i in all_nodes:
        di = demands[i] if i < len(demands) else 0.0
        if di > max_demand:
            max_demand = di
    max_demand = max_demand if max_demand > 0 else 1.0

    scores = []

    for i in all_nodes:
        # depot distance norm
        dep_norm = distance_matrix[i][0] / max_dep if max_dep > 0 else 0.0

        # mean distance norm
        mean_norm = mean_to_others[i] / max_mean if max_mean > 0 else 0.0

        # node demand normalized
        demand_i = demands[i] if i < len(demands) else 0.0
        demand_norm = demand_i / max_demand if max_demand > 0 else 0.0

        r = node_to_route[i]
        rd = route_demand.get(r, 0.0)

        cross = dep_norm * mean_norm

        # nonlinear combination emphasizing far and dispersed nodes
        score = (dep_norm ** 2) + (mean_norm ** 2) + 0.5 * demand_norm
        if rd > 0.0:
            score += 0.6 * (demand_i / rd)

        score += 0.3 * cross

        # jitter for diversification
        jitter = rng.random() * 0.1 * (dep_norm + mean_norm + demand_norm + cross + 1.0)
        score += jitter

        if score < 0.0:
            score = 0.0

        scores.append((i, score))

    # number of nodes to remove
    frac = 0.07 + rng.random() * 0.18  # between 0.07 and 0.25
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])
    max_cap = max(vehicle_capacities) if vehicle_capacities else 1

    N = len(distance_matrix)

    # Define a small set of pivot nodes (totally different form from savings-based methods)
    pivots = []
    if N > 1:
        pivots.append(1)
    if N > 3:
        pivots.append(N // 3)
    if N > 2:
        pivots.append(N - 1)
    # Ensure pivots are unique and valid
    seen = set()
    pivots = []
    for p in [1, N // 3, N - 1]:
        if p is None:
            continue
        if 0 < p < N and p not in seen:
            pivots.append(p)
            seen.add(p)
    if not pivots:
        pivots = [1]  # fallback

    # Precompute distance to nearest pivot for all nodes
    dist_to_pivot = [0.0] * N
    max_dist_to_pivot = 0.0
    for node in range(N):
        best = float('inf')
        for p in pivots:
            d = distance_matrix[node][p]
            if d < best:
                best = d
        if best == float('inf'):
            best = 0.0
        dist_to_pivot[node] = best
        if best > max_dist_to_pivot:
            max_dist_to_pivot = best

    # Gather nodes that actually appear in the solution
    present_nodes = []
    present_set = set()
    for route in current_solution:
        for n in route:
            if n != 0 and n not in present_set:
                present_set.add(n)
                present_nodes.append(n)

    # Compute maximums for normalization
    max_node_demand = 0.0
    for n in present_nodes:
        if n < len(demands) and demands[n] > max_node_demand:
            max_node_demand = demands[n]
    if max_node_demand <= 0.0:
        max_node_demand = 1.0

    route_demand_map = {}
    max_route_demand = 0.0
    for ridx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        if len(non_dep) == 0:
            continue
        rd = 0.0
        for n in non_dep:
            if n < len(demands):
                rd += demands[n]
        route_demand_map[ridx] = rd
        if rd > max_route_demand:
            max_route_demand = rd
    if max_route_demand <= 0.0:
        max_route_demand = 1.0

    scores = []
    total_non_dep = 0

    for ridx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L
        if L == 0:
            continue

        route_demand = route_demand_map.get(ridx, 0.0)

        for idx, node in enumerate(non_dep):
            dist_pivot = dist_to_pivot[node] if node < N else 0.0
            norm_pivot = dist_pivot / max_dist_to_pivot if max_dist_to_pivot > 0.0 else 0.0

            demand = demands[node] if node < len(demands) else 0.0
            norm_demand = demand / max_node_demand if max_node_demand > 0.0 else 0.0

            norm_route_load = route_demand / max_route_demand if max_route_demand > 0.0 else 0.0

            # distance to depot (can be used for optional extension)
            distance_to_depot = distance_matrix[node][0] if node < N and 0 < len(distance_matrix[node]) else 0.0

            # Combine factors into a distinct score
            score = 0.5 * norm_pivot + 0.25 * norm_demand + 0.25 * norm_route_load

            # Random jitter for diversification
            jitter = rng.random() * 0.25
            score += jitter

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.18  # between 0.12 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # Gather route-level information
    route_infos = []
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        route_infos.append({
            'non_dep': non_dep,
            'L': L,
            'route_demand': route_demand
        })

    # Compute average route demand (only for routes with nodes)
    sum_dem = 0.0
    cnt_routes = 0
    for info in route_infos:
        if info['L'] > 0:
            sum_dem += info['route_demand']
            cnt_routes += 1
    avg_route_demand = sum_dem / cnt_routes if cnt_routes > 0 else 0.0

    # Compute per-node scores
    for info in route_infos:
        non_dep = info['non_dep']
        L = info['L']
        route_demand = info['route_demand']

        for idx, node in enumerate(non_dep):
            dist_to_depot = 0.0
            if node < len(distance_matrix) and 0 < len(distance_matrix[node]):
                dist_to_depot = distance_matrix[node][0]

            mean_distance_to_others = 0.0
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        s += distance_matrix[node][other]
                mean_distance_to_others = s / (L - 1)
            else:
                mean_distance_to_others = 0.0

            C1 = dist_to_depot / (dist_to_depot + 1.0)
            C2 = 1.0 / (1.0 + mean_distance_to_others)

            load_penalty = 0.0
            if avg_route_demand > 0.0:
                load_ratio = route_demand / avg_route_demand
                if load_ratio > 1.0:
                    load_penalty = load_ratio - 1.0

            C3 = 1.0 + 0.6 * load_penalty

            score = C1 * C2 * C3

            perturb = rng.random() * 0.25 * (dist_to_depot + mean_distance_to_others + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.15  # between 0.05 and 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # Gather all nodes present in the solution (excluding depot 0)
    nodes_in_solution = set()
    for route in current_solution:
        for node in route:
            if node != 0:
                nodes_in_solution.add(node)

    N = len(distance_matrix)
    # Precompute per-node metrics
    dist_to_depot = {}
    centrality = {}
    node_demand = {}

    max_dist = 0.0
    max_demand = 0.0
    max_center = 0.0

    for node in nodes_in_solution:
        if 0 <= node < N:
            d_dep = distance_matrix[0][node] if N > 0 else 0.0
            dist_to_depot[node] = d_dep

            dem = demands[node] if node < len(demands) else 0.0
            node_demand[node] = dem

            # centrality: sum of distances to all other nodes
            s = 0.0
            for j in range(N):
                if j == node:
                    continue
                s += distance_matrix[node][j]
            centrality[node] = s

            if d_dep > max_dist:
                max_dist = d_dep
            if dem > max_demand:
                max_demand = dem
            if s > max_center:
                max_center = s
        else:
            dist_to_depot[node] = 0.0
            node_demand[node] = 0.0
            centrality[node] = 0.0

    # Normalization factors (avoid division by zero)
    if max_dist == 0.0:
        max_dist = 1.0
    if max_demand == 0.0:
        max_demand = 1.0
    if max_center == 0.0:
        max_center = 1.0

    # Compute scores for each node
    for route in current_solution:
        for node in route:
            if node == 0:
                continue
            if node not in nodes_in_solution:
                continue

            ndist = dist_to_depot.get(node, 0.0) / max_dist
            dmd = node_demand.get(node, 0.0) / max_demand
            cent = centrality.get(node, 0.0) / max_center

            # Combine features with fixed weights (totally different form)
            score = 0.4 * ndist + 0.3 * dmd + 0.3 * cent

            # jitter to diversify removals
            perturb = rng.random() * 0.02 * (ndist + dmd + cent + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))
            total_non_dep += 1

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.15  # between 0.05 and 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

