    node_to_route = {}
    route_demands = []

    for r_idx, route in enumerate(routes):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        # route demand
        rd = 0.0
        for n in non_dep:
            if n < len(demands):
                rd += demands[n]
        route_demands.append(rd)

        for n in non_dep:
            node_to_route[n] = r_idx

    N = len(distance_matrix)

    # Compute scores for every node
    for r_idx, route in enumerate(routes):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)

        if L == 0:
            continue

        route_demand = route_demands[r_idx]

        for idx, node in enumerate(non_dep):
            # diversity_term: min distance to a node in a different route
            diversity_term = 0.0
            min_other = None
            for other_node in range(N):
                if other_node == node:
                    continue
                if other_node in node_to_route:
                    if node_to_route[other_node] != r_idx:
                        d = distance_matrix[node][other_node]
                        if min_other is None or d < min_other:
                            min_other = d
            if min_other is not None:
                diversity_term = min_other
            else:
                diversity_term = 0.0

            # mean distance to others in same route (centrality within route)
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_within = s / (L - 1)
            else:
                mean_within = 0.0

            node_demand = demands[node] if node < len(demands) else 0.0
            demand_prop = node_demand / (route_demand + 1e-9)

            distance_to_depot = distance_matrix[0][node] if len(distance_matrix) > 0 else 0.0

            # New scoring formula (distinct from the given ones)
            score = (diversity_term * 2.5) + (demand_prop * 3.0) - (mean_within * 0.7) - (distance_to_depot * 0.2)

            # Jitter to diversify removals
            perturb = rng.random() * 0.05 * (diversity_term + mean_within + distance_to_depot + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.04 + rng.random() * 0.16  # between 0.04 and 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

