    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # New distinct parameter settings
    ALPHA = 0.9       # influence of route length (L-1) on squared-distance term
    BETA = 0.12       # weight for per-node demand relative to route demand
    GAMMA = 0.4       # attenuation factor based on max distance within route
    JITTER_SCALE = 0.25 # diversification jitter

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Compute total route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # Compute sum of squared distances to other nodes in the same route
            ssum_sq = 0.0
            for other in non_dep:
                if other == node:
                    continue
                if node < len(distance_matrix) and other < len(distance_matrix[node]):
                    d = distance_matrix[node][other]
                else:
                    d = 0.0
                ssum_sq += d * d

            # Compute maximum distance to any other node in the route (for attenuation)
            max_dist = 0.0
            for other in non_dep:
                if other == node:
                    continue
                if node < len(distance_matrix) and other < len(distance_matrix[node]):
                    d = distance_matrix[node][other]
                else:
                    d = 0.0
                if d > max_dist:
                    max_dist = d

            # Node demand
            demand = demands[node] if node < len(demands) else 0.0

            # Score with the new formulation
            score = ssum_sq * (1.0 + ALPHA * (L - 1))

            if route_demand > 0.0:
                score += BETA * (demand / route_demand)

            attenuation = 1.0 / (1.0 + max_dist * GAMMA)
            score *= attenuation

            perturb = rng.random() * JITTER_SCALE * (ssum_sq + max_dist + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.18  # between 0.07 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

