    # Precompute global max distance for normalization
    max_dist = 0.0
    for i in range(len(distance_matrix)):
        row = distance_matrix[i]
        for j in range(len(row)):
            d = row[j]
            if d > max_dist:
                max_dist = d
    denom = max_dist if max_dist > 0 else 1.0

    scores = []
    total_non_dep = 0

    # Determine maximum route length (for route-length adjustment)
    max_route_len = 0
    for route in current_solution:
        non_dep_len = 0
        for n in route:
            if n != 0:
                non_dep_len += 1
        if non_dep_len > max_route_len:
            max_route_len = non_dep_len

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Compute route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # Depot distance feature
            d_to_depot = 0.0
            if node < len(distance_matrix) and 0 < len(distance_matrix[node]):
                d_to_depot = distance_matrix[node][0]

            # Nearest neighbor distance within the same route
            min_dist = None
            for other in non_dep:
                if other == node:
                    continue
                dist = 0.0
                if node < len(distance_matrix) and other < len(distance_matrix[node]):
                    dist = distance_matrix[node][other]
                if min_dist is None or dist < min_dist:
                    min_dist = dist
            if min_dist is None:
                min_dist = 0.0

            # Demand share for the node relative to its route
            demand = demands[node] if node < len(demands) else 0.0
            demand_share = (demand / route_demand) if route_demand > 0.0 else 0.0

            # Normalize features
            f1 = d_to_depot / denom
            f2 = demand_share
            f3 = min_dist / denom

            # Feature combination (totally different form from local-savings)
            score_raw = 1.2 * f1 + 0.9 * f2 + 0.8 * f3

            # Route-length adjustment (prefer affecting longer routes)
            if max_route_len > 0:
                route_len_factor = 1.0 + 0.25 * ((L - 1) / max_route_len)
            else:
                route_len_factor = 1.0
            score = score_raw * route_len_factor

            # Diversification jitter
            perturb = rng.random() * 0.05 * (score_raw + f3 + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0
            if score > 1.0:
                score = 1.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.18  # between 0.08 and 0.26
        k = max(1, int(round(total_non_dep * frac)))
