            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # New scoring components (distinct from prior ones)
    SAVING_WEIGHT = 0.7
    CENTER_TERM_WEIGHT = 1.0
    DEMAND_REL_WEIGHT = 0.9
    MEAN_DIST_REL_WEIGHT = 0.3
    JITTER_SCALE = 0.1

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Compute route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # Identify route center (node with minimum sum of distances to others)
        center = None
        if L > 0:
            min_sum = None
            for n in non_dep:
                s = 0.0
                for m in non_dep:
                    if m == n:
                        continue
                    s += distance_matrix[n][m]
                if min_sum is None or s < min_sum:
                    min_sum = s
                    center = n
        if center is None:
            center = non_dep[0] if L > 0 else None

        # Precompute mean distances to others for each node and max mean
        mean_distance_map = {}
        max_mean = 0.0
        for n in non_dep:
            if L > 1:
                s = 0.0
                for m in non_dep:
                    if m == n:
                        continue
                    s += distance_matrix[n][m]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0
            mean_distance_map[n] = mean_distance
            if mean_distance > max_mean:
                max_mean = mean_distance
        if max_mean == 0.0:
            max_mean = 1.0  # avoid division by zero

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # Compute local route-saving if possible
            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0

            mean_distance = mean_distance_map[node]

            distance_to_center = distance_matrix[node][center] if center is not None else 0.0
            center_factor = 1.0 / (1.0 + distance_to_center)

            demand = demands[node] if node < len(demands) else 0.0

            # Assemble score with a distinctly different form from prior methods
            score = (saving * SAVING_WEIGHT
                     + center_factor * CENTER_TERM_WEIGHT)

            if route_demand > 0.0:
                score += DEMAND_REL_WEIGHT * (demand / route_demand)

            score += (mean_distance / max_mean) * MEAN_DIST_REL_WEIGHT

            # Add jitter for diversification
            perturb = rng.random() * JITTER_SCALE * (saving + mean_distance + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.15  # between 0.05 and 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

