def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    non_dep_total = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue
        non_dep_total += len(non_dep)

        route_len = len(route)
        route_factor = 1.0 + 0.2 * (route_len - 1)

        for i in non_dep:
            others = [n for n in non_dep if n != i]
            distances = []
            for j in others:
                d = distance_matrix[i][j] if (i < len(distance_matrix) and j < len(distance_matrix[i])) else 0
                distances.append(d)

            if len(distances) == 0:
                avg_near = 0.0
            else:
                distances_sorted = sorted(distances)
                if len(distances_sorted) >= 2:
                    avg_near = (distances_sorted[0] + distances_sorted[1]) / 2.0
                else:
                    avg_near = distances_sorted[0]

            demand = demands[i] if i < len(demands) else 0
            denom = 1.0 + (demand ** 0.6)
            score = (avg_near ** 0.9) * route_factor / denom
            score += rng.random() * 0.15 * (avg_near + 1.0)
            scores.append((i, score))

    if non_dep_total == 0:
        k = 0
    else:
        frac = 0.04 + rng.random() * 0.24
        k = max(1, int(round(non_dep_total * frac)))
        if k > non_dep_total:
            k = non_dep_total

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    capacities = data.get('vehicle_capacities', [])
    max_capacity = max(capacities) if capacities else 1

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Diversity term based on depot distances in this route
        depot_dists = []
        for node in non_dep:
            if node < len(distance_matrix):
                depot_dists.append(distance_matrix[node][0])
            else:
                depot_dists.append(0.0)
        if depot_dists:
            max_dep = max(depot_dists)
            min_dep = min(depot_dists)
            if max_dep > 0:
                diversity = 1.0 + 0.3 * (max_dep - min_dep) / max_dep
            else:
                diversity = 1.0
        else:
            diversity = 1.0

        # Route demand (sum of demands for non-depot nodes in this route)
        route_demand = 0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            if L > 1:
                sum_to_others = 0.0
                min_to_others = float('inf')
                max_to_others = 0.0
                for j, other in enumerate(non_dep):
                    if idx == j:
                        continue
                    d = distance_matrix[node][other]
                    sum_to_others += d
                    if d < min_to_others:
                        min_to_others = d
                    if d > max_to_others:
                        max_to_others = d
                mean_distance = sum_to_others / (L - 1)
                min_distance = min_to_others if min_to_others != float('inf') else 0.0
            else:
                mean_distance = 0.0
                min_distance = 0.0

            depot_distance = distance_matrix[node][0] if node < len(distance_matrix) else 0.0

            node_demand = demands[node] if node < len(demands) else 0

            # New scoring formula: emphasize intra-route centrality, depot proximity, and load, with diversity impact
            base = 0.5 * mean_distance + 0.2 * min_distance + 0.25 * depot_distance
            load_factor = route_demand / max_capacity if max_capacity > 0 else 0.0
            score = base * (1.0 + 0.7 * load_factor + 0.5 * (diversity - 1.0))

            # Penalize high-demand nodes to encourage removing smaller-load nodes first
            score -= 0.8 * node_demand

            perturb = rng.random() * 0.05 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.16  # between 0.12 and 0.28
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

