    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # compute global maximum distance for normalization
    max_dist_global = 0.0
    n_nodes = len(distance_matrix)
    for i in range(n_nodes):
        row = distance_matrix[i]
        for j in range(len(row)):
            d = distance_matrix[i][j]
            if d > max_dist_global:
                max_dist_global = d
    if max_dist_global <= 0.0:
        max_dist_global = 1.0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # mean distance to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other] if (node < len(distance_matrix) and other < len(distance_matrix[node])) else 0.0
                    s += d
                mean_distance_to_others = s / (L - 1)
            else:
                mean_distance_to_others = 0.0

            node_demand = demands[node] if node < len(demands) else 0.0
            distance_to_depot = distance_matrix[0][node] if n_nodes > 0 and node < n_nodes and len(distance_matrix[0]) > node else 0.0

            # score components tailored for a distinct destruction heuristic
            score = (mean_distance_to_others ** 0.6) * 1.15
            if route_demand > 0.0:
                score += (node_demand / (route_demand + 1.0)) * 0.9
            score += (distance_to_depot / (max_dist_global + 1.0)) * 0.4

            # jitter for diversification
            perturb = rng.random() * 0.05 * (mean_distance_to_others + distance_to_depot + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.06 + rng.random() * 0.18  # between 0.06 and 0.24
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Choose a small sample of peers for dispersion measurement
        S = min(3, max(0, L - 1))
        if S > 0:
            sample_nodes = list(rng.choice(non_dep, size=S, replace=False))
        else:
            sample_nodes = []

        # Compute distance sums to the sample for each node
        dist_sums = []
        for node in non_dep:
            if sample_nodes:
                ssum = 0.0
                for s in sample_nodes:
                    if node < len(distance_matrix) and s < len(distance_matrix[node]):
                        ssum += distance_matrix[node][s]
                dist_sums.append((node, ssum))
            else:
                dist_sums.append((node, 0.0))

        # Mean dispersion for the route
        total = sum(ssum for _, ssum in dist_sums)
        mean = total / L if L > 0 else 0.0

        # Per-node dispersion score with small jitter
        for node, ssum in dist_sums:
            score = abs(ssum - mean)
            jitter = rng.random() * 0.05
            score += jitter
            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.04 + rng.random() * 0.08
        k = int(round(total_non_dep * frac))
        if k < 1:
            k = 1
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # Precompute max route length (in non-depot nodes)
    max_route_len = 0
    for route in current_solution:
        non_dep_len = 0
        for n in route:
            if n != 0:
                non_dep_len += 1
        if non_dep_len > max_route_len:
            max_route_len = non_dep_len

    max_demand = max(demands) if len(demands) > 0 else 1.0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        for idx, node in enumerate(non_dep):
            # Mean distance to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            # Centrality score (higher if node is closer on average to others)
            centrality = 1.0 / (mean_distance + 1.0)

            # Route-length factor (prefer removing nodes from longer routes)
            if max_route_len > 1:
                route_factor = 1.0 + 0.5 * ((L - 1) / float(max_route_len - 1))
            else:
                route_factor = 1.0

            # Demand-based penalty (prefer removing low-demand nodes)
            demand = demands[node] if node < len(demands) else 0.0
            score = centrality * route_factor - (demand / max_demand) * 0.3

            # Random jitter for diversification
            jitter = rng.random() * 0.25
            score += jitter

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.18  # between 0.07 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # Gather non-depot nodes per route and route demands
    node_to_route = {}
    route_to_demand = {}
    all_non_dep = []
    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        # compute route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]
        route_to_demand[r_idx] = route_demand

        for n in non_dep:
            all_non_dep.append(n)
            node_to_route[n] = r_idx

    if total_non_dep == 0:
        return [], 0

    # Precompute global average distance to other non-depot nodes for each i
    avg_distance = {}
    for i in all_non_dep:
        sum_dist = 0.0
        count = 0
        for j in all_non_dep:
            if j == i:
                continue
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                d = distance_matrix[i][j]
            else:
                d = 0.0
            sum_dist += d
            count += 1
        avg_distance[i] = (sum_dist / count) if count > 0 else 0.0

    # Compute per-node scores
    for i in all_non_dep:
        # global centrality component: higher when avg distance to others is small
        centrality = 1.0 / (1.0 + avg_distance[i])

        # route/demand component
        r = node_to_route[i]
        route_demand = route_to_demand[r]
        denom = route_demand if route_demand > 0 else 1.0
        node_demand = demands[i] if i < len(demands) else 0.0
        demand_ratio = node_demand / denom

        # cross-node penalty: distance to top-3 highest-demand neighbors
        candidates = []
        for j in all_non_dep:
            if j == i:
                continue
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                d = distance_matrix[i][j]
            else:
                d = 0.0
            dem_j = demands[j] if j < len(demands) else 0.0
            candidates.append((j, d, dem_j))

        top3 = sorted(candidates, key=lambda t: t[2], reverse=True)[:3]
        penalty = 0.0
        if top3:
            sumd = 0.0
            cnt = 0
            for (j2, d2, dem2) in top3:
                sumd += d2
                cnt += 1
            if cnt > 0:
                mean_top3 = sumd / cnt
                penalty = 0.4 * mean_top3

        score = centrality * 0.6 + demand_ratio * 0.4 - penalty

        # jitter for diversification
        score += rng.random() * 0.08 * (centrality + demand_ratio + 1.0)

        if score < 0.0:
            score = 0.0

        scores.append((i, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.18  # between 0.08 and 0.26
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    all_nodes = []
    node_to_route = {}
    route_demands_by_r = {}

    # Gather all non-depot nodes and their route associations
    for ridx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue
        # compute route demand
        rd = 0.0
        for n in non_dep:
            if n < len(demands):
                rd += demands[n]
        route_demands_by_r[ridx] = rd
        for n in non_dep:
            all_nodes.append(n)
            node_to_route[n] = ridx

    N = len(all_nodes)
    if N == 0:
        return scores, 0

    # Compute global connectivity score for each node
    for i in all_nodes:
        sum_dist = 0.0
        for j in all_nodes:
            if j == i:
                continue
            # safe access to distance
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                d = distance_matrix[i][j]
            else:
                d = 0.0
            sum_dist += d
        avg_dist = sum_dist / (N - 1) if N > 1 else 0.0

        ridx = node_to_route.get(i, -1)
        route_demand = route_demands_by_r.get(ridx, 0.0)

        # Attenuate by route demand to reduce removal of high-demand nodes
        score = avg_dist / (1.0 + route_demand)

        # Add a random tilt to diversify removals
        perturb = rng.random() * 0.15 * (avg_dist + 1.0)
        score += perturb

        if score < 0.0:
            score = 0.0

        scores.append((i, score))

    # Choose k as a small random fraction of removable nodes
    k_frac = 0.05 + rng.random() * 0.18  # between 0.05 and 0.23
    k = max(1, int(round(N * k_frac)))
    if k > N:
        k = N

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])
    max_cap = max(vehicle_capacities) if vehicle_capacities else 1

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # pre-compute route length (sum of consecutive intra-route distances)
        route_len = 0.0
        if L > 1:
            for i in range(L - 1):
                a = non_dep[i]
                b = non_dep[i + 1]
                if a < len(distance_matrix) and b < len(distance_matrix[a]):
                    route_len += distance_matrix[a][b]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # marginal impact when removing this node (alternative form)
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0
            elif prev_node is not None:
                saving = distance_matrix[prev_node][node]
            elif next_node is not None:
                saving = distance_matrix[node][next_node]
            else:
                saving = 0.0

            # connectivity measure: mean distance to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        s += distance_matrix[node][other]
                mean_distance_to_others = s / (L - 1)
            else:
                mean_distance_to_others = 0.0

            distance_to_depot = distance_matrix[node][0] if node < len(distance_matrix) and 0 < len(distance_matrix[node]) else 0.0

            # nonlinear amplification based on route length
            route_len_factor = 1.0 + (L - 1) * 0.15

            # base impact adjusted by route length
            impact = 0.0
            if saving > 0.0:
                impact = saving * route_len_factor
            else:
                impact = 0.0

            d = demands[node] if node < len(demands) else 0.0
            if route_demand > 0.0:
                impact *= (1.0 + 0.6 * (d / route_demand))

            # depot-distance bias (prefer removing nodes far from depot)
            depot_bias = 1.0 + 0.35 * (distance_to_depot / (distance_to_depot + 40.0))
            impact *= depot_bias

            # penalize high mean distance to other nodes (reduce fragmentation)
            if mean_distance_to_others > 0.0:
                impact /= (1.0 + 0.5 * mean_distance_to_others)

            # small random perturbation for diversification
            perturb = rng.random() * 0.05 * (saving + mean_distance_to_others + 1.0)
            score = impact + perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.20  # between 0.12 and 0.32
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

