            continue

        # compute route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # determine route centroid (node with minimal sum of distances to others)
        centroid = None
        if L > 0:
            best_centroid = non_dep[0]
            best_sum = None
            for c in non_dep:
                s = 0.0
                for t in non_dep:
                    if t == c:
                        continue
                    s += distance_matrix[c][t]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    best_centroid = c
            centroid = best_centroid

        for idx, node in enumerate(non_dep):
            # distances within the route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance_to_others = s / (L - 1)
            else:
                mean_distance_to_others = 0.0

