            distance_to_centroid = distance_matrix[node][centroid] if centroid is not None else 0.0
            node_demand = demands[node] if node < len(demands) else 0.0

            # overload factor based on route demand vs capacity
            overload = 0.0
            if max_cap > 0.0 and route_demand > max_cap:
                overload = (route_demand - max_cap) / max_cap

            # non-linear combination emphasizing distal and dispersed nodes
            score = ((distance_to_centroid + distance_to_depot) ** 1.25) * ((mean_distance_to_others + 1.0) ** 0.6)
            score /= (route_demand + 1.0)
            if max_cap > 0.0:
                score *= (1.0 + overload)

            # jitter to promote diversification
            jitter = rng.random() * 0.4 * (distance_to_centroid + distance_to_depot + mean_distance_to_others + 1.0)
            score += jitter

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.15
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
