            continue

        # Compute total route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # Pick a random anchor node within the route
        anchor = None
        if L > 0:
            anchor = non_dep[rng.integers(0, L)]

        for idx, node in enumerate(non_dep):
            # Distance to anchor (0 if anchor is not defined or indices invalid)
            dist_to_anchor = 0.0
            if anchor is not None:
                if node < len(distance_matrix) and anchor < len(distance_matrix[node]):
                    dist_to_anchor = distance_matrix[node][anchor]
                else:
                    dist_to_anchor = 0.0

            # Mean distance to other nodes in the same route
            mean_distance = 0.0
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            # Route length factor
            route_len_factor = 1.0 + 0.25 * (L - 1)

            # Score computation
            denom = 1.0 + route_demand
            score = (dist_to_anchor * route_len_factor) / denom if denom > 0.0 else 0.0

            # Attenuation based on mean distance
            attenuation = 1.0 / (1.0 + mean_distance * 0.6)
            score *= attenuation

