    capacities = data.get('vehicle_capacities', [])
    max_cap = max(capacities) if capacities else 0.0

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # total demand on this route
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # cross-route proximity: sum of distances from this node to all nodes not in this route
            cross_sum = 0.0
            for other_route in current_solution:
                for m in other_route:
                    if m == 0:
                        continue
                    # include all nodes in other routes; including the same route but not the same node
                    if other_route is route and m == node:
                        continue
                    cross_sum += distance_matrix[node][m]

            # mean distance to other nodes within the same route for attenuation
            if L > 1:
                s = 0.0
                for t in non_dep:
                    if t == node:
                        continue
                    s += distance_matrix[node][t]
                mean_within = s / (L - 1)
            else:
                mean_within = 0.0

            node_demand = demands[node] if node < len(demands) else 0.0

            # base score from cross-route proximity attenuated by intra-route dispersion
            attenuation = 1.0 / (1.0 + mean_within)
            score = cross_sum * attenuation

            # capacity-aware adjustment to discourage removing high-demand nodes on tight routes
            cap_factor = 0.0
            if max_cap > 0.0 and route_demand > 0.0:
                cap_factor = (route_demand / max_cap) * 0.1
            score -= cap_factor

            # jitter to diversify removals
            perturb = rng.random() * 0.18 * (cross_sum + mean_within + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.18  # between 0.08 and 0.26
        k = max(1, int(round(total_non_dep * frac)))
