def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)

        if L == 0:
            continue

        total_non_dep += L

        # Betweenness-like centrality: count, for each node i in the route,
        # how many pairs (u, v) (u != v, u,v in non_dep, u,v != i) satisfy
        # dist(u, v) == dist(u, i) + dist(i, v)
        centrality = {node: 0 for node in non_dep}

        for a in range(L):
            u = non_dep[a]
            for b in range(a + 1, L):
                v = non_dep[b]
                dist_uv = distance_matrix[u][v]
                for node in non_dep:
                    if distance_matrix[u][node] + distance_matrix[node][v] == dist_uv:
                        centrality[node] += 1

        base_factor = 1.0 + 0.8 * (L - 1)

        for node in non_dep:
            score = centrality[node] * base_factor

            # add jitter for diversification
            jitter = rng.random() * 0.6 * (centrality[node] + L)
            score += jitter

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.10  # 5% to 15% of removable nodes
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

