    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            # node properties
            demand = demands[node] if node < len(demands) else 0.0

            # mean distance to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance_to_others = s / (L - 1)
            else:
                mean_distance_to_others = 0.0

            # distance to depot
            distance_to_depot = distance_matrix[node][0] if len(distance_matrix[node]) > 0 else 0.0

            # distance to nearest neighbor in the route
            distance_to_nearest = 0.0
            if L > 1:
                nearest = None
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if nearest is None or d < nearest:
                        nearest = d
                distance_to_nearest = nearest if nearest is not None else 0.0

            # compute a novel disruption-oriented score (different form from savings-based ones)
            ratio_demand = (demand / route_demand) if route_demand > 0.0 else 0.0
            ratio_distance_depot = distance_to_depot / (distance_to_depot + 50.0)
            ratio_nearest = (distance_to_nearest / (mean_distance_to_others + 1e-9)) if L > 1 else 0.0

            score_base = ratio_demand * 1.0 + ratio_distance_depot * 0.8 + ratio_nearest * 0.6

            perturb = rng.random() * 0.25
            score = score_base + perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.18
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

