            demand = demands[node] if node < len(demands) else 0.0

            score = saving
            if idx == 0 or idx == L - 1:
                score += 0.25 * saving

            if route_demand > 0.0:
                score += 0.3 * (demand / route_demand)

            attenuation = 1.0 / (1.0 + mean_distance + 0.5)
            score *= attenuation

            perturb = rng.random() * 0.12 * (saving + mean_distance + 1.0)
            score += perturb

            if score < 0.0:
