def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])
    max_cap = max(vehicle_capacities) if vehicle_capacities else 1

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # marginal saving when removing this node
            saving = 0.0
            if prev_node is not None and next_node is not None:
                d_prev_node_node = (distance_matrix[prev_node][node]
                                    if prev_node < len(distance_matrix) and node < len(distance_matrix[prev_node])
                                    else 0.0)
                d_node_next = (distance_matrix[node][next_node]
                               if node < len(distance_matrix) and next_node < len(distance_matrix[node])
                               else 0.0)
                d_prev_next = (distance_matrix[prev_node][next_node]
                               if prev_node < len(distance_matrix) and next_node < len(distance_matrix[prev_node])
                               else 0.0)
                saving = d_prev_node_node + d_node_next - d_prev_next
                if saving < 0.0:
                    saving = 0.0
            elif prev_node is not None:
                saving = (distance_matrix[prev_node][node]
                          if prev_node < len(distance_matrix) and node < len(distance_matrix[prev_node])
                          else 0.0)
            elif next_node is not None:
                saving = (distance_matrix[node][next_node]
                          if node < len(distance_matrix) and next_node < len(distance_matrix[node])
                          else 0.0)

            # mean distance to other nodes in the route (cohesion measure)
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d_node_other = (distance_matrix[node][other]
                                    if node < len(distance_matrix) and other < len(distance_matrix[node])
                                    else 0.0)
                    s += d_node_other
                mean_distance_to_others = s / (L - 1)
            else:
                mean_distance_to_others = 0.0

            # distance to depot
            distance_to_depot = (distance_matrix[node][0]
                                 if node < len(distance_matrix) and 0 < len(distance_matrix[node])
                                 else 0.0)

            # linear route-length factor (as opposed to nonlinear in the original)
            route_len_factor = 1.0 + 0.15 * (L - 1)

            # base score from positive saving
            score = saving * route_len_factor if saving > 0.0 else 0.0

            # balance by route slack (capacity slack increases with removal potential)
            if max_cap > 0.0:
                slack = max_cap - route_demand
                balance_factor = 1.0 + 0.5 * (slack / max_cap)
            else:
                balance_factor = 1.0
            score *= balance_factor

            # depot-distance bias
            depot_term = distance_to_depot / (1.0 + distance_to_depot)
            score *= (1.0 + 0.5 * depot_term)

            # cohesion penalty
            if mean_distance_to_others > 0.0:
                score /= (1.0 + 0.4 * mean_distance_to_others)

            # small random perturbation for diversification
            perturb = rng.random() * 0.05 * (saving + mean_distance_to_others + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.06 + rng.random() * 0.24  # between 0.06 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

