    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # route max demand for normalization
        route_max_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                d = demands[n]
                if d > route_max_demand:
                    route_max_demand = d
        if route_max_demand <= 0.0:
            route_max_demand = 1.0

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # removal_cost: local impact of removing node (neighbors connect)
            removal_cost = 0.0
            if prev_node is not None and next_node is not None:
                removal_cost = (distance_matrix[prev_node][node]
                                + distance_matrix[node][next_node]
                                - distance_matrix[prev_node][next_node])
                if removal_cost < 0.0:
                    removal_cost = 0.0
            elif prev_node is not None:
                removal_cost = distance_matrix[prev_node][node]
            elif next_node is not None:
                removal_cost = distance_matrix[node][next_node]
            else:
                removal_cost = 0.0

            # mean distance to others (diversification signal)
            mean_distance_to_others = 0.0
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance_to_others = s / (L - 1)
            else:
                mean_distance_to_others = 0.0

            # node-specific metrics
            node_demand = demands[node] if node < len(demands) else 0.0
            demand_prop = node_demand / route_max_demand

            distance_to_depot = distance_matrix[0][node] if len(distance_matrix) > 0 else 0.0

            # new scoring formula (different form)
            attenuation = 1.0 / (1.0 + (mean_distance_to_others ** 1.3) + (distance_to_depot ** 1.1))
            score = (1.0 + removal_cost) * (1.0 + demand_prop) * attenuation

            # jitter to diversify removals
            perturb = rng.random() * 0.04 * (removal_cost + mean_distance_to_others + distance_to_depot + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.15  # between 0.07 and 0.22
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

