    else:
        frac = 0.05 + rng.random() * 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Gather per-route non-depot nodes and track maximum route length
    per_route_nodes = []
    max_route_len = 0
    for route in current_solution:
        non_dep = [n for n in route if n != 0 and n is not None]
        per_route_nodes.append(non_dep)
        if len(non_dep) > max_route_len:
            max_route_len = len(non_dep)

    # Choose a random anchor per route
    anchors = []
    for non_dep in per_route_nodes:
        if not non_dep:
            anchors.append(0)  # depot as anchor when route has no non-depot nodes
        else:
            idx = int(rng.integers(0, len(non_dep)))
            anchors.append(non_dep[idx])

    # Compute scores for all non-depot nodes
    max_demand = max(demands) if demands else 0
    scores = []
    for r_idx, non_dep in enumerate(per_route_nodes):
        anchor = anchors[r_idx]
        if not non_dep:
            continue

        route_len = len(non_dep)
        route_factor = 1.0
        if max_route_len > 1:
            route_factor = 1.0 + 0.5 * (route_len - 1) / (max_route_len - 1)

        for n in non_dep:
            dist_to_anchor = distance_matrix[n][anchor] if anchor != 0 else distance_matrix[n][0]
            demand = demands[n] if n < len(demands) else 0
            demand_factor = 1.0
            if max_demand > 0:
                demand_factor = 1.0 + 0.3 * (max_demand - demand) / max_demand

            score = dist_to_anchor * route_factor * demand_factor
            scores.append((n, score))

    total_nodes = len(scores)
    if total_nodes <= 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # fraction between 0.15 and 0.40
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # determine max demand for normalization
    max_demand = 1
    if isinstance(demands, dict):
        if demands:
            max_demand = max(demands.values()) if demands else 1
    else:
        if isinstance(demands, (list, tuple)) and len(demands) > 0:
            max_demand = max(demands)
        else:
            max_demand = 1

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue

        route_len = len(non_dep)
        axis = rng.random()  # per-route random axis in [0,1)

        for i in non_dep:
            total_nodes += 1

            # average distance to peers within the same route
            denom = route_len - 1 if route_len > 1 else 1
            sum_dist = 0.0
            for j in non_dep:
                if j == i:
                    continue
                d = distance_matrix[i][j] if i < len(distance_matrix) and j < len(distance_matrix[i]) else 0.0
                sum_dist += d
            avg_peer_dist = sum_dist / denom

            # distance to depot
            dist_to_depot = distance_matrix[i][0] if len(distance_matrix) > 0 and i < len(distance_matrix) else 0.0

            # node demand
            if isinstance(demands, dict):
                demand = demands.get(i, 0)
            elif isinstance(demands, (list, tuple)) and i < len(demands):
                demand = demands[i]
            else:
                demand = 0
            norm_demand = demand / max_demand if max_demand > 0 else 0.0

            # score: convex combination of two aspects, penalize high-demand nodes
            score = axis * avg_peer_dist + (1.0 - axis) * dist_to_depot - 0.4 * norm_demand
            score += rng.random() * 0.0001  # tiny jitter to break ties

            scores.append((i, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_nodes = 0

    # maximum demand for scaling (if available)
    max_demand = 0
    for d in demands:
        if d > max_demand:
            max_demand = d

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # consider non-depot nodes only
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue

        route_len_factor = 1.0 / (1.0 + 0.2 * (m - 1))

        for node in route:
            if node == 0:
                continue
            total_nodes += 1

            # connectivity score: sum distances to all other non-depot nodes in the same route
            conn = 0.0
            for other in non_dep:
                if other == node:
                    continue
                if node < len(dist) and other < len(dist[node]):
                    conn += dist[node][other]
                else:
                    conn += 0.0

            # demand-based scaling (favor removing low-demand nodes)
            demand = demands[node] if node < len(demands) else 0
            if max_demand > 0:
                demand_factor = 1.0 + 0.4 * ((max_demand - demand) / float(max_demand))
            else:
                demand_factor = 1.0

            score = conn * demand_factor * route_len_factor

            # small random perturbation for diversification
            jitter = rng.random() * 0.0005
            score += jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 5)
        k = int(rng.integers(1, max_k + 1))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        # consider only non-depot nodes in this route
        non_dep = [n for n in route if n != 0]
        m = len(non_dep)
        if m == 0:
            continue
        total_nodes += m

        for idx, node in enumerate(non_dep):
            # collect distances from this node to all other non-depot nodes in the same route
            dists = []
            for j, other in enumerate(non_dep):
                if idx == j:
                    continue
                if node < len(distance_matrix) and other < len(distance_matrix[node]):
                    d = distance_matrix[node][other]
                else:
                    d = 0
                dists.append(d)

            if not dists:
                dispersion = 0.0
            else:
                mean_dist = sum(dists) / len(dists)
                max_dist = max(dists)
                dispersion = max_dist - mean_dist

            demand = demands[node] if node < len(demands) else 0
            score = dispersion - 0.15 * demand
            score += rng.random() * 0.05  # small jitter in [0, 0.05)
            score *= (1.0 + (m - 1) * 0.03)  # scale by route length

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        total_non_dep += len(non_dep)
        if not non_dep:
            continue

        for n in non_dep:
            dn = demands[n] if n < len(demands) else 0
            s = 0.0
            for m in non_dep:
                if m == n:
                    continue
                dm = demands[m] if m < len(demands) else 0
                w = 1.0 / (1.0 + abs(dn - dm))
                d_nm = distance_matrix[n][m] if (n < len(distance_matrix) and m < len(distance_matrix[n])) else 0
                s += d_nm * w
            noise = rng.random() * 0.001 * (s + 1.0)
            scores.append((n, s + noise))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.16  # between 0.12 and 0.28
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # collect unique non-depot nodes present in the solution
    nodes = []
    seen = set()
    for route in current_solution:
        if not route:
            continue
        for node in route:
            if node == 0 or node is None:
                continue
            if node not in seen:
                seen.add(node)
                nodes.append(node)

    total_nodes = len(nodes)
    scores = []
    if total_nodes == 0:
        return scores, 0

    # helper to safely fetch distance
    def dist(a, b):
        if a < len(distance_matrix) and b < len(distance_matrix[a]):
            return distance_matrix[a][b]
        return 0.0

    # compute connectivity score s_i for each node: sum of 1/(1+dist(i,j)) over peers
    s_values = {}
    max_s = -1.0
    for i in nodes:
        s_i = 0.0
        for j in nodes:
            if j == i:
                continue
            s_i += 1.0 / (1.0 + dist(i, j))
        s_values[i] = s_i
        if s_i > max_s:
            max_s = s_i

    # determine max demand for normalization
    if isinstance(demands, dict):
        max_demand = max(demands.values()) if demands else 1
    else:
        max_demand = max(demands) if isinstance(demands, (list, tuple)) and demands else 1

    if max_demand <= 0:
        max_demand = 1

    # compute final scores with demand damping and small perturbation
    for i in nodes:
        s_i = s_values[i]
        diff = (max_s - s_i) if max_s >= 0 else 0.0

        # fetch demand for node i
        if isinstance(demands, dict):
            d = demands.get(i, 0)
        else:
            if isinstance(demands, (list, tuple)) and i < len(demands):
                d = demands[i]
            else:
                d = 0

        demand_factor = 1.0 + (d / max_demand) * 0.9  # up to ~1.9

        score = diff / demand_factor
        score += rng.random() * 0.01 * (1.0 + diff)  # small perturbation
        if score < 0.0:
            score = 0.0

        scores.append((i, score))

    # determine k as a random fraction of total non-depot nodes
    max_k = max(1, total_nodes // 4)
    frac = 0.18 + rng.random() * 0.32  # between 0.18 and 0.50
    k = int(round(total_nodes * frac))
    if k < 1:
        k = 1
    if k > total_nodes:
        k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # determine max demand for normalization
    max_demand = 1
    if isinstance(demands, dict):
        if demands:
            max_demand = max(demands.values()) if demands else 1
    else:
        if isinstance(demands, (list, tuple)) and len(demands) > 0:
            max_demand = max(demands)
        else:
            max_demand = 1

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        # non-depot nodes in this route
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue

        # compute per-node exposure: max distance to other peers in the same route
        exposure = {}
        for i in non_dep:
            max_dist = 0.0
            for j in non_dep:
                if i == j:
                    continue
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0.0
                if d > max_dist:
                    max_dist = d
            exposure[i] = max_dist

        # route mean exposure
        if exposure:
            route_mean_exposure = sum(exposure.values()) / len(exposure)
        else:
            route_mean_exposure = 0.0

        for i in non_dep:
            max_dist_to_others = exposure.get(i, 0.0)
            endpoint_factor = 1.25 if (i == non_dep[0] or i == non_dep[-1]) else 1.0
            score = (max_dist_to_others - route_mean_exposure) * endpoint_factor

            # demand-based bias: favor removing low-demand nodes
            demand = 0
            if isinstance(demands, dict):
                demand = demands.get(i, 0)
            else:
                if isinstance(demands, (list, tuple)) and i < len(demands):
                    demand = demands[i]
                else:
                    demand = 0
            norm_demand = demand / max_demand if max_demand > 0 else 0.0
            removal_bias = 1.0 + 0.75 * (1.0 - norm_demand)
            score *= removal_bias

            # small random perturbation
            score += rng.random() * 0.01

            scores.append((i, score))
            total_nodes += 1

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

