    # determine max demand for normalization
    max_demand = 0
    if isinstance(demands, dict):
        if demands:
            max_demand = max(demands.values()) if demands else 0
    else:
        if isinstance(demands, (list, tuple)) and len(demands) > 0:
            max_demand = max(demands)
        else:
            max_demand = 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue

        for i in non_dep:
            # collect distances from i to all other peers in the same route
            dists = []
            for j in non_dep:
                if j == i:
                    continue
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0
                dists.append(d)

            cnt = len(dists)
            if cnt > 0:
                mean = sum(dists) / cnt
                var = sum((dd - mean) ** 2 for dd in dists) / cnt
                std_dev = var ** 0.5
            else:
                std_dev = 0.0

            # retrieve demand for node i
            if isinstance(demands, dict):
                demand = demands.get(i, 0)
            else:
                if isinstance(demands, (list, tuple)) and i < len(demands):
                    demand = demands[i]
                else:
                    demand = 0

            # inverted-demand factor: favor removing low-demand nodes
            if max_demand > 0:
                inv_demand_factor = 1.0 + 0.5 * ((max_demand - demand) / max_demand)
            else:
                inv_demand_factor = 1.0

            score = std_dev * inv_demand_factor

            # small random perturbation for diversification
            jitter = rng.random() * 0.01 * (std_dev + 1.0)
            score += jitter

            scores.append((i, score))
            total_nodes += 1

