def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data.get('demands', [])
    max_demand = max(demands) if demands else 0

    # Build per-route lists of non-depot nodes
    routes_nodes = []
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        routes_nodes.append(non_dep)

    scores = []
    total_nodes = sum(len(nl) for nl in routes_nodes)

    # For each non-depot node, compute inter-route separation score
    for i, nodes in enumerate(routes_nodes):
        if not nodes:
            continue
        for n in nodes:
            # average distance to the closest node in each other route
            sum_min = 0.0
            count = 0
            for j, other_nodes in enumerate(routes_nodes):
                if j == i or not other_nodes:
                    continue
                min_d = None
                for m in other_nodes:
                    d = dist[n][m] if (n < len(dist) and m < len(dist[n])) else 0
                    if min_d is None or d < min_d:
                        min_d = d
                if min_d is not None:
                    sum_min += min_d
                    count += 1
            avg_min_dist = sum_min / count if count > 0 else 0.0

            demand = demands[n] if n < len(demands) else 0
            if max_demand > 0:
                demand_factor = 1.0 + 0.8 * ((max_demand - demand) / float(max_demand))
            else:
                demand_factor = 1.0

            score = avg_min_dist * demand_factor
            jitter = rng.random() * 0.01 * (avg_min_dist + 1.0)
            score += jitter

            scores.append((n, score))

    total = len(scores)
    if total <= 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # 0.15 to 0.30
        k = int(round(total * frac))
        if k < 1:
            k = 1
        if k > total:
            k = total

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_candidates = 0

    # Precompute global max demand for scaling
    max_demand = 0
    for d in demands:
        if d > max_demand:
            max_demand = d

    for route in current_solution:
        # consider non-depot nodes only
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue

        m = len(non_dep)
        # Number of nearest neighbors to consider (at most 3, at least 0)
        K = min(3, m - 1) if m > 1 else 0

        for n in non_dep:
            total_candidates += 1

            # compute density as sum distances to K nearest neighbors in the same route
            density_sum = 0.0
            if K > 0:
                dists = []
                for other in non_dep:
                    if other == n:
                        continue
                    if n < len(distance_matrix) and other < len(distance_matrix[n]):
                        d = distance_matrix[n][other]
                    else:
                        d = 0.0
                    dists.append(d)
                dists.sort()
                density_sum = sum(dists[:K]) if dists else 0.0

            # demand-based weighting (favor removing low-demand nodes)
            demand = demands[n] if n < len(demands) else 0
            if max_demand > 0:
                demand_factor = 1.0 + 0.4 * (max_demand - demand) / float(max_demand)
            else:
                demand_factor = 1.0

            score = density_sum * demand_factor

            # small random perturbation for diversification
            score += rng.random() * 0.01 * (density_sum + 1.0)

            scores.append((n, score))

    if total_candidates == 0:
        k = 0
    else:
        frac = 0.2 + rng.random() * 0.3  # between 0.2 and 0.5
        k = int(round(total_candidates * frac))
        if k < 1:
            k = 1
        if k > total_candidates:
            k = total_candidates

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])
    max_capacity = max(vehicle_capacities) if vehicle_capacities else 0

    scores = []
    for route in current_solution:
        # consider non-depot nodes in their route order
        non_dep = [n for n in route if n != 0]
        m = len(non_dep)
        if m == 0:
            continue

        # route load to scale the score
        load = 0.0
        for n in non_dep:
            if n < len(demands):
                load += demands[n]
        factor = 1.0
        if max_capacity > 0:
            factor = 1.0 + (load / max_capacity)

        for idx, node in enumerate(non_dep):
            # nodes after and before in the route
            after = non_dep[idx+1:] if idx+1 < m else []
            before = non_dep[:idx] if idx > 0 else []

            forward_mean = 0.0
            if after:
                s = 0.0
                for o in after:
                    if node < len(distance_matrix) and o < len(distance_matrix[node]):
                        s += distance_matrix[node][o]
                forward_mean = s / len(after) if after else 0.0

            backward_mean = 0.0
            if before:
                t_sum = 0.0
                for o in before:
                    if node < len(distance_matrix) and o < len(distance_matrix[node]):
                        t_sum += distance_matrix[node][o]
                backward_mean = t_sum / len(before) if before else 0.0

            imbalance = abs(forward_mean - backward_mean)
            score = imbalance * factor

            jitter = rng.random() * 0.01 * (imbalance + 1.0)
            score += jitter

            scores.append((node, score))

    total_nodes = len(scores)
    if total_nodes == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.15  # fraction between 0.10 and 0.25
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    # Precompute maximum distance in the graph for normalization
    max_graph_dist = 0
    n = len(dist)
    for i in range(n):
        row = dist[i]
        for j in range(n):
            if i == j:
                continue
            if row[j] > max_graph_dist:
                max_graph_dist = row[j]

    scores_dict = {}  # best score per node
    scores_list = []  # temporary flat list (not strictly needed, but kept for clarity)

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # compute route total demand (ignore depots/None)
        route_demand = 0
        for nd in route:
            if nd is None or nd == 0:
                continue
            if nd < len(demands):
                route_demand += demands[nd]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue

            # local disruption delta when removing this node
            if m == 1:
                delta = 0.0
            elif idx == 0:
                next_node = route[1]
                delta = dist[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                delta = dist[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                delta = dist[prev_node][node] + dist[node][next_node] - dist[prev_node][next_node]
            if delta < 0:
                delta = 0.0

            # route slack factor based on remaining capacity
            slack = cap - route_demand
            if slack < 0:
                slack = 0
            route_slack_factor = 1.0 + (slack / float(cap + 1)) * 0.5  # avoid division by zero when cap==0

            # diversity factor: node's maximum distance to other nodes in the same route
            max_dist_to_route = 0.0
            for other in route:
                if other is None or other == 0 or other == node:
                    continue
                d_to = dist[node][other]
                if d_to > max_dist_to_route:
                    max_dist_to_route = d_to

            diversity_norm = 0.0
            if max_graph_dist > 0:
                diversity_norm = max_dist_to_route / max_graph_dist
            diversity_factor = 1.0 + 0.8 * diversity_norm  # up to ~1.8

            jitter = rng.random() * 0.01  # small random perturbation
            score = (delta * route_slack_factor) * diversity_factor + jitter

            if node not in scores_dict or score > scores_dict[node]:
                scores_dict[node] = score

    scores = [(n, s) for n, s in scores_dict.items()]
    total_nodes = len(scores)
    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
        k = int(rng.integers(1, max_k + 1))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_nodes = 0
    beta = 0.5  # diffusion strength

    for route in current_solution:
        # collect non-depot nodes in the route
        nodes = [n for n in route if n is not None and n != 0]
        if not nodes:
            continue

        total_nodes += len(nodes)

        # initial scores are node demands (0 if out of range)
        init = {}
        for n in nodes:
            d = demands[n] if n < len(demands) else 0.0
            init[n] = float(d)

        # two-step diffusion over the route nodes
        score = init.copy()
        for _ in range(2):
            new_score = {}
            for i in nodes:
                s = 0.0
                for j in nodes:
                    if j == i:
                        continue
                    # distance between i and j with safe indexing
                    d = 0.0
                    if i < len(distance_matrix) and j < len(distance_matrix[i]):
                        d = distance_matrix[i][j]
                    s += score.get(j, 0.0) / (d + 1.0)
                new_score[i] = score.get(i, 0.0) + beta * s
            score = new_score

        # record final diffusion scores with small jitter for diversification
        for n in nodes:
            s = score.get(n, 0.0)
            jitter = rng.random() * 0.01  # small perturbation
            scores.append((n, s + jitter))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 5)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

