        if not route:
            continue
        m = len(route)

        # Compute total demand on this route (ignore None/0 nodes)
        route_demand = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Local savings if removing this node
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]

            demand = demands[node] if node < len(demands) else 0

            slack = cap - route_demand
            if slack < 0:
                slack = 0
            factor = 1.0 / (slack + 1)

            # Centrality: average distance to other nodes in the same route
            if m > 1:
                other_nodes = [n for n in route if n is not None and n != 0 and n != node]
                if other_nodes:
                    dist_sum = 0.0
                    for other in other_nodes:
                        dist_sum += distance_matrix[node][other]
                    centrality = dist_sum / len(other_nodes)
                else:
                    centrality = 0.0
            else:
                centrality = 0.0

            jitter = rng.random() * 0.5 - 0.25  # [-0.25, 0.25)
            score = savings * 0.75 + demand * 0.4 * factor - centrality * 0.15 + jitter
            scores.append((node, score))

    max_k = max(1, total_nodes // 5) if total_nodes > 0 else 0
    if total_nodes == 0:
        k = 0
    else:
        k = int(rng.integers(1, max_k + 1))

