            # Compute disruption score (nonlinear, with endpoints handled gracefully)
            disruption = 0.0
            if left not in (None, 0) and right not in (None, 0):
                disruption = distance_matrix[left][right] - (distance_matrix[left][node] + distance_matrix[node][right])
            else:
                if left not in (None, 0):
                    disruption = distance_matrix[left][node]
                elif right not in (None, 0):
