def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep_nodes = 0

    max_demand = max(demands) if demands else 0

    for route in current_solution:
        if not route:
            continue

        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue

        for pos, node in enumerate(route):
            if node == 0:
                continue  # skip depot

            total_non_dep_nodes += 1

            prev_node = route[pos - 1] if pos > 0 else 0
            next_node = route[pos + 1] if pos < len(route) - 1 else 0

            d_prev = dist[prev_node][node] if prev_node < len(dist) and node < len(dist[prev_node]) else 0.0
            d_next = dist[node][next_node] if node < len(dist) and next_node < len(dist[node]) else 0.0
            d_prev_next = dist[prev_node][next_node] if prev_node < len(dist) and next_node < len(dist[prev_node]) else 0.0

            delta_three = d_prev + d_next - d_prev_next
            if delta_three < 0:
                delta_three = 0.0

            cross_influence = 0.0
            for other in non_dep:
                if other == node:
                    continue
                if node < len(dist) and other < len(dist[node]):
                    demand_i = demands[node] if node < len(demands) else 0
                    demand_j = demands[other] if other < len(demands) else 0
                    similarity = 1.0 / (1.0 + abs(demand_i - demand_j)) if (demand_i is not None and demand_j is not None) else 0.0
                    cross_influence += dist[node][other] * similarity

            demand = demands[node] if node < len(demands) else 0
            factor = 1.0
            if max_demand > 0:
                factor += 0.4 * ((max_demand - demand) / float(max_demand))

            score = delta_three * factor + cross_influence * 0.25
            score += rng.random() * 1e-4

            scores.append((node, score))

    if total_non_dep_nodes <= 0:
        k = 0
    else:
        frac = 0.20 + rng.random() * 0.15  # between 0.20 and 0.35
        k = int(round(total_non_dep_nodes * frac))
        if k < 1:
            k = 1
        if k > total_non_dep_nodes:
            k = total_non_dep_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    dist = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    # Precompute maximum distance in the graph for normalization
    max_graph_dist = 0
    n = len(dist)
    for i in range(n):
        row = dist[i]
        for j in range(n):
            if i == j:
                continue
            if row[j] > max_graph_dist:
                max_graph_dist = row[j]

    scores_dict = {}  # best score per node

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # compute route total demand (ignore depots/None)
        route_demand = 0
        for nd in route:
            if nd is None or nd == 0:
                continue
            if nd < len(demands):
                route_demand += demands[nd]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue

            # local disruption delta with a different weighting scheme
            if m == 1:
                delta = 0.0
            elif idx == 0:
                next_node = route[1]
                delta = dist[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                delta = dist[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                # alternative delta: uses max of two legs to emphasize detour around the node
                delta = max(dist[prev_node][node], dist[node][next_node])
            if delta < 0:
                delta = 0.0

            # route slack factor based on remaining capacity
            slack = cap - route_demand
            if slack < 0:
                slack = 0
            route_slack_factor = 1.0 + (slack / float(cap + 1)) * 0.3  # conservative

            # diversity factor: average distance to other nodes in the same route
            sum_dist = 0.0
            count = 0
            for other in route:
                if other is None or other == 0 or other == node:
                    continue
                sum_dist += dist[node][other]
                count += 1
            avg_dist = (sum_dist / count) if count > 0 else 0.0
            diversity_norm = 0.0
            if max_graph_dist > 0:
                diversity_norm = avg_dist / max_graph_dist
            diversity_factor = 1.0 + 0.6 * diversity_norm  # broadened

            jitter = rng.random() * 0.02  # small diversification
            score = (delta * route_slack_factor) * diversity_factor + jitter

            if node not in scores_dict or score > scores_dict[node]:
                scores_dict[node] = score

    scores = [(n, s) for n, s in scores_dict.items()]
    total_nodes = len(scores)
    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))
        if k > total_nodes:
            k = total_nodes

    return scores, k

