def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])

    max_demand = max(demands) if demands else 0
    max_cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # compute route load (sum of demands for non-depot nodes)
        route_load = 0
        for node in route:
            if node is None or node == 0:
                continue
            if 0 <= node < len(demands):
                route_load += demands[node]
            total_nodes += 1

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue

            # Local removal savings (reconnect prev and next)
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            # Centrality factor: emphasize middle positions in the route with adjusted parameters
            if m > 1:
                middle = (m - 1) / 2.0
                dist_from_middle = abs(idx - middle)
                scale = 1.0 - (dist_from_middle / (middle if middle > 0 else 1.0))
                centrality_factor = 0.60 + 0.40 * max(0.0, min(1.0, scale))
            else:
                centrality_factor = 0.60

            # Demand factor: scale with node demand relative to max demand (adjusted)
            if max_demand > 0:
                node_demand = demands[node] if node < len(demands) else 0
                demand_factor = 0.90 + 0.70 * (node_demand / max_demand)
            else:
                demand_factor = 1.0

            # Load factor: scale with how loaded the route is relative to max capacity (adjusted)
            if max_cap > 0:
                load_factor = 0.70 + 0.30 * (route_load / max_cap)
            else:
                load_factor = 1.0

            # Slight randomness to diversify selection
            noise = 1.0
            if rng is not None:
                try:
                    # rng is expected to be a numpy Generator
                    noise = 1.0 + (rng.random() - 0.5) * 0.20  # +/-10% variation
                except Exception:
                    pass

            if savings <= 0:
                score = 0.0
            else:
                score = savings * centrality_factor * demand_factor * load_factor * noise

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        k = int(total_nodes * 0.3)
        if k == 0:
            k = 1

    return scores, k

