def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    centers = []

    for route in current_solution:
        # collect non-depot nodes in the route
        non_dep = [n for n in route if n is not None and n != 0]
        if not non_dep:
            centers.append(0)
            continue

        # determine the route center: node minimizing sum of distances to others
        if len(non_dep) == 1:
            center = non_dep[0]
        else:
            best_center = None
            best_sum = None
            for c in non_dep:
                s = 0.0
                for m in non_dep:
                    if m == c:
                        continue
                    if c < len(distance_matrix) and m < len(distance_matrix[c]):
                        s += distance_matrix[c][m]
                    else:
                        s += 0.0
                if best_sum is None or s < best_sum:
                    best_sum = s
                    best_center = c
            center = best_center if best_center is not None else non_dep[0]
        centers.append(center)

        # compute route demand
        route_demand = 0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # distance from center to farthest node in route (for normalization)
        max_dist = 0.0
        for m in non_dep:
            if center < len(distance_matrix) and m < len(distance_matrix[center]):
                d = distance_matrix[center][m]
            else:
                d = 0.0
            if d > max_dist:
                max_dist = d

        # compute scores for each node
        for n in non_dep:
            if center < len(distance_matrix) and n < len(distance_matrix[center]):
                center_dist = distance_matrix[center][n]
            else:
                center_dist = 0.0

            norm_dist = center_dist / (max_dist + 1e-9)

            dem = demands[n] if n < len(demands) else 0
            dem_factor = 1.0
            if route_demand > 0:
                dem_factor = 1.0 + (dem / route_demand)

            score = norm_dist * dem_factor

            jitter = (rng.random() - 0.5) * 0.1  # [-0.05, 0.05)
            score += jitter

            scores.append((n, score))

    total_scored = len(scores)
    if total_scored == 0:
        k = 0
        return scores, k

    frac = 0.18 + rng.random() * 0.22  # between 0.18 and 0.40
    k = int(round(total_scored * frac))
    if k < 1:
        k = 1
    if k > total_scored:
        k = total_scored

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    n_nodes = len(distance_matrix)

    # Gather per-node route context
    node_to_len = {}
    node_to_idx = {}
    max_route_len = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)
        if m == 0:
            continue
        if m > max_route_len:
            max_route_len = m
        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            node_to_len[node] = m
            node_to_idx[node] = idx

    scores = []
    total_nodes = len(node_to_len)

    if total_nodes > 0:
        # Compute scores per node
        for node, m in node_to_len.items():
            idx = node_to_idx[node]

            # Base score: sum of distances from this node to all others
            base = 0.0
            row = distance_matrix[node]
            for j in range(n_nodes):
                if j == node:
                    continue
                base += row[j]

            # Route-length factor
            route_len_factor = 1.0 + 0.5 * (m - 1) / max(1, max_route_len)

            # Position factor: interior nodes get a bit higher weight
            if idx > 0 and idx < m - 1:
                pos_weight = 1.2
            else:
                pos_weight = 0.8

            score = base * route_len_factor * pos_weight

            # Small random perturbation for diversification
            perturb = rng.normal(0.0, 0.05)
            score *= (1.0 + perturb)

            if score < 0:
                score = 0.0

            scores.append((node, score))

        # Determine how many to remove
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))
    else:
        k = 0

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # Collect all non-depot nodes present in the current solution
    all_nodes = []
    for route in current_solution:
        for node in route:
            if node is None or node == 0:
                continue
            all_nodes.append(node)

    total_nodes = len(all_nodes)
    # Determine landmarks: a small random subset of unique non-depot nodes
    unique_nodes = sorted(set(all_nodes))
    if len(unique_nodes) == 0:
        landmarks = []
    else:
        landmark_count = min(5, max(1, len(unique_nodes)))
        if len(unique_nodes) >= landmark_count:
            landmarks = rng.choice(unique_nodes, size=landmark_count, replace=False)
            landmarks = list(landmarks)
        else:
            landmarks = unique_nodes

    # Precompute max demand for normalization
    max_demand = max(demands) if demands else 1

    scores = []
    for route in current_solution:
        for node in route:
            if node is None or node == 0:
                continue

            # Compute mean distance from this node to all landmarks
            if len(landmarks) == 0:
                mean_dist = 0.0
            else:
                dist_sum = 0.0
                for lm in landmarks:
                    dist = distance_matrix[node][lm] if node < len(distance_matrix) and lm < len(distance_matrix[node]) else 0.0
                    dist_sum += dist
                mean_dist = dist_sum / len(landmarks)

            # Demand normalization
            demand = demands[node] if node < len(demands) else 0
            demand_norm = demand / max_demand if max_demand > 0 else 0.0

            # Score combines mean distance and demand-based reduction, with a small jitter
            score = mean_dist * (1.0 - 0.25 * demand_norm)
            jitter = rng.random() * 0.01 * (mean_dist + 1.0)
            score += jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    max_demand = max(demands) if demands else 0

