    for route in current_solution:
        if not route:
            continue
        m = len(route)

        for node in route:
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Global mean distance from this node to all other non-depot nodes
            sum_dist = 0.0
            count = 0
            for other in unique_nodes:
                if other == node:
                    continue
                if node < len(distance_matrix) and other < len(distance_matrix[node]):
                    d = distance_matrix[node][other]
