            else:
                demand_factor = 1.0

            score = mean_dist * length_factor * demand_factor

            jitter = rng.random() * 0.01 * (mean_dist + 1.0)
            score += jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.20  # between 0.15 and 0.35
