def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Collect all non-depot nodes present in the solution (unique)
    nodes_set = set()
    for route in current_solution:
        for node in route:
            if node is None:
                continue
            if node != 0:
                nodes_set.add(node)
    all_nodes = list(nodes_set)

    total_nodes = len(all_nodes)
    scores = []

    max_demand = max(demands) if demands else 0

    for i in all_nodes:
        # find two nearest other non-depot nodes to i
        first = None
        second = None
        for j in all_nodes:
            if j == i:
                continue
            d = distance_matrix[i][j] if (i < len(distance_matrix) and j < len(distance_matrix[i])) else 0
            if first is None or d < first:
                second = first
                first = d
            elif second is None or d < second:
                second = d
        if first is None:
            avg = 0.0
        elif second is None:
            avg = first
        else:
            avg = 0.5 * (first + second)

        demand = demands[i] if i < len(demands) else 0
        demand_term = (demand / max_demand) if max_demand > 0 else 0.0

        # Score: higher when peripheral (avg large), slightly reduced by high demand, with a small jitter
        score = avg * 0.9 - 0.25 * demand_term
        score += rng.random() * 0.05 * (avg + 1.0)
        scores.append((i, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    routes = current_solution

    scores = []
    # collect all non-depot nodes present in the solution
    present_nodes = set()
    for route in routes:
        for node in route:
            if node is None or node == 0:
                continue
            present_nodes.add(node)

    if not present_nodes:
        return scores, 0

    # Compute removal gain (savings) for removing each node from its current route
    removal_savings = {}
    for route in routes:
        if not route:
            continue
        m = len(route)
        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            prev_node = route[idx - 1] if idx - 1 >= 0 else 0
            next_node = route[idx + 1] if idx + 1 < m else 0

            d1 = distance_matrix[prev_node][node] if (prev_node < len(distance_matrix) and node < len(distance_matrix[prev_node])) else 0
            d2 = distance_matrix[node][next_node] if (node < len(distance_matrix) and next_node < len(distance_matrix[node])) else 0
            d0 = distance_matrix[prev_node][next_node] if (prev_node < len(distance_matrix) and next_node < len(distance_matrix[prev_node])) else 0

            B = d1 + d2 - d0
            if B < 0:
                B = 0
            # keep the best (largest) removal gain if node appears in multiple routes (defensive)
            if node not in removal_savings or B > removal_savings[node]:
                removal_savings[node] = B

    # Compute minimum insertion cost of each node across all possible edges (a,b)
    min_insertion = {v: float('inf') for v in present_nodes}

    for route in routes:
        if not route:
            continue
        edges = []
        edges.append((0, route[0]))
        for i in range(len(route) - 1):
            edges.append((route[i], route[i+1]))
        edges.append((route[-1], 0))

        for (a, b) in edges:
            # cost to insert v between a and b
            for v in present_nodes:
                dist_av = distance_matrix[a][v] if (a < len(distance_matrix) and v < len(distance_matrix[a])) else 0
                dist_vb = distance_matrix[v][b] if (v < len(distance_matrix) and b < len(distance_matrix[v])) else 0
                dist_ab = distance_matrix[a][b] if (a < len(distance_matrix) and b < len(distance_matrix[a])) else 0
                cost = dist_av + dist_vb - dist_ab
                if cost < min_insertion[v]:
                    min_insertion[v] = cost

    # Build scores for all nodes
    for v in present_nodes:
        ins_cost = min_insertion.get(v, 0.0)
        rem_cost = removal_savings.get(v, 0.0)
        score = ins_cost / (1.0 + rem_cost)
        # small random perturbation
        score += rng.random() * 0.01 * (ins_cost + rem_cost + 1e-9)
        scores.append((v, score))

    total_non_dep = len(present_nodes)
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.18 + rng.random() * 0.12  # between 0.18 and 0.30
        k = int(round(total_non_dep * frac))
        if k < 1:
            k = 1
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

