    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    max_demand = max(demands) if demands else 0
    max_cap = cap

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        number_of_nodes_in_route = sum(1 for n in route if n is not None and n != 0)

        # compute route load (sum of demands for non-depot nodes in this route)
        route_load = 0
        for node in route:
            if node is None or node == 0:
                continue
            if 0 <= node < len(demands):
                route_load += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Centrality-like score: proximity to other nodes in the same route
            if m > 1:
                sum_dist = 0.0
                count = 0
                for other in route:
                    if other is None or other == 0 or other == node:
                        continue
                    d = distance_matrix[node][other] if (node < len(distance_matrix) and other < len(distance_matrix[node])) else 0
                    sum_dist += d
                    count += 1
                avg_dist = sum_dist / count if count > 0 else 0.0
                closeness = 1.0 / (1.0 + avg_dist)
            else:
                closeness = 0.0

            # Demand factor
            dem = demands[node] if node < len(demands) else 0
            if max_demand > 0:
                demand_factor = 1.0 + 0.6 * (dem / max_demand)
            else:
                demand_factor = 1.0

            # Load factor: how loaded the route is relative to max capacity
            if max_cap > 0:
                load_factor = 0.4 + 0.6 * (route_load / max_cap)
            else:
                load_factor = 1.0

            score = closeness * demand_factor * load_factor

            # small random perturbation to diversify
            jitter = (rng.random() - 0.5) * 0.1  # +/-0.05
            score += jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.4  # fraction in [0.15, 0.55]
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

