def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])
    _ = vehicle_capacities  # not used directly in this variant

    scores = []
    total_nodes = 0

    max_demand = max(demands) if demands else 0

    for route in current_solution:
        if not route:
            continue
        # filter actual nodes in the route (ignore depot 0 and None)
        route_nodes = [node for node in route if node is not None and node != 0]
        if len(route_nodes) == 0:
            continue

        m = len(route_nodes)
        # Compute MST weight for the full route (subset = route_nodes)
        if m <= 1:
            mst_with = 0.0
        else:
            total = 0.0
            visited = [False] * m
            visited[0] = True
            dist = [0.0] * m
            for j in range(1, m):
                dist[j] = distance_matrix[route_nodes[0]][route_nodes[j]]
            for _ in range(m - 1):
                min_d = float('inf')
                min_idx = -1
                for j in range(1, m):
                    if not visited[j] and dist[j] < min_d:
                        min_d = dist[j]
                        min_idx = j
                if min_idx == -1:
                    break
                visited[min_idx] = True
                total += min_d
                for j in range(1, m):
                    if not visited[j]:
                        w = distance_matrix[route_nodes[min_idx]][route_nodes[j]]
                        if w < dist[j]:
                            dist[j] = w
            mst_with = total

        # For each node in the route, compute MST without that node
        for i, node in enumerate(route_nodes):
            subset = route_nodes[:i] + route_nodes[i+1:]
            m2 = len(subset)
            if m2 <= 1:
                mst_without = 0.0
            else:
                total2 = 0.0
                visited2 = [False] * m2
                visited2[0] = True
                dist2 = [0.0] * m2
                for j in range(1, m2):
                    dist2[j] = distance_matrix[subset[0]][subset[j]]
                for _ in range(m2 - 1):
                    min_d2 = float('inf')
                    min_idx2 = -1
                    for j in range(1, m2):
                        if not visited2[j] and dist2[j] < min_d2:
                            min_d2 = dist2[j]
                            min_idx2 = j
                    if min_idx2 == -1:
                        break
                    visited2[min_idx2] = True
                    total2 += min_d2
                    for j in range(1, m2):
                        if not visited2[j]:
                            w = distance_matrix[subset[min_idx2]][subset[j]]
                            if w < dist2[j]:
                                dist2[j] = w
                mst_without = total2

            savings = mst_with - mst_without  # non-negative

            demand = demands[node] if node < len(demands) else 0
            demand_norm = demand / max_demand if max_demand > 0 else 0.0

            jitter = rng.random() * 0.4 - 0.2  # in [-0.2, 0.2)

            score = savings * 0.9 + demand_norm * 0.6 + jitter
            scores.append((node, score))
            total_nodes += 1

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # compute max demand for scaling
    max_demand = 0
    for d in demands:
        if d > max_demand:
            max_demand = d

    scores = []
    total_nodes = 0

    # Precompute route length statistics for imbalance factor
    route_lengths = []
    for route in current_solution:
        if not route:
            continue
        m = len(route)
        if m > 0:
            route_lengths.append(m)
    if route_lengths:
        avg_len = sum(route_lengths) / len(route_lengths)
        max_len = max(route_lengths)
        if max_len == 0:
            max_len = 1
    else:
        avg_len = 0.0
        max_len = 1

    for route in current_solution:
        if not route:
            continue
        m = len(route)
        if m == 0:
            continue
        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Compute local removal impact (savings) with a modified scheme
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]

            # Demand-based scaling
            demand = demands[node] if node < len(demands) else 0
            if max_demand > 0:
                demand_factor = 1.0 + 0.4 * (demand / max_demand)
            else:
                demand_factor = 1.0

            # Route-length imbalance factor
            if avg_len > 0:
                route_imbalance = 1.0 - abs(m - avg_len) / max(1.0, max_len)
                if route_imbalance < 0:
                    route_imbalance = 0.0
            else:
                route_imbalance = 0.0

            # Small random perturbation to diversify
            jitter = rng.random() * 0.01

            score = savings * demand_factor + 0.25 * route_imbalance + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
