    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])

    max_demand = max(demands) if demands else 0
    total_capacity = sum(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    # Count total non-depot nodes
    for route in current_solution:
        if not route:
            continue
        for node in route:
            if node is None or node == 0:
                continue
            if 0 <= node < len(demands):
                total_nodes += 1

    # Compute scores for each non-depot node
    for route in current_solution:
        if not route:
            continue
        m = len(route)
        # compute route load (sum of demands for non-depot nodes)
        route_load = 0
        for node in route:
            if node is None or node == 0:
                continue
            if 0 <= node < len(demands):
                route_load += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue

            # Local disruption savings (relink neighbors if removed)
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            disruption = savings if savings > 0 else 0.0

            # Global factor by route utilization
            if total_capacity > 0:
                global_factor = 1.0 + 0.3 * (route_load / total_capacity)
            else:
                global_factor = 1.0

            # Demand factor
            if max_demand > 0:
                node_demand = demands[node] if node < len(demands) else 0
                demand_factor = 1.0 + 0.5 * (node_demand / max_demand)
            else:
                demand_factor = 1.0

            # Small random perturbation for diversification
            rand_factor = 0.95 + 0.1 * rng.random()

            if disruption <= 0:
                score = 0.0
            else:
                score = (disruption ** 1.25) * global_factor * demand_factor * rand_factor

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, int(total_nodes * 0.3))
        k = int(rng.integers(1, max_k + 1))

    return scores, k

