                continue
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            demand = demands[node] if node < len(demands) else 0

            # Centrality-based factor: nodes near the middle of the route are considered more disruptive
            if m > 1:
                center = (m - 1) / 2.0
                norm = abs(idx - center) / max(1.0, center)
                centrality = max(0.0, 1.0 - norm)
            else:
                centrality = 1.0

            # Slack after removing nodes from this route
            slack = cap - route_demand
            if slack < 0:
                slack = 0

            jitter = rng.random() * 0.3 - 0.15

            score = demand * (0.9 * centrality + 0.1) + (slack / (slack + 1.0)) * 0.5 + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))

