def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])

    max_demand = max(demands) if demands else 0
    max_cap = max(vehicle_caps) if vehicle_caps else 0

    # compute max distance for normalization
    max_distance = 0
    n = len(distance_matrix)
    for i in range(n):
        row = distance_matrix[i]
        for j in range(len(row)):
            d = row[j]
            if d > max_distance:
                max_distance = d

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # compute route load (sum of demands for non-depot nodes)
        route_load = 0
        for node in route:
            if node is None or node == 0:
                continue
            if 0 <= node < len(demands):
                route_load += demands[node]
            total_nodes += 1  # count only actual customers

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue

            # Local removal savings (reconnect prev and next)
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            # Position-based factor: emphasize endpoints more (diversity)
            if m > 1:
                middle = (m - 1) / 2.0
                dist_from_middle = abs(idx - middle)
                if middle > 0:
                    centrality_factor = 0.3 + 0.7 * (1.0 - dist_from_middle / middle)
                else:
                    centrality_factor = 0.3
            else:
                centrality_factor = 0.5

            # Demand factor: scale with node demand relative to max demand
            if max_demand > 0:
                node_demand = demands[node] if node < len(demands) else 0
                demand_factor = 1.0 + 0.5 * (node_demand / max_demand)
            else:
                demand_factor = 1.0

            # Load factor: scale with how loaded the route is relative to max capacity
            if max_cap > 0:
                load_factor = 0.6 + 0.4 * (route_load / max_cap)
            else:
                load_factor = 1.0

            # Reinsertion-distance penalty (normalize by max distance)
            if max_distance > 0:
                if m > 1:
                    endpoint_distance = min(distance_matrix[node][route[0]], distance_matrix[node][route[-1]])
                else:
                    endpoint_distance = distance_matrix[node][route[0]]
                denom = 1.0 + (endpoint_distance / max_distance)
            else:
                denom = 1.0

            if savings <= 0:
                score = 0.0
            else:
                score = (savings ** 1.25) * centrality_factor * demand_factor * load_factor / denom

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, int(total_nodes * 0.25))
        k = int(rng.integers(1, max_k + 1))

    return scores, k

