def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    # Collect all non-depot nodes across the entire solution
    all_non_dep = []
    for route in current_solution:
        for n in route:
            if n != 0:
                all_non_dep.append(n)
    total_non_dep = len(all_non_dep)

    if total_non_dep == 0:
        k = 0
        return scores, k

    # Compute scores per non-depot node
    for route in current_solution:
        non_dep_in_route = [n for n in route if n != 0]
        if not non_dep_in_route:
            continue
        route_len_minus1 = len(non_dep_in_route) - 1
        factor = 1.0 + 0.15 * route_len_minus1  # parameterized route-length factor

        for i in non_dep_in_route:
            sum_dist = 0.0
            for j in all_non_dep:
                if j == i:
                    continue
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0.0
                sum_dist += d
            if total_non_dep > 1:
                avg_dist = sum_dist / (total_non_dep - 1)
            else:
                avg_dist = 0.0

            demand = demands[i] if i < len(demands) else 0
            denom = 1.0 + (demand ** 0.5)  # inverse-sqrt demand scaling
            score = (avg_dist * factor) / denom

            perturb = rng.random() * 0.03 * (avg_dist + 1.0)
            score += perturb

            scores.append((i, score))

    # Determine k
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.22  # between 0.08 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

