            removal_potential = disruption if disruption > 0 else 0.0

            # Global factor (less aggressive than the original)
            if total_capacity > 0:
                global_factor = 1.0 + 0.2 * (route_load / total_capacity)
            else:
                global_factor = 1.0

            # Demand factor (more influence for higher-demand nodes)
            if max_demand > 0 and 0 <= node < len(demands):
                node_demand = demands[node]
                demand_factor = 1.0 + 0.6 * (node_demand / max_demand)
            else:
                demand_factor = 1.0

            # Proximity to depot factor (closer to depot slightly increases score)
            dep_dist = distance_matrix[node][0] if len(distance_matrix) > 0 and 0 < len(distance_matrix[0]) else 0
            dep_factor = 1.0 + (dep_dist / max_distance) * 0.25 if max_distance > 0 else 1.0

            # Small random perturbation for diversification
            rand_factor = 0.9 + 0.2 * rng.random()

            if removal_potential <= 0:
                score = 0.0
            else:
                score = (removal_potential ** 0.95) * global_factor * dep_factor * demand_factor * rand_factor

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, int(total_nodes * 0.25))
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        route_nodes = [n for n in route if n is not None and n != 0]
        m = len(route_nodes)
        if m == 0:
            continue

        route_demand = 0
        for node in route_nodes:
            if node < len(demands):
                route_demand += demands[node]

        center_node = None
        if len(route_nodes) >= 2:
            best_sum = None
            for cand in route_nodes:
                s = 0
                for other in route_nodes:
                    if other == cand:
                        continue
                    s += distance_matrix[cand][other]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    center_node = cand
        elif len(route_nodes) == 1:
            center_node = route_nodes[0]

        for idx, node in enumerate(route_nodes):
            total_nodes += 1

            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route_nodes[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route_nodes[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route_nodes[idx - 1]
                next_node = route_nodes[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            slack = cap - route_demand
            if slack < 0:
                slack = 0
            exponent = -0.95 * (slack - (cap * 0.6 if cap else 0.0))
            factor = 1.0 / (1.0 + (2.718281828 ** exponent))

            demand = demands[node] if node < len(demands) else 0
            demand_bonus = (demand ** 0.95) * factor * 0.72

            jitter = rng.random() * 0.6 - 0.3

            center_dist = distance_matrix[node][center_node] if center_node is not None else 0.0
            centrality_bonus = (center_dist ** 0.88) * 0.58

            score = (savings ** 1.15) * 0.85 + demand_bonus + centrality_bonus + jitter
            scores.append((node, score))

    max_k = max(1, total_nodes // 5) if total_nodes > 0 else 0
    if total_nodes == 0:
        k = 0
    else:
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Build mapping: node -> route length (number of non-depot nodes in its route)
    node_route_len = {}
    non_dep_nodes = []
    for route in current_solution:
        if not route:
            continue
        route_nodes = [n for n in route if n is not None and n != 0]
        L = len(route_nodes)
        if L == 0:
            continue
        for n in route_nodes:
            node_route_len[n] = L
            non_dep_nodes.append(n)

    scores = []
    for i in non_dep_nodes:
        sum_dist = 0.0
        for j in non_dep_nodes:
            if j == i:
                continue
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                sum_dist += distance_matrix[i][j]
            else:
                sum_dist += 0.0  # safe default if indices out of bounds

        route_len = node_route_len.get(i, 1)
        demand = demands[i] if i < len(demands) else 0
        factor = 1.0 + 0.2 * (route_len - 1)
        denom = 1.0 + demand
        score = (sum_dist * factor) / denom

        jitter = (rng.random() - 0.5) * 0.5  # [-0.25, 0.25)
        score += jitter

        scores.append((i, score))

    total = len(non_dep_nodes)
    if total == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = max(1, int(round(total * frac)))
        if k > total:
            k = total

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    max_demand = max(demands) if demands else 0

    N = len(distance_matrix)
    scores = []
    total_nodes = 0

    for route in current_solution:
        # non-depot nodes in this route
        non_dep_nodes = [node for node in route if node is not None and node != 0]
        m = len(non_dep_nodes)
        if m == 0:
            continue

        route_node_set = set(non_dep_nodes)

        for node in non_dep_nodes:
            total_nodes += 1

            # Intra-route dispersion: average distance to other nodes in the same route
            if m <= 1:
                intra_disp = 0.0
            else:
                sum_d = 0.0
                for other in non_dep_nodes:
                    if other == node:
                        continue
                    sum_d += distance_matrix[node][other]
                intra_disp = sum_d / (m - 1)

            # Cross-route proximity: minimum distance to any node not in this route
            cross_min = None
            for other in range(N):
                if other == node:
                    continue
                if other in route_node_set:
                    continue
                d = distance_matrix[node][other]
                if cross_min is None or d < cross_min:
                    cross_min = d
            if cross_min is None:
                cross_min = 0.0

            # Demand normalization
            d_node = demands[node] if node < len(demands) else 0
            demand_norm = d_node / max_demand if max_demand > 0 else 0.0

            # Score combination with fixed coefficients and jitter
            score = 0.8 * intra_disp + 0.7 * cross_min - 0.25 * demand_norm
            jitter = (rng.random() - 0.5) * 0.04
            score += jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.18  # between 0.12 and 0.30
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    # Collect unique non-depot nodes present in the current solution
    unique_nodes_set = set()
    for route in current_solution:
        for node in route:
            if node is None:
                continue
            if node == 0:
                continue
            unique_nodes_set.add(node)
    unique_nodes = sorted(unique_nodes_set)
    N = len(unique_nodes)
    if N == 0:
        return [], 0

    index_map = {node: idx for idx, node in enumerate(unique_nodes)}

    # Build adjacency (edge) matrix for consecutive pairs in routes
    INF = float('inf')
    adj = [[INF] * N for _ in range(N)]
    for i in range(N):
        adj[i][i] = 0.0
    for route in current_solution:
        if not route:
            continue
        prev = None
        for node in route:
            if node is None or node == 0:
                continue
            if prev is not None:
                if prev in index_map and node in index_map:
                    u = index_map[prev]
                    v = index_map[node]
                    w = distance_matrix[prev][node]
                    if w < adj[u][v]:
                        adj[u][v] = w
                        adj[v][u] = w
            prev = node

    # Centrality counts (betweenness-like)
    centrality = {node: 0 for node in unique_nodes}

    # Dijkstra-like BFS (O(N^2)) from each source
    for s_idx in range(N):
        # Dijkstra from source s_idx
        dist = [INF] * N
        pred = [-1] * N
        visited = [False] * N
        dist[s_idx] = 0.0

        for _ in range(N):
            # select unvisited node with smallest dist
            u = -1
            best = INF
            for i in range(N):
                if not visited[i] and dist[i] < best:
                    best = dist[i]
                    u = i
            if u == -1:
                break
            visited[u] = True
            for v in range(N):
                if visited[v]:
                    continue
                w = adj[u][v]
                if w == INF:
                    continue
                nd = dist[u] + w
                if nd < dist[v] - 1e-12:
                    dist[v] = nd
                    pred[v] = u

        # Reconstruct paths from s to every t and count internal nodes
        for t_idx in range(N):
            if t_idx == s_idx:
                continue
            if dist[t_idx] == INF:
                continue
            # Reconstruct path from t_idx back to s_idx using pred
            path_indices = []
            idx = t_idx
            for _ in range(N):
                path_indices.append(idx)
                if idx == s_idx:
                    break
                idx = pred[idx]
            if not path_indices or path_indices[-1] != s_idx:
                continue  # not connected properly
            internal_indices = path_indices[1:]  # exclude the endpoint t
            for idx_in_path in internal_indices:
                node_id = unique_nodes[idx_in_path]
                centrality[node_id] += 1

    # Build scores with a small random jitter
    scores = []
    for node in unique_nodes:
        base = centrality.get(node, 0)
        jitter = rng.random() * 0.5  # in [0, 0.5)
        score = base + jitter
        scores.append((node, score))

    total_nodes = len(unique_nodes)
    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    node_to_route = {}
    route_lengths = {}
    all_nodes = []

    for r_idx, route in enumerate(current_solution):
        if not route:
            continue
        non_dep_indices = [i for i, n in enumerate(route) if n is not None and n != 0]
        L = len(non_dep_indices)
        route_lengths[r_idx] = L

        for pos_in_route, idx_in_route in enumerate(non_dep_indices):
            node = route[idx_in_route]
            node_to_route[node] = (r_idx, pos_in_route)
            all_nodes.append(node)

    N = len(all_nodes)
    scores = []

    if N == 0:
        return scores, 0

    for node in all_nodes:
        s = 0.0
        for other in all_nodes:
            if other == node:
                continue
            s += distance_matrix[node][other]
        mean_all = s / (N - 1) if N > 1 else 0.0

        r_idx, pos_in_route = node_to_route[node]
        L = route_lengths.get(r_idx, 0)

        if L <= 1:
            pos_factor = 0.6
        elif pos_in_route == 0 or pos_in_route == L - 1:
            pos_factor = 0.8
        else:
            pos_factor = 1.5

        d = demands[node] if node < len(demands) else 0
        score = mean_all * pos_factor / (1.0 + 0.5 * d)

        jitter = (rng.random() - 0.5) * 0.2 * (1.0 + mean_all)
        score += jitter

        scores.append((node, score))

    frac = 0.07 + rng.random() * 0.14  # between 0.07 and 0.21
    k = max(1, int(round(N * frac)))
    if k > N:
        k = N

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    max_demand = max(demands) if demands else 0

    scores = []
    total_nodes = 0

    # Collect all non-depot nodes present in the solution
    nodes_set = set()
    for route in current_solution:
        for node in route:
            if node is not None and node != 0:
                nodes_set.add(node)

    nodes_list = sorted(nodes_set)
    L = len(nodes_list)

    if L == 0:
        return scores, 0

    # Betweenness-like centrality via random pair sampling
    centrality = {node: 0 for node in nodes_list}

    # Count how many routes contain each node (for route popularity)
    route_count = {}
    total_routes = len(current_solution)
    for route in current_solution:
        for node in route:
            if node is None or node == 0:
                continue
            route_count[node] = route_count.get(node, 0) + 1

    # Number of samples (limited to keep runtime reasonable)
    sample_count = min(200, max(1, L * 2))

    EPS = 1e-9
    if L > 1 and sample_count > 0:
        for _ in range(sample_count):
            s_idx = int(rng.integers(0, L))
            t_idx = int(rng.integers(0, L - 1))
            if t_idx >= s_idx:
                t_idx += 1
            s = nodes_list[s_idx]
            t = nodes_list[t_idx]

            path_len = distance_matrix[s][t]
            # For each candidate node u, check if it lies on a shortest path between s and t
            for u in nodes_list:
                if u == s or u == t:
                    continue
                d_s_u = distance_matrix[s][u]
                d_u_t = distance_matrix[u][t]
                if abs((d_s_u + d_u_t) - path_len) <= EPS:
                    centrality[u] += 1

    # Build scores for each node
    for node in nodes_list:
        c_norm = (centrality[node] / sample_count) if sample_count > 0 else 0.0
        demand_norm = (demands[node] / max_demand) if (max_demand > 0 and node < len(demands)) else 0.0
        pop = route_count.get(node, 0) / max(1, total_routes)

        score = (2.0 * c_norm) + (0.8 * demand_norm) + (0.5 * pop)
        jitter = (rng.random() - 0.5) * 0.1  # [-0.05, 0.05)
        score += jitter

        scores.append((node, score))

    total_nodes = len(nodes_list)
    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    max_demand = max(demands) if demands else 0

    scores = []
    total_nodes = 0

    # Map each node to its route and route properties
    route_of = {}
    route_lengths = {}
    all_nodes = set()

    for ri, route in enumerate(current_solution):
        if not route:
            continue
        m = len(route)
        route_lengths[ri] = m
        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            route_of[node] = (ri, m, idx)
            all_nodes.add(node)

    # Compute scores for each non-depot node
    for node in sorted(all_nodes):
        ri, m, idx = route_of[node]
        route = current_solution[ri]

        # Intra-route mean distance to other non-depot nodes in the same route
        intra_nodes = [n for n in route if (n is not None and n != 0 and n != node)]
        if intra_nodes:
            s_intra = 0.0
            for j in intra_nodes:
                s_intra += distance_matrix[node][j]
            intra_mean = s_intra / len(intra_nodes)
        else:
            intra_mean = 0.0

        # Inter-route mean distance to all nodes not in this route
        inter_nodes = []
        for rj, other_route in enumerate(current_solution):
            if rj == ri:
                continue
            for other_node in other_route:
                if other_node is None or other_node == 0:
                    continue
                inter_nodes.append(other_node)
        if inter_nodes:
            s_inter = 0.0
            for o in inter_nodes:
                s_inter += distance_matrix[node][o]
            inter_mean = s_inter / len(inter_nodes)
        else:
            inter_mean = 0.0

        route_len_factor = 1.0 + 0.25 * (m - 1)

        d = demands[node] if node < len(demands) else 0
        demand_norm = d / max_demand if max_demand > 0 else 0.0

        score = ((inter_mean + 1e-9) / (1.0 + intra_mean)) * route_len_factor - 0.4 * demand_norm
        score += (rng.random() - 0.5) * 0.1  # small jitter for diversification

        scores.append((node, score))
        total_nodes += 1

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 5)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    N = len(distance_matrix)

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Local savings if removing this node from its route
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]

            # Best insertion cost of this node into any route/gap across all routes
            best_cost = float('inf')
            for r2 in current_solution:
                if not r2:
                    continue
                L = len(r2)
                if L > 0:
                    # insertion before first
                    first = r2[0]
                    if first is not None:
                        cost_front = distance_matrix[0][node] + distance_matrix[node][first] - distance_matrix[0][first]
                        if cost_front < best_cost:
                            best_cost = cost_front
                    # insert between consecutive nodes
                    for t in range(L - 1):
                        a = r2[t]
                        b = r2[t + 1]
                        if a is None or b is None:
                            continue
                        cost = distance_matrix[a][node] + distance_matrix[node][b] - distance_matrix[a][b]
                        if cost < best_cost:
                            best_cost = cost
                    # insertion at the end
                    last = r2[-1]
                    if last is not None:
                        cost_end = distance_matrix[last][node] + distance_matrix[node][0] - distance_matrix[last][0]
                        if cost_end < best_cost:
                            best_cost = cost_end

            if best_cost == float('inf'):
                best_cost = 0.0

            jitter = rng.random() * 0.2 - 0.1  # [-0.1, 0.1)
            score = savings - best_cost + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        k = int(round(total_nodes * (rng.random() ** 0.6)))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    total_nodes = 0

    scores_map = {}

    for route in current_solution:
        if not route:
            continue
        non_dep = [n for n in route if n is not None and n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_nodes += L
        P = 3  # number of random bipartitions

        for _ in range(P):
            clusters = {0: [], 1: []}
            for node in non_dep:
                cluster = 0 if rng.random() < 0.5 else 1
                clusters[cluster].append(node)

            for c in (0, 1):
                cluster_nodes = clusters[c]
                m = len(cluster_nodes)
                if m <= 1:
                    for node in cluster_nodes:
                        scores_map[node] = scores_map.get(node, 0.0)
                    continue

                for node in cluster_nodes:
                    s = 0.0
                    for other in cluster_nodes:
                        if other == node:
                            continue
                        s += distance_matrix[node][other]
                    mean_dist = s / (m - 1)
                    contrib = 1.0 / (mean_dist + 1.0)
                    scores_map[node] = scores_map.get(node, 0.0) + contrib

    # Optional demand-based boost
    max_demand = max(demands) if demands else 0
    if max_demand > 0 and scores_map:
        for node in list(scores_map.keys()):
            demand = demands[node] if node < len(demands) else 0
            scores_map[node] += 0.25 * (demand / max_demand)

    scores = [(node, score) for node, score in scores_map.items()]

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.2  # between 0.15 and 0.35
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    all_non_dep = []
    node_route_len = {}
    total_nodes = 0

    # Gather all non-depot nodes and their route lengths
    for route in current_solution:
        non_dep = [n for n in route if n is not None and n != 0]
        L = len(non_dep)
        if L == 0:
            continue
        for n in non_dep:
            total_nodes += 1
            node_route_len[n] = L
            all_non_dep.append(n)

    # Compute centrality-like score for each node
    for i in all_non_dep:
        centrality = 0.0
        for j in all_non_dep:
            if j == i:
                continue
            dist = 0.0
            if i < len(distance_matrix) and j < len(distance_matrix[i]):
                dist = distance_matrix[i][j]
            if dist <= 0.0:
                dist = 1e-6
            centrality += 1.0 / dist

        L = node_route_len.get(i, 1)
        route_factor = 1.0 + 0.3 * (L - 1)
        d = demands[i] if i < len(demands) else 0
        score = centrality * route_factor + d * 0.7

        score += rng.random() * 0.01 * (centrality + 1.0)
        scores.append((i, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.18 + rng.random() * 0.18  # between 0.18 and 0.36
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    # capacity not directly used in this approach, kept for compatibility

    # Identify cross-route hubs: first non-depot node in each non-empty route
    hubs = []
    for route in current_solution:
        hub = None
        for n in route:
            if n is not None and n != 0:
                hub = n
                break
        if hub is not None:
            hubs.append(hub)

    # Compute route-wise demands and count non-empty routes
    route_demands = []
    nonempty_route_flags = []
    for route in current_solution:
        rd = 0
        has_node = False
        for n in route:
            if n is None or n == 0:
                continue
            has_node = True
            if n < len(demands):
                rd += demands[n]
        route_demands.append(rd)
        nonempty_route_flags.append(has_node)

    # Mean route demand over non-empty routes
    total_rd = 0
    count = 0
    for i, flag in enumerate(nonempty_route_flags):
        if flag:
            total_rd += route_demands[i]
            count += 1
    mean_route_demand = (total_rd / count) if count > 0 else 0.0

    scores = []
    total_nodes = 0

    for ri, route in enumerate(current_solution):
        for node in route:
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Distance to nearest hub
            hub_distance = None
            for hub in hubs:
                d = distance_matrix[node][hub] if (node < len(distance_matrix) and hub < len(distance_matrix[node])) else 0.0
                if (hub_distance is None) or (d < hub_distance):
                    hub_distance = d
            if hub_distance is None:
                hub_distance = 0.0

            # Load variation: how far this route's load deviates from the mean
            rd = route_demands[ri]
            if mean_route_demand > 0:
                load_factor = 1.0 + abs(rd - mean_route_demand) / mean_route_demand
            else:
                load_factor = 1.0

            jitter = rng.random() * 0.12 - 0.06  # [-0.06, 0.06)
            score = (hub_distance * 0.65) + (load_factor * 0.75) + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.18 + rng.random() * 0.26  # between 0.18 and 0.44
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    # Collect all non-depot nodes currently present
    nodes_in_sol = []
    seen = set()
    for route in current_solution:
        if not route:
            continue
        for node in route:
            if node is None or node == 0:
                continue
            if node not in seen:
                seen.add(node)
                nodes_in_sol.append(node)

    n = len(nodes_in_sol)
    scores = []

    if n == 0:
        return scores, 0

    # Build index mapping for compact computation
    idx = {node: i for i, node in enumerate(nodes_in_sol)}

    # Build a lightweight affinity graph: weight(i,j) = 1 / (1 + distance(i,j))
    W = [[0.0] * n for _ in range(n)]
    for i in range(n):
        ni = nodes_in_sol[i]
        for j in range(n):
            if i == j:
                continue
            nj = nodes_in_sol[j]
            d = distance_matrix[ni][nj] if ni < len(distance_matrix) and nj < len(distance_matrix[ni]) else 0.0
            w = 1.0 / (1.0 + d)
            W[i][j] = w

    # Row sums and transition matrix P (normalized affinities)
    row_sum = [sum(W[i]) for i in range(n)]
    P = [[0.0] * n for _ in range(n)]
    for i in range(n):
        s = row_sum[i]
        if s > 0:
            inv = 1.0 / s
            for j in range(n):
                P[i][j] = W[i][j] * inv
        else:
            P[i][i] = 1.0

    # Power iteration to estimate centrality (stationary distribution)
    pi = [1.0 / n] * n
    for _ in range(25):
        pi_next = [0.0] * n
        for b in range(n):
            s_val = 0.0
            for a in range(n):
                s_val += pi[a] * P[a][b]
            pi_next[b] = s_val
        ssum = sum(pi_next)
        if ssum > 0:
            pi_next = [v / ssum for v in pi_next]
        pi = pi_next

    # Assign scores based on centrality (higher centrality -> higher score)
    for i, node in enumerate(nodes_in_sol):
        scores.append((node, pi[i]))

    # Determine k: a small random fraction of involved nodes
    max_k = max(1, n // 4)
    k = int(rng.integers(1, max_k + 1)) if n > 0 else 0

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    all_nodes = []
    route_of_node = {}

    # Gather all non-depot nodes and their route indices
    for ri, route in enumerate(current_solution):
        if not route:
            continue
        for node in route:
            if node is None or node == 0:
                continue
            if node not in route_of_node:
                route_of_node[node] = ri
                all_nodes.append(node)

    total_non_dep = len(all_nodes)

    # Choose a small set of anchor nodes (non-depot)
    if total_non_dep > 0:
        A = min(5, total_non_dep)
        anchors = rng.choice(all_nodes, size=A, replace=False).tolist()
    else:
        anchors = []

    # Compute scores for each non-depot node
    for node in all_nodes:
        ri = route_of_node[node]
        route = current_solution[ri]

        # Distance to nearest anchor
        if anchors:
            min_dist = min(distance_matrix[node][a] for a in anchors)
        else:
            min_dist = 0.0

        # Route demand
        route_demand = 0
        for n in route:
            if n is None or n == 0:
                continue
            if n < len(demands):
                route_demand += demands[n]
        slack = cap - route_demand
        if slack < 0:
            slack = 0

        # Node demand
        dem = demands[node] if node < len(demands) else 0
        jitter = rng.random() * 0.2

        # Weights and score
        w1 = 1.2  # weight for anchor diversity (distance to anchors)
        w2 = 0.8  # weight for node demand
        w3 = 0.5  # weight for congestion term
        score = w1 * min_dist + w2 * dem + w3 * (1.0 / (slack + 1.0)) + jitter

        scores.append((node, score))

    # Determine k
    if total_non_dep == 0:
        k = 0
    else:
        max_k = max(1, total_non_dep // 4)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # Compute total demand on this route
        route_demand = 0
        for node in route:
            if node is None or node == 0:
                continue
            if isinstance(node, int) and node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Edge contribution around the node
            if m == 1:
                edge_sum = 0.0
            elif idx == 0:
                next_node = route[1]
                edge_sum = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                edge_sum = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                edge_sum = distance_matrix[prev_node][node] + distance_matrix[node][next_node]

            demand = demands[node] if node < len(demands) else 0

            load_factor = route_demand / cap if cap else 0
            influence = demand * (0.8 + 0.3 * load_factor)

            # Position factor
            if m <= 2:
                position = 0.5
            else:
                if idx == 0 or idx == m - 1:
                    position = 0.3
                else:
                    position = 1.0

            center = 1.0 if 0 < idx < m - 1 else 0.5

            distance_weight = edge_sum

            jitter = rng.random() * 0.25 - 0.125  # [-0.125, 0.125)

            score = (influence * 0.6) + (distance_weight * 0.25) + (center * 0.15) + (position * 0.1) + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        p = 0.25 + rng.random() * 0.25  # portion to remove
        k = int(max(1, round(total_nodes * p)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        route_demand = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]

            demand = demands[node] if node < len(demands) else 0

            # New factors for a modified scoring
            route_util = route_demand / cap if cap > 0 else 0.0
            slack = cap - route_demand
            if slack < 0:
                slack = 0

            jitter = rng.random() * 0.3 - 0.15
            density_factor = 0.25 * demand * (1.0 + route_util)
            score = savings * 0.7 + density_factor - slack * 0.05 + jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 2)
        k = int(rng.random() * max_k) + 1

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Route-size factor grows with sqrt(L)
        route_size_factor = 1.0 + 0.25 * (L ** 0.5)

        for node in non_dep:
            if L > 1:
                # Mean distance to all other non-depot nodes in this route
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)

                # Nearest neighbor distance within the route
                min_dist = None
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if (min_dist is None) or (d < min_dist):
                        min_dist = d
            else:
                mean_distance = 0.0
                min_dist = 0.0

            demand = demands[node] if node < len(demands) else 0
            score = (mean_distance * route_size_factor) / (1.0 + demand)

            if min_dist is not None:
                score += 0.1 * min_dist

            perturb = rng.random() * 0.03 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.15  # between 0.10 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # Compute total demand on this route
        route_demand = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Removal gain (local savings-like term)
            if m == 1:
                removal_saving = 0.0
            elif idx == 0:
                next_node = route[1]
                removal_saving = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                removal_saving = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                removal_saving = (distance_matrix[prev_node][node] +
                                  distance_matrix[node][next_node] -
                                  distance_matrix[prev_node][next_node])

            demand = demands[node] if node < len(demands) else 0
            slack = cap - route_demand
            if slack < 0:
                slack = 0

            # Route centrality: sum of distances from this node to other nodes in the same route
            centrality = 0.0
            for other in route:
                if other is None or other == 0 or other == node:
                    continue
                centrality += distance_matrix[node][other]
            centrality_norm = centrality / (m - 1) if m > 1 else 0.0

            # Score components
            if removal_saving > 0:
                gain = 0.6 * removal_saving
            else:
                gain = 0.2 * removal_saving

            demand_factor = 0.25 * (demand / (slack + 1))

            jitter = rng.random() * 0.2 - 0.1  # [-0.1, 0.1)
            score = gain + demand_factor + 0.3 * centrality_norm + jitter

            scores.append((node, score))

    if total_nodes > 0:
        max_k = max(1, total_nodes // 5)
        k = int(rng.integers(1, max_k + 1))
    else:
        k = 0

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # determine maximum route length for normalization
    max_route_len = max((len(r) for r in current_solution), default=1)

    scores = []
    non_dep_total = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue
        non_dep_total += len(non_dep)

        # compute route diameter (max distance between any two non-depot nodes in the route)
        if len(non_dep) > 1:
            diameter = 0.0
            for a in non_dep:
                for b in non_dep:
                    if a == b:
                        continue
                    d = distance_matrix[a][b] if (a < len(distance_matrix) and b < len(distance_matrix[a])) else 0
                    if d > diameter:
                        diameter = d
            if diameter <= 0.0:
                diameter = 1.0
        else:
            diameter = 1.0

        for i in non_dep:
            # sum distances from i to all other non-depot nodes in the same route
            sum_dist = 0.0
            for j in non_dep:
                if j == i:
                    continue
                d = distance_matrix[i][j] if (i < len(distance_matrix) and j < len(distance_matrix[i])) else 0
                sum_dist += d
            avg_dist = sum_dist / (len(non_dep) - 1) if len(non_dep) > 1 else 0.0

            # normalized centrality within route
            normalized_centrality = (avg_dist / diameter) if diameter > 0.0 else 0.0

            demand = demands[i] if i < len(demands) else 0
            route_len_penalty = 1.0 + 0.8 * (len(route) - 1) / max_route_len
            score = normalized_centrality * route_len_penalty / (1.0 + demand)
            score += rng.random() * 0.03 * (normalized_centrality + 1.0)

            scores.append((i, score))

    if non_dep_total == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.28  # between 0.08 and 0.36
        k = max(1, int(round(non_dep_total * frac)))
        if k > non_dep_total:
            k = non_dep_total

    return scores, k

