def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_nodes = 0

    total_routes = len(current_solution)

    # Precompute which routes contain at least one non-depot node for diversity computation
    nonempty_route_flags = []
    for route in current_solution:
        has_node = False
        for n in route:
            if n is not None and n != 0:
                has_node = True
                break
        nonempty_route_flags.append(has_node)

    # Compute per-route loads (sum of demands for non-depot nodes)
    route_loads = []
    for route in current_solution:
        load = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                load += demands[node]
        route_loads.append(load)

    # Derive diversity metrics (based on loads across nonempty routes)
    nonempty_indices = [i for i, flag in enumerate(nonempty_route_flags) if flag]
    loads_nonempty = [route_loads[i] for i in nonempty_indices]
    if loads_nonempty:
        max_load = max(loads_nonempty)
        min_load = min(loads_nonempty)
        avg_load = sum(loads_nonempty) / len(loads_nonempty)
        denom = max_load - min_load
    else:
        max_load = min_load = avg_load = 0
        denom = 0

    # Weights tuned to be different from the original algorithm
    w_sav = 1.0
    w_int = 1.2
    w_div = 0.6

    for ri, route in enumerate(current_solution):
        m = len(route)
        if m == 0:
            continue

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Local removal savings (alternative formulation)
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            # Inter-route proximity: distance to nearest node in a different route
            min_dist_to_other = None
            for rj, other_route in enumerate(current_solution):
                if rj == ri:
                    continue
                for other_node in other_route:
                    if other_node is None or other_node == 0:
                        continue
                    d = distance_matrix[node][other_node]
                    if (min_dist_to_other is None) or (d < min_dist_to_other):
                        min_dist_to_other = d

            if min_dist_to_other is None:
                inter_route_factor = 0.0
            else:
                inter_route_factor = 1.0 / (1.0 + min_dist_to_other)

            # Diversity factor based on route load distribution
            if denom <= 0:
                diversity_factor = 0.0
            else:
                route_load = route_loads[ri]
                diversity_factor = (max_load - route_load) / denom
                if diversity_factor < 0:
                    diversity_factor = 0.0
                elif diversity_factor > 1:
                    diversity_factor = 1.0

            score = (w_sav * savings) + (w_int * inter_route_factor) + (w_div * diversity_factor)
            score += rng.random() * 0.02  # small jitter for diversification

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Collect all non-depot nodes present in the solution
    non_dep_nodes = []
    for route in current_solution:
        for node in route:
            if node is None or node == 0:
                continue
            non_dep_nodes.append(node)

    if not non_dep_nodes:
        return [], 0

    # Determine hub: non-depot node with minimal sum of distances to all other non-depot nodes
    hub = non_dep_nodes[0]
    best_sum = None
    for h in set(non_dep_nodes):
        row = distance_matrix[h]
        s = 0.0
        for v in non_dep_nodes:
            if v == h:
                continue
            s += row[v] if v < len(row) else 0.0
        if best_sum is None or s < best_sum:
            best_sum = s
            hub = h

    # Compute scores for all non-depot nodes
    scores = []
    for route in current_solution:
        for node in route:
            if node is None or node == 0:
                continue
            dist_to_hub = distance_matrix[node][hub] if (hub is not None and hub < len(distance_matrix[node])) else 0.0
            dist_to_depot = distance_matrix[node][0] if 0 < len(distance_matrix[node]) else 0.0
            demand = demands[node] if node < len(demands) else 0
            score = dist_to_hub + 0.6 * dist_to_depot + 0.2 * demand
            score += (rng.random() - 0.5) * 0.2  # small jitter
            scores.append((node, score))

    total_nodes = len(scores)
    if total_nodes == 0:
        k = 0
    else:
        frac = 0.2 + rng.random() * 0.25  # between 0.2 and 0.45
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    all_nodes_info = []  # each entry: (node, route_idx, pos_in_route, route_nodes)

    # 1) determine a center node for each route and collect all non-depot nodes
    centers_by_route = {}
    for r_idx, route in enumerate(current_solution):
        route_nodes = [n for n in route if n != 0]
        if not route_nodes:
            centers_by_route[r_idx] = None
            continue

        if len(route_nodes) == 1:
            centers_by_route[r_idx] = route_nodes[0]
        else:
            best = None
            best_sum = None
            for cand in route_nodes:
                s = 0.0
                for other in route_nodes:
                    if other == cand:
                        continue
                    s += distance_matrix[cand][other]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    best = cand
            centers_by_route[r_idx] = best

        for pos, node in enumerate(route_nodes):
            all_nodes_info.append((node, r_idx, pos, route_nodes))

    total_non_dep = len(all_nodes_info)

    # 2) build a small random basis from all non-depot nodes
    basis_nodes = []
    if total_non_dep > 0:
        idxs = list(range(total_non_dep))
        rng.shuffle(idxs)
        B = min(6, total_non_dep)
        basis_nodes = [all_nodes_info[i][0] for i in idxs[:B]]

    # 3) compute scores for all non-depot nodes
    for node, r_idx, pos, route_nodes in all_nodes_info:
        # cross-route diversity term: mean distance to basis nodes
        if basis_nodes:
            cross_sum = 0.0
            for b in basis_nodes:
                d = distance_matrix[node][b] if (node < len(distance_matrix) and b < len(distance_matrix[node])) else 0.0
                cross_sum += d
            cross_similarity = cross_sum / len(basis_nodes)
        else:
            cross_similarity = 0.0

        # route-center distance term
        center_node = centers_by_route.get(r_idx)
        distance_to_center = 0.0
        if center_node is not None:
            if (node < len(distance_matrix)) and (center_node < len(distance_matrix[node])):
                distance_to_center = distance_matrix[node][center_node]

        # max distance from center to any node in this route (for normalization)
        max_dist = 0.0
        if center_node is not None:
            for other in route_nodes:
                if (center_node < len(distance_matrix)) and (other < len(distance_matrix[center_node])):
                    d = distance_matrix[center_node][other]
                    if d > max_dist:
                        max_dist = d
        if max_dist <= 0.0:
            route_influence = 1.0
        else:
            ratio = distance_to_center / max_dist
            route_influence = 1.0 + ratio

        # demand-based penalty (lower demand increases score less aggressively)
        demand = demands[node] if node < len(demands) else 0
        demand_penalty = 1.0 / (1.0 + 0.6 * demand)

        # multiplicative combination with a small jitter
        score = (cross_similarity ** 1.2) * (route_influence ** 0.9) * demand_penalty
        jitter = rng.random() * 0.04 * (cross_similarity + route_influence + 1.0)
        score += jitter

        scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.18  # between 0.07 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0  # though not directly used in this heuristic

    # Collect all non-depot nodes and map each to its route
    all_nodes = []
    node_to_route = {}
    for r_idx, route in enumerate(current_solution):
        if not route:
            continue
        for node in route:
            if node is None or node == 0:
                continue
            all_nodes.append(node)
            node_to_route[node] = r_idx

    scores = []
    total_nodes = len(all_nodes)

    if total_nodes == 0:
        return scores, 0

    # Precompute per-route lengths (ignoring depots)
    route_len = {}
    for r_idx, route in enumerate(current_solution):
        L = 0
        if route:
            for n in route:
                if n is None or n == 0:
                    continue
                L += 1
        route_len[r_idx] = L

    # Precompute cross-route proximity for each node
    for node in all_nodes:
        cross_score = 0.0
        # sum over all other non-depot nodes
        for other in all_nodes:
            if other == node:
                continue
            dist = 0.0
            if node < len(distance_matrix) and other < len(distance_matrix[node]):
                dist = distance_matrix[node][other]
            cross_score += 1.0 / (dist + 1.0)

        # Node-specific attributes
        demand = demands[node] if node < len(demands) else 0
        r_id = node_to_route[node]
        r_len = route_len.get(r_id, 0)
        depot_dist = distance_matrix[node][0] if node < len(distance_matrix) and 0 < len(distance_matrix[node]) else 0
        jitter = rng.random() * 0.4 - 0.2  # [-0.2, 0.2)

        # Weighted combination (tuned to emphasize global proximity and demand, with route-size penalty)
        score = 0.8 * cross_score + 0.4 * demand - 0.25 * r_len - 0.05 * depot_dist + jitter
        scores.append((node, score))

    max_k = max(1, total_nodes // 4)
    k = int(rng.integers(1, max_k + 1)) if total_nodes > 0 else 0

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        non_dep = [n for n in route if n is not None and n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_nodes += L
        factor = 1.0 + 0.5 * (L - 1)

        for node in non_dep:
            sum_sq_dist = 0.0
            for other in non_dep:
                if other == node:
                    continue
                d = 0.0
                if node < len(distance_matrix) and other < len(distance_matrix[node]):
                    d = distance_matrix[node][other]
                sum_sq_dist += d * d

            demand = demands[node] if node < len(demands) else 0
            score = (sum_sq_dist * factor) / (1.0 + demand)

            jitter = (rng.random() - 0.5) * 0.02 * (L + 1)
            score += jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.22  # 0.08 to 0.30
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue

        # consider only actual nodes (ignore depot 0)
        route_nodes = [n for n in route if n is not None and n != 0]
        L = len(route_nodes)
        if L == 0:
            continue

        # total demand on this route
        route_demand = 0
        for node in route_nodes:
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route_nodes):
            total_nodes += 1

            # average distance from this node to others in the same route
            sum_dist = 0.0
            for other in route_nodes:
                if other == node:
                    continue
                sum_dist += distance_matrix[node][other]
            avg_dist = sum_dist / (L - 1) if L > 1 else 0.0
            connectivity = 1.0 / (1.0 + avg_dist)

            demand = demands[node] if node < len(demands) else 0
            demand_factor = 1.0 / (1.0 + demand)

            slack = cap - route_demand
            if slack < 0:
                slack = 0
            slack_ratio = slack / cap if cap > 0 else 0.0

            if cap > 0:
                logistic = 1.0 / (1.0 + (2.718281828 ** (-6.0 * (slack_ratio - 0.5))))
            else:
                logistic = 0.5

            jitter = (rng.random() - 0.5) * 0.12  # [-0.06, 0.06)

            score = connectivity * 0.5 + demand_factor * 0.25 + logistic * 0.2 + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.07 + rng.random() * 0.15  # between 0.07 and 0.22
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

