            continue

        # route total demand
        route_demand = 0
        for node in route_nodes:
            if node < len(demands):
                route_demand += demands[node]
        if route_demand < 0:
            route_demand = 0

        # precompute sum of distances to all other nodes in the route for centrality
        sums_to_others = {}
        for i, node in enumerate(route_nodes):
            s = 0.0
            for j, other in enumerate(route_nodes):
                if i == j:
                    continue
                s += distance_matrix[node][other]
            sums_to_others[node] = s

        max_sum = 0.0
        for v in route_nodes:
            if sums_to_others[v] > max_sum:
                max_sum = sums_to_others[v]

        for idx, node in enumerate(route_nodes):
            total_nodes += 1

            # local removal impact (same as before but kept as a separate component)
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route_nodes[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route_nodes[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route_nodes[idx - 1]
                next_node = route_nodes[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            # centrality-based diversification (new form)
            sum_to_others = sums_to_others[node]
            centrality = 0.0
            if max_sum > 0.0:
                centrality = (max_sum - sum_to_others) / max_sum  # in [0,1], higher for more central nodes

            # demand and slack context
            demand = demands[node] if node < len(demands) else 0
            slack = cap - route_demand
            if slack < 0:
                slack = 0
            jitter = rng.random() * 0.6 - 0.3  # in [-0.3, 0.3)

            # new scoring blend (different weights and components)
            score = (centrality * 1.5) + (demand * 0.7) + (savings * 0.4) + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 5)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

