        route_demand = 0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for i in non_dep:
            # distance to depot
            if i < len(distance_matrix) and 0 < len(distance_matrix[i]):
                d_to_depot = distance_matrix[i][0]
            else:
                d_to_depot = 0.0

            # mean intra-route distance to others in the same route
            sum_to_others = 0.0
            for j in non_dep:
