                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0.0
                sum_to_others += d
            mean_intra = sum_to_others / (L - 1) if L > 1 else 0.0

            base = d_to_depot + mean_intra
            ratio = (route_demand / cap) if cap > 0 else 0.0
            jitter = rng.random() * 0.05 * (base + 1.0)

            score = (base ** 1.2) * (1.0 + 0.7 * ratio) * (1.0 + jitter)
            scores.append((i, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.25  # between 0.12 and 0.37
        k = max(1, int(round(total_non_dep * frac)))
