def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L <= 1:
            continue

        for node in non_dep:
            dists = []
            for other in non_dep:
                if other == node:
                    continue
                if node < len(distance_matrix) and other < len(distance_matrix[node]):
                    d = distance_matrix[node][other]
                else:
                    d = 0
                dists.append(d)

            if dists:
                d_nearest = min(dists)
                d_farthest = max(dists)
                spread = d_farthest - d_nearest
            else:
                spread = 0.0

            demand = demands[node] if node < len(demands) else 0
            score = spread * (1.0 + 0.8 * demand)

            jitter = rng.random() * 0.1 * (spread + 1.0)
            score += jitter

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    # Collect all non-depot nodes once
    all_nodes = []
    seen = set()
    for route in current_solution:
        for node in route:
            if node is None or node == 0:
                continue
            if node not in seen:
                seen.add(node)
                all_nodes.append(node)

    # Build adjacency (undirected) between consecutive non-depot nodes within each route
    neighbor_sets = {node: set() for node in all_nodes}
    for route in current_solution:
        route_nodes = [n for n in route if (n is not None) and (n != 0)]
        for i in range(1, len(route_nodes)):
            a = route_nodes[i - 1]
            b = route_nodes[i]
            neighbor_sets[a].add(b)
            neighbor_sets[b].add(a)

    # Diffusion process to compute influence scores
    diff = {node: 1.0 for node in all_nodes}
    T = 3  # number of diffusion steps
    for _ in range(T):
        new_diff = {}
        for node in all_nodes:
            s = 0.0
            for neigh in neighbor_sets[node]:
                deg_neigh = len(neighbor_sets[neigh])
                if deg_neigh > 0:
                    s += diff[neigh] / deg_neigh
            new_diff[node] = 0.5 * diff[node] + 0.5 * s
        diff = new_diff

    # Compute per-node scores using diffusion influence, route length, and demand
    scores = []
    for node in all_nodes:
        # find route length L for the node
        L = 1
        for route in current_solution:
            if node in route:
                L = len(route)
                break

        demand = demands[node] if node < len(demands) else 0
        factor = 1.0 + 0.25 * (L - 1)
        score = diff[node] * factor / (1.0 + demand)

        jitter = rng.random() * 0.01 * (diff[node] + 1.0)
        score += jitter

        scores.append((node, score))

    # Determine how many nodes to remove
    total_nodes = len(all_nodes)
    if total_nodes == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.18  # between 0.08 and 0.26
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

