            dists = []
            for j in non_dep:
                if i == j:
                    continue
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0
                dists.append(d)
            # compute k nearest distances (k = 3)
            if dists:
                k_nn = 3
                dists_sorted = sorted(dists)
                k_eff = min(k_nn, len(dists_sorted))
                avg_nearest = sum(dists_sorted[:k_eff]) / k_eff if k_eff > 0 else 0.0
            else:
                avg_nearest = 0.0

            # distance to depot
            if i < len(distance_matrix) and 0 < len(distance_matrix[i]):
                d_to_depot = distance_matrix[i][0]
