            score = (0.55 * avg_nearest + 0.45 * d_to_depot) * (1.0 + 0.6 * (route_len - 1)) / (1.0 + demand)

            # Random perturbation
            score += rng.random() * 0.12 * (avg_nearest + 1.0)

            scores.append((i, score))

    if non_dep_total == 0:
        k = 0
    else:
