def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    max_demand = max(demands) if demands else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)
        center_index = (m - 1) / 2.0 if m > 0 else 0.0

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            demand = demands[node] if node < len(demands) else 0

            # Local savings (same as original local_savings calculation)
            if m == 1:
                local_savings = 0.0
            elif idx == 0:
                next_node = route[1]
                local_savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                local_savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                local_savings = (distance_matrix[prev_node][node] +
                                 distance_matrix[node][next_node] -
                                 distance_matrix[prev_node][next_node])

            if local_savings < 0:
                local_savings = 0.0

            # End-centric weighting: higher weight for nodes toward the ends
            if m > 1:
                max_dist_end = max(center_index, (m - 1) - center_index)
                dist_to_end = min(idx, (m - 1) - idx)
                if max_dist_end == 0:
                    end_boost = 1.0
                else:
                    end_boost = max(0.0, 1.0 - dist_to_end / max_dist_end)
            else:
                end_boost = 1.0

            local_term = local_savings ** 2.0
            end_factor = 1.0 + end_boost * 0.6

            if max_demand > 0:
                demand_factor = 1.0 + 0.4 * (demand / max_demand)
            else:
                demand_factor = 1.0

            perturb = rng.random() * 0.001

            score = local_term * end_factor * demand_factor + perturb

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

