    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    max_demand = max(demands) if demands else 1

    records = []
    total_nodes = 0

    # First pass: collect per-node metrics
    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # Compute total demand on this route (ignore depot/None)
        route_demand = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Local "savings" (same interpretation as before, but kept as a metric)
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]

            demand = demands[node] if node < len(demands) else 0

            # Route diversity: average intra-route distance for this node
            others = [o for o in route if o is not None and o != 0 and o != node]
            if len(others) > 0:
                avg_dist = sum(distance_matrix[node][o] for o in others) / len(others)
            else:
                avg_dist = 0.0

            records.append({
                'node': node,
                'route': route,
                'idx': idx,
                'm': m,
                'route_demand': route_demand,
                'savings': savings,
                'demand': demand,
                'avg_dist': avg_dist
            })

    # Compute max average distance for normalization
    max_avg_dist = 0.0
    for r in records:
        if r['avg_dist'] > max_avg_dist:
            max_avg_dist = r['avg_dist']

    # Compute scores
    scores = []
    for r in records:
        if cap > 0 and r['route_demand'] <= cap:
            density = ((cap - r['route_demand']) / cap) * (r['demand'] / max_demand if max_demand > 0 else 0.0)
        else:
            density = 0.0

        if max_avg_dist > 0:
            diversity = r['avg_dist'] / max_avg_dist
        else:
            diversity = 0.0

        jitter = (rng.random() - 0.5) * 0.08  # small randomness

        score = 0.5 * r['savings'] + 0.4 * density + 0.1 * diversity + jitter
        scores.append((r['node'], score))

    # Determine k (number of nodes to remove)
    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 3)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

