def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])

    # Build per-route non-depot lists and mappings
    routes_non_dep = []
    node_to_route = {}
    all_nodes = []
    for rid, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        routes_non_dep.append(non_dep)
        for n in non_dep:
            node_to_route[n] = rid
            all_nodes.append(n)
    N = len(all_nodes)

    scores = []

    # Precompute mean_global: mean distance to all non-depot nodes
    mean_global = {}
    if N > 1:
        for i in all_nodes:
            s = 0.0
            for j in all_nodes:
                if j == i:
                    continue
                d = distance_matrix[i][j] if (i < len(distance_matrix) and j < len(distance_matrix[i])) else 0.0
                s += d
            mean_global[i] = s / (N - 1)
    else:
        for i in all_nodes:
            mean_global[i] = 0.0

    # Precompute mean_intra: mean distance to other nodes within the same route
    mean_intra = {}
    for i in all_nodes:
        rid = node_to_route[i]
        non_dep = routes_non_dep[rid]
        L = len(non_dep)
        if L > 1:
            s = 0.0
            for other in non_dep:
                if other == i:
                    continue
                d = distance_matrix[i][other] if (i < len(distance_matrix) and other < len(distance_matrix[i])) else 0.0
                s += d
            mean_intra[i] = s / (L - 1)
        else:
            mean_intra[i] = 0.0

    # Compute scores for each non-depot node
    for i in all_nodes:
        mg = mean_global.get(i, 0.0)
        mi = mean_intra.get(i, 0.0)
        d = demands[i] if i < len(demands) else 0
        L = len(routes_non_dep[node_to_route[i]]) if i in node_to_route else 0

        score = (mg - mi)            # centrality difference
        score += 0.01 * max(0, L - 1) # small route-length boost
        score += 0.05 * d              # demand weighting
        # jitter to diversify
        jitter = (rng.random() - 0.5) * 0.1 * max(1.0, mg + 1.0)
        score += jitter

        scores.append((i, score))

    # Determine k
    if N == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = max(1, int(round(N * frac)))
        if k > N:
            k = N

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    # Build anchors: first non-depot node in each route
    anchors = []
    for route in current_solution:
        anchor = None
        if route:
            for node in route:
                if node is not None and node != 0:
                    anchor = node
                    break
        anchors.append(anchor)

    scores = []
    total_nodes = 0

    for ri, route in enumerate(current_solution):
        if not route:
            continue

        # Non-depot nodes in this route
        non_dep = [n for n in route if (n is not None and n != 0)]
        m = len(non_dep)
        if m == 0:
            continue

        # Route demand
        route_demand = 0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            total_nodes += 1

            # Intra-route dispersion: average distance to other non-depot nodes in this route
            if m <= 1:
                intra_avg = 0.0
            else:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        d = distance_matrix[node][other]
                    else:
                        d = 0.0
                    s += d
                intra_avg = s / (m - 1)

            # Anchor distance: distance to nearest anchor in other routes
            anchor_dist = None
            for aj, anchor in enumerate(anchors):
                if aj == ri:
                    continue
                if anchor is None:
                    continue
                if node < len(distance_matrix) and anchor < len(distance_matrix[node]):
                    d = distance_matrix[node][anchor]
                else:
                    d = 0.0
                if anchor_dist is None or d < anchor_dist:
                    anchor_dist = d
            anchor_term = anchor_dist if anchor_dist is not None else 0.0

            # Demand term
            demand = demands[node] if node < len(demands) else 0

            # Slack (route pressure)
            slack = cap - route_demand
            if slack < 0:
                slack = 0
            ratio_slack = (slack / cap) if cap > 0 else 0.0

            # Small jitter for diversification
            jitter = (rng.random() * 0.15) - 0.075

            # Composite score (higher means more likely to be removed)
            score = (0.45 * intra_avg) + (0.30 * anchor_term) + (0.15 * (1.0 / (1.0 + demand))) + (0.10 * (1.0 - ratio_slack)) + jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        # Choose a diversification-friendly fraction of nodes to remove
        frac = 0.25 + rng.random() * 0.35  # between 0.25 and 0.60
        max_k = max(1, total_nodes // 2)
        k = int(rng.integers(1, max_k + 1))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])
    cap = max(vehicle_capacities) if vehicle_capacities else 0

    # Build per-route node lists and mappings
    route_of = {}
    route_nodes_by_route = []
    all_non_dep = []
    for r_idx, route in enumerate(current_solution):
        nodes = [n for n in route if n != 0]
        route_nodes_by_route.append(nodes)
        for n in nodes:
            route_of[n] = r_idx
            all_non_dep.append(n)

    total_non_dep = len(all_non_dep)

    scores = []
    if total_non_dep > 0:
        # Precompute per-route demands
        route_demands = []
        for nodes in route_nodes_by_route:
            s = 0
            for n in nodes:
                if n < len(demands):
                    s += demands[n]
            route_demands.append(s)

        # Compute cross-route dispersion scores
        for r_idx, nodes in enumerate(route_nodes_by_route):
            if not nodes:
                continue
            for i in nodes:
                cross_sum = 0.0
                cross_cnt = 0
                for j in all_non_dep:
                    if j == i:
                        continue
                    if route_of.get(j) == r_idx:
                        continue
                    cross_sum += distance_matrix[i][j]
                    cross_cnt += 1
                cross_avg = cross_sum / cross_cnt if cross_cnt > 0 else 0.0

                demand_i = demands[i] if i < len(demands) else 0
                route_cap = cap if cap > 0 else 1
                route_factor = 1.0 + (route_demands[r_idx] / route_cap)

                score = cross_avg * route_factor
                score += rng.random() * 0.01 * (cross_avg + 1.0)

                scores.append((i, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])

    routes = current_solution

    # Build per-route lists of non-depot nodes
    non_dep_per_route = []
    total_non_dep = 0
    max_L = 0
    for route in routes:
        non_dep = [n for n in route if n != 0]
        non_dep_per_route.append(non_dep)
        L = len(non_dep)
        total_non_dep += L
        if L > max_L:
            max_L = L

    scores = []

    # Compute cross-route novelty scores for each non-depot node
    for r_idx, route in enumerate(routes):
        non_dep = non_dep_per_route[r_idx]
        L = len(non_dep)
        if L == 0:
            continue

        # Route-length factor to differentiate longer routes
        if max_L > 1:
            route_len_factor = 1.0 + 0.4 * ((L - 1) / float(max_L - 1))
        else:
            route_len_factor = 1.0

        for node in non_dep:
            cross_sum = 0.0
            # Sum distance to nearest node in every other route
            for o_idx, o_route in enumerate(non_dep_per_route):
                if o_idx == r_idx:
                    continue
                if not o_route:
                    continue
                min_dist = None
                for other in o_route:
                    d = distance_matrix[node][other]
                    if (min_dist is None) or (d < min_dist):
                        min_dist = d
                if min_dist is not None:
                    cross_sum += min_dist

            demand = demands[node] if node < len(demands) else 0
            jitter = (rng.random() - 0.5) * 0.2  # [-0.1, 0.1)
            score = cross_sum * 0.5 + demand * 0.9 + route_len_factor * 0.25 + jitter
            scores.append((node, score))

    # Determine k as a random fraction of total non-depot nodes
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.18  # between 0.12 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    # collect all non-depot nodes and map each to its route
    all_nodes = []
    node_routes = {}
    for r_idx, route in enumerate(current_solution):
        for node in route:
            if node is None:
                continue
            if node != 0:
                all_nodes.append(node)
                node_routes[node] = r_idx

    total_non_dep = len(all_nodes)
    if total_non_dep == 0:
        return scores, 0

    # max distance to depot for normalization
    max_dist_to_depot = 0
    for node in all_nodes:
        d = distance_matrix[node][0]
        if d > max_dist_to_depot:
            max_dist_to_depot = d

    # max distance across all pairs for center normalization
    max_dist_all = 0
    n_nodes_all = len(distance_matrix)
    for i in range(n_nodes_all):
        row = distance_matrix[i]
        for j in range(n_nodes_all):
            if row[j] > max_dist_all:
                max_dist_all = row[j]
    if max_dist_all == 0:
        max_dist_all = 1

    # per-route demand and node lists
    route_demands = {}
    route_nodes_map = {}
    for r_idx, route in enumerate(current_solution):
        non_dep_in_route = [n for n in route if n != 0 and n is not None]
        L = len(non_dep_in_route)
        dsum = 0
        for n in non_dep_in_route:
            if n < len(demands):
                dsum += demands[n]
        route_demands[r_idx] = dsum
        route_nodes_map[r_idx] = non_dep_in_route

    max_demand = max(demands) if demands else 0
    if max_demand <= 0:
        max_demand = 1

    # choose a global center node as the node with minimal sum of distances to all other non-depot nodes
    center_node = None
    best_sum = None
    for cand in all_nodes:
        s = 0
        for other in all_nodes:
            if other == cand:
                continue
            s += distance_matrix[cand][other]
        if best_sum is None or s < best_sum:
            best_sum = s
            center_node = cand

    for node in all_nodes:
        r = node_routes[node]
        # depot-distance normalization
        dep_norm = distance_matrix[node][0] / max_dist_to_depot if max_dist_to_depot > 0 else 0.0

        # route slack normalization
        route_demand = route_demands.get(r, 0)
        slack_norm = 0.0
        if cap > 0:
            val = (cap - route_demand) / cap
            if val < 0:
                val = 0.0
            slack_norm = val

        # demand normalization
        demand = demands[node] if node < len(demands) else 0
        demand_norm = demand / max_demand if max_demand > 0 else 0.0

        # center diversity term
        center_dist_norm = distance_matrix[node][center_node] / max_dist_all if center_node is not None else 0.0

        # small random perturbation for diversification
        jitter = rng.random() * 0.08

        # weighted combination (totals to about 1, plus jitter)
        score = (0.35 * dep_norm) + (0.25 * slack_norm) + (0.25 * demand_norm) + (0.15 * center_dist_norm) + jitter

        scores.append((node, score))

    # determine k
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.10  # between 0.15 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    N = len(distance_matrix) if distance_matrix is not None else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        for node in route:
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Global mean distance to all other nodes
            if N > 1:
                s = 0.0
                for j in range(N):
                    if j == node:
                        continue
                    s += distance_matrix[node][j]
                mean_dist = s / (N - 1)
            else:
                mean_dist = 0.0

            demand = demands[node] if node < len(demands) else 0
            score = mean_dist * 0.9 + demand * 0.4

            # Small random jitter to diversify
            jitter = (rng.random() - 0.5) * 0.6  # [-0.3, 0.3)
            score += jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.12 + (rng.random() ** 2) * 0.23  # biased toward smaller fractions
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # gather all routes and mapping from node to its current route
    routes = current_solution
    node_to_route = {}
    total_non_dep = 0

    for r_idx, route in enumerate(routes):
        non_dep = [n for n in route if n != 0]
        total_non_dep += len(non_dep)
        for n in non_dep:
            node_to_route[n] = r_idx

    # compute max distance to use as a fallback when no other routes exist
    max_dist = 0.0
    N = len(distance_matrix)
    for i in range(N):
        row = distance_matrix[i]
        for j in range(N):
            d = row[j]
            if d > max_dist:
                max_dist = d

    scores = []

    for r_idx, route in enumerate(routes):
        nodes = [n for n in route if n != 0]
        if not nodes:
            continue

        # For each node, compute minimal reinsertion delta into any other route
        for node in nodes:
            min_delta = None
            # search across all other routes
            for j_idx, other_route in enumerate(routes):
                if j_idx == r_idx:
                    continue
                other_nodes = [n for n in other_route if n != 0]
                m = len(other_nodes)

                if m == 0:
                    delta = distance_matrix[0][node] + distance_matrix[node][0]  # insert at depot path
                    if (min_delta is None) or (delta < min_delta):
                        min_delta = delta
                else:
                    # try inserting at every position in the non-depot sequence
                    for pos in range(m + 1):
                        if pos == 0:
                            a = 0
                            b = other_nodes[0]
                        elif pos == m:
                            a = other_nodes[m-1]
                            b = 0
                        else:
                            a = other_nodes[pos - 1]
                            b = other_nodes[pos]
                        delta = distance_matrix[a][node] + distance_matrix[node][b] - distance_matrix[a][b]
                        if (min_delta is None) or (delta < min_delta):
                            min_delta = delta

            # if there is no other route to consider (single route scenario)
            if min_delta is None:
                min_delta = max_dist

            demand = demands[node] if node < len(demands) else 0
            jitter = (rng.random() * 0.5) - 0.25  # in [-0.25, 0.25)
            score = min_delta - 0.1 * demand + jitter
            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.16  # between 0.12 and 0.28
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # determine a reasonable number of nodes to project
    N = 0
    if isinstance(demands, list):
        N = max(N, len(demands))
    if isinstance(distance_matrix, list):
        N = max(N, len(distance_matrix))
    else:
        try:
            N = max(N, int(getattr(distance_matrix, 'shape', [0])[0]))
        except Exception:
            pass
    if N <= 0:
        return [], 0

    # generate a random projection value for each node (stable across routes)
    proj = [0.0] * N
    for i in range(N):
        proj[i] = rng.random()

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        factor = 1.0 + 0.25 * (L - 1)

        for node in non_dep:
            s = 0.0
            if L > 1:
                p_i = proj[node] if 0 <= node < len(proj) else 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    p_j = proj[other] if 0 <= other < len(proj) else 0.0
                    s += abs(p_i - p_j)
            demand = demands[node] if 0 <= node < len(demands) else 0
            score = s * factor / (1.0 + 0.8 * demand)
            jitter = rng.random() * 0.05 * (s + 1.0)
            score += jitter
            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.1 + rng.random() * 0.2  # between 0.1 and 0.3
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Per-node betweenness-like centrality within the route
        betweenness = {}
        for node in non_dep:
            other_nodes = [x for x in non_dep if x != node]
            m = len(other_nodes)
            btwn = 0.0
            if m >= 2:
                for i_idx in range(m):
                    i = other_nodes[i_idx]
                    for j_idx in range(i_idx + 1, m):
                        j = other_nodes[j_idx]
                        if distance_matrix[i][j] == distance_matrix[i][node] + distance_matrix[node][j]:
                            w = 1.0 / (1.0 + distance_matrix[i][j])
                            btwn += w
            betweenness[node] = btwn

        # Mean distance to others in the route
        mean_to_others = {}
        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_to_others[node] = s / (L - 1)
            else:
                mean_to_others[node] = 0.0

        for node in non_dep:
            score = betweenness.get(node, 0.0) * 2.0
            score += mean_to_others.get(node, 0.0) * 0.8

            demand = demands[node] if node < len(demands) else 0
            score -= 0.5 * demand

            jitter = rng.random() * 0.6 - 0.3
            score += jitter

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.14 + rng.random() * 0.11  # between 0.14 and 0.25
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])

    # Collect all non-depot nodes present in the solution
    node_set = set()
    for route in current_solution:
        for node in route:
            if node != 0:
                node_set.add(node)
    nodes_pool = sorted(node_set)
    total_nodes = len(nodes_pool)

    scores = []

    # Choose up to 5 centers deterministically from the pool (to ensure no loops)
    P = min(5, total_nodes)
    centers = nodes_pool[:P] if P > 0 else []

    # Precompute mean distance to centers for each node
    mean_dist_to_centers = {}
    if total_nodes > 0 and P > 0:
        for n in nodes_pool:
            s = 0.0
            for c in centers:
                d = distance_matrix[n][c] if (n < len(distance_matrix) and c < len(distance_matrix[n])) else 0.0
                s += d
            mean_dist_to_centers[n] = s / P
    else:
        for n in nodes_pool:
            mean_dist_to_centers[n] = 0.0

    # Compute route-position fraction for each node (0.0 to 1.0 within its route)
    pos_frac = {}
    for route in current_solution:
        route_nodes = [n for n in route if n != 0]
        L = len(route_nodes)
        if L == 0:
            continue
        if L == 1:
            pos_frac[route_nodes[0]] = 0.0
        else:
            for idx, n in enumerate(route_nodes):
                pos_frac[n] = idx / (L - 1)

    # Random projection weights
    w1 = rng.random()
    w2 = rng.random()
    jitter_bound = 0.05

    for n in nodes_pool:
        mean_center = mean_dist_to_centers.get(n, 0.0)
        pf = pos_frac.get(n, 0.0)
        score = w1 * mean_center + w2 * pf
        score += rng.random() * jitter_bound
        scores.append((n, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        route_nodes = [n for n in route if n is not None and n != 0]
        m = len(route_nodes)
        if m == 0:
            continue

        # Determine a threshold for "local" edges within this route
        max_d = 0.0
        for i in range(m):
            ni = route_nodes[i]
            for j in range(i + 1, m):
                nj = route_nodes[j]
                if ni < len(distance_matrix) and nj < len(distance_matrix[ni]):
                    d = distance_matrix[ni][nj]
                    if d > max_d:
                        max_d = d
        threshold = max_d * 0.5

        # Build local centrality: sum of distances to nearby peers within threshold
        centrality = {node: 0.0 for node in route_nodes}
        for i in range(m):
            ni = route_nodes[i]
            for j in range(i + 1, m):
                nj = route_nodes[j]
                if ni < len(distance_matrix) and nj < len(distance_matrix[ni]):
                    d = distance_matrix[ni][nj]
                    if d <= threshold:
                        centrality[ni] += d
                        centrality[nj] += d

        for node in route_nodes:
            total_nodes += 1
            cent = centrality[node]
            demand = demands[node] if node < len(demands) else 0
            score = cent * 0.95 - demand * 0.25
            jitter = rng.random() * 0.4 - 0.2  # [-0.2, 0.2)
            score += jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, int(total_nodes * 0.25))
        k = int(rng.integers(1, max_k + 1))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0
    max_demand = max(demands) if demands else 1

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # Compute total demand on this route (ignore depot/None)
        route_demand = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Altered local-savings: endpoints use distance to neighbor, internal uses a combination
            if m == 1:
                base_savings = 0.0
            elif idx == 0:
                next_node = route[1]
                base_savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                base_savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                base_savings = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - 0.5 * distance_matrix[prev_node][next_node]

            demand = demands[node] if node < len(demands) else 0

            # Density term based on remaining capacity and node demand
            if cap > 0:
                fill = (cap - route_demand) / cap
                if fill < 0:
                    fill = 0.0
            else:
                fill = 0.0
            normalized_demand = demand / max_demand if max_demand > 0 else 0.0
            density = fill * normalized_demand

            jitter = (rng.random() - 0.5) * 0.25  # [-0.125, 0.125)
            score = base_savings * 0.6 + density * 0.4 + jitter
            scores.append((node, score))

    max_k = max(1, total_nodes // 5) if total_nodes > 0 else 0
    if total_nodes == 0:
        k = 0
    else:
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # route total demand
        route_total_demand = 0
        for node in non_dep:
            if node < len(demands):
                route_total_demand += demands[node]

        for idx, node in enumerate(non_dep):
            # distances to other nodes in the same route
            dist_list = []
            for other in non_dep:
                if other == node:
                    continue
                dist_list.append(distance_matrix[node][other])
            dist_list.sort()

            if len(dist_list) >= 2:
                d1, d2 = dist_list[0], dist_list[1]
                neighbor_sum = d1 + d2
            elif len(dist_list) == 1:
                neighbor_sum = dist_list[0] * 2.0
            else:
                neighbor_sum = 0.0

            route_size_factor = 1.0 + 0.12 * (L - 1)
            demand = demands[node] if node < len(demands) else 0
            demand_factor = 1.0 / (1.0 + 0.5 * route_total_demand)
            pos_factor = 1.0 + 0.04 * idx

            if neighbor_sum > 0:
                score = (neighbor_sum ** 0.75) * route_size_factor * demand_factor * pos_factor
            else:
                score = 0.0

            perturb = rng.random() * 0.03 * (neighbor_sum + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.20  # between 0.10 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    n_nodes = len(distance_matrix)
    # Pre-compute maximum distance in the matrix for normalization
    max_dist = 0
    for i in range(n_nodes):
        row = distance_matrix[i]
        for j in range(n_nodes):
            if i == j:
                continue
            d = row[j]
            if d > max_dist:
                max_dist = d

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue
        m = len(route)

        # Compute total demand for the route
        route_demand = 0
        for node in route:
            if node is None or node == 0:
                continue
            if node < len(demands):
                route_demand += demands[node]

        for idx, node in enumerate(route):
            if node is None or node == 0:
                continue
            total_nodes += 1

            # Local removal impact (savings-like)
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                savings = distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]

            # Slack and demand pressure
            slack = cap - route_demand
            if slack < 0:
                slack = 0

            # Diversity term: average distance to other nodes in the same route
            sum_dist = 0
            count = 0
            for other in route:
                if other is None or other == 0 or other == node:
                    continue
                sum_dist += distance_matrix[node][other]
                count += 1
            if count > 0:
                avg_dist = sum_dist / count
            else:
                avg_dist = 0.0

            if max_dist > 0:
                norm_dist = avg_dist / max_dist
            else:
                norm_dist = 0.0
            diversity_term = 1.0 - norm_dist  # higher when node is further from others

            demand = demands[node] if node < len(demands) else 0
            jitter = rng.random() * 0.25 - 0.12

            # New score: combine local impact, diversity, and demand pressure
            score = (savings * 0.4) + (diversity_term * 0.35) + (demand * 0.25) / (slack + 1) + jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

