                min_dist = 0.0

            d_to_depot = distance_matrix[i][0] if (i < len(distance_matrix) and 0 < len(distance_matrix[i])) else 0.0
            demand_i = demands[i] if i < len(demands) else 0
            length_factor = 1.0 + 0.7 * (route_len - 1)
            score = (0.6 * min_dist + 0.3 * d_to_depot + 0.1 * route_load) * length_factor / (1.0 + demand_i)

            score += rng.random() * 0.05 * (min_dist + d_to_depot + 1.0)

