            total_nodes += 1

            # nonlinear detour term (variant of local removal effect)
            if m == 1:
                detour = 0.0
            elif idx == 0:
                next_node = route[1]
                detour = distance_matrix[node][next_node] ** 1.5
            elif idx == m - 1:
                prev_node = route[idx - 1]
                detour = distance_matrix[prev_node][node] ** 1.5
            else:
                prev_node = route[idx - 1]
                next_node = route[idx + 1]
                detour = (distance_matrix[prev_node][node] + distance_matrix[node][next_node] - distance_matrix[prev_node][next_node]) ** 1.5

            demand = demands[node] if node < len(demands) else 0
            slack = cap - route_demand
            if slack < 0:
                slack = 0

            # capacity-based scaling
            cap_factor = 1.0 / (slack + 1)

            # route-position jitter factor (emphasize interior vs ends)
            if m <= 2:
                pos_factor = 0.9
            else:
                pos_factor = 0.9 if (idx == 0 or idx == m - 1) else 1.1

            jitter = rng.random() * 0.25 - 0.125

            # combined score (different weighting and nonlinear terms)
            score = detour * 0.6 * pos_factor + (demand * 0.3) * cap_factor + jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
