                        best2 = d
                near_sum = best1 + best2 if best2 != float('inf') else best1
            else:
                near_sum = 0.0

            demand = demands[node] if node < len(demands) else 0

            score = near_sum * factor
            score /= (1.0 + 0.9 * demand)

            perturb = rng.random() * 0.05 * (near_sum + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.10  # between 0.05 and 0.15
        k = max(1, int(round(total_non_dep * frac)))
