def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    # collect all unique non-depot nodes present in the solution
    all_nodes = []
    for route in current_solution:
        if not route:
            continue
        for n in route:
            if n is None or n == 0:
                continue
            if n not in all_nodes:
                all_nodes.append(n)

    for route in current_solution:
        if not route:
            continue

        route_nodes = [n for n in route if n is not None and n != 0]
        m = len(route_nodes)
        if m == 0:
            continue

        # compute total demand on this route
        route_demand = 0
        for node in route_nodes:
            if node < len(demands):
                route_demand += demands[node]

        # determine a route center (node with minimal sum of distances to others)
        center_node = None
        if len(route_nodes) >= 2:
            best_sum = None
            for cand in route_nodes:
                s = 0
                for other in route_nodes:
                    if other == cand:
                        continue
                    s += distance_matrix[cand][other]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    center_node = cand
        elif len(route_nodes) == 1:
            center_node = route_nodes[0]

        for idx, node in enumerate(route_nodes):
            total_nodes += 1

            # Local detour savings
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route_nodes[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route_nodes[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route_nodes[idx - 1]
                next_node = route_nodes[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            # Diversity term: average distance to all other distinct nodes
            if len(all_nodes) > 1:
                total_dist = 0.0
                for other in all_nodes:
                    if other == node:
                        continue
                    total_dist += distance_matrix[node][other]
                diversity_term = total_dist / (len(all_nodes) - 1)
            else:
                diversity_term = 0.0

            # Load-balance regularizer based on route utilization
            if cap > 0:
                route_utilization = route_demand / cap
                balance_term = 1.0 - abs(route_utilization - 0.5) * 2.0
                if balance_term < 0.0:
                    balance_term = 0.0
            else:
                balance_term = 0.0

            # Center distance bonus (favor nodes farther from center)
            center_dist = distance_matrix[node][center_node] if center_node is not None else 0.0
            center_bonus = (center_dist ** 0.6) * 0.4

            # jitter
            jitter = rng.normal(0.0, 0.15)

            score = savings * 0.55 + diversity_term * 0.25 + balance_term * 0.15 + center_bonus + jitter
            scores.append((node, score))

    max_k = max(1, total_nodes // 3) if total_nodes > 0 else 0
    if total_nodes == 0:
        k = 0
    else:
        k = int(rng.integers(1, max_k + 1))

    return scores, k

