def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # Build mapping from node to its route index
    node_route = {}
    for ri, route in enumerate(current_solution):
        for node in route:
            if node is None or node == 0:
                continue
            node_route[node] = ri

    scores = []
    total_nodes = 0

    for ri, route in enumerate(current_solution):
        # Collect non-depot nodes in this route
        route_nodes = []
        for n in route:
            if n is None or n == 0:
                continue
            route_nodes.append(n)
        m = len(route_nodes)
        if m == 0:
            continue

        for idx, node in enumerate(route_nodes):
            total_nodes += 1

            # Local detour savings
            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route_nodes[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route_nodes[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route_nodes[idx - 1]
                next_node = route_nodes[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            # Cross-route proximity: distance to nearest node in a different route
            cross_min = None
            for other_node, other_ri in node_route.items():
                if other_ri == ri:
                    continue
                d = distance_matrix[node][other_node]
                if cross_min is None or d < cross_min:
                    cross_min = d
            cross_factor = 0.0 if cross_min is None else 1.0 / (1.0 + cross_min)

            # Intra-route cohesion (mean distance to other nodes in the same route)
            intra_mean = 0.0
            if m > 1:
                s = 0.0
                for other in route_nodes:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                intra_mean = s / (m - 1)

            # Demand term
            demand = demands[node] if node < len(demands) else 0

            # Score combines local savings, cross proximity, and demand with a cohesion penalty
            score = savings * 0.5
            score += cross_factor * 0.25
            score += (demand / (1.0 + intra_mean)) * 0.25
            jitter = (rng.random() * 0.2) - 0.1  # [-0.1, 0.1)
            score += jitter
            # Penalize high cohesion (large intra_mean) to favor removal of less-integrated nodes
            score -= 0.15 * intra_mean

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.12  # between 0.08 and 0.20
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

