        dists = []
        for i in range(len(route_nodes)):
            ni = route_nodes[i]
            for j in range(i + 1, len(route_nodes)):
                nj = route_nodes[j]
                dists.append(distance_matrix[ni][nj])

        if dists:
            dists.sort()
            L = len(dists)
            mid = L // 2
            if L % 2 == 1:
                median_dist = dists[mid]
            else:
                median_dist = (dists[mid - 1] + dists[mid]) / 2.0
        else:
            median_dist = 0.0

        for node in route_nodes:
            total_nodes += 1

            # density: number of other nodes within median_dist
            if m > 1:
                density = 0
                for other in route_nodes:
                    if other == node:
                        continue
                    if distance_matrix[node][other] <= max(0.0, median_dist):
                        density += 1
                density_norm = density / (m - 1)
            else:
                density_norm = 0.0

            # demand contribution (nonlinear)
            demand = demands[node] if node < len(demands) else 0
            score = density_norm * 1.8
            if demand > 0:
                score += (demand ** 0.4) * 0.9

            # small jitter for diversification
            jitter = rng.random() * 0.25 - 0.125  # [-0.125, 0.125)
            score += jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.15  # between 0.15 and 0.30
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # Collect all non-depot nodes globally
    global_nodes = []
    for route in current_solution:
        for node in route:
            if node != 0:
                global_nodes.append(node)

    scores = []
    total_non_dep = len(global_nodes)

    for route in current_solution:
        # Non-depot nodes in this route
        route_nodes = [n for n in route if n != 0]
        L = len(route_nodes)
        if L == 0:
            continue

        # Route-length factor grows with route length
        route_len_factor = 1.0 + 0.25 * (L - 1)

        for node in route_nodes:
            # Potential targets exclude the node itself
            potential_targets = [n for n in global_nodes if n != node]
            sample_size = 4
            num_targets = min(sample_size, len(potential_targets))

            if num_targets > 0:
                sdist = 0.0
                for _ in range(num_targets):
                    t = potential_targets[int(rng.random() * len(potential_targets))]
                    if node < len(distance_matrix) and t < len(distance_matrix[node]):
                        sdist += distance_matrix[node][t]
                    else:
                        sdist += 0.0
                mean_dist = sdist / num_targets
            else:
                mean_dist = 0.0

            demand = demands[node] if node < len(demands) else 0
            score = mean_dist * route_len_factor / (1.0 + 0.5 * demand)

            perturb = rng.random() * 0.04 * (mean_dist + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.25  # between 0.05 and 0.30
        k = int(round(total_non_dep * frac))
        if k < 1:
            k = 1
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    records = []
    total_non_dep = 0
    max_route_len = 1

    # First pass: gather per-node metrics and max route length
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L > max_route_len:
            max_route_len = L
    # Guard against degenerate cases
    if max_route_len <= 1:
        max_route_len = 2

    global_max_disp = 0.0

    for route_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue
        total_non_dep += L

        for idx, node in enumerate(non_dep):
            # Compute delta (local edge-savings disruption) for removal
            if L == 1:
                delta = 0.0
                base = 0.0
            else:
                if idx == 0:
                    next_node = non_dep[1]
                    delta = distance_matrix[node][next_node] - (distance_matrix[0][node] + distance_matrix[node][next_node])
                elif idx == L - 1:
                    prev_node = non_dep[idx - 1]
                    delta = - distance_matrix[prev_node][node]
                else:
                    prev_node = non_dep[idx - 1]
                    next_node = non_dep[idx + 1]
                    delta = distance_matrix[prev_node][next_node] - (distance_matrix[prev_node][node] + distance_matrix[node][next_node])
                base = max(0.0, -delta)

            # Dispersion: mean distance to other non-depot nodes in the same route
            if L > 1:
                sum_dist = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    sum_dist += distance_matrix[node][other]
                dispersion = sum_dist / (L - 1)
            else:
                dispersion = 0.0

            if dispersion > global_max_disp:
                global_max_disp = dispersion

            records.append((route_idx, node, L, base, dispersion))

    # Second pass: compute scores
    for (route_idx, node, L, base, dispersion) in records:
        route_len_factor = 1.0
        if max_route_len > 1:
            route_len_factor = 1.0 + 0.4 * (L - 1) / (max_route_len - 1)

        dispersion_norm = dispersion / (global_max_disp if global_max_disp > 0.0 else 1.0)
        score = (base ** 1.25) * (1.0 + dispersion_norm) * route_len_factor

        jitter = rng.random() * 0.1 * (base + dispersion_norm + 1.0)
        score += jitter

        scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.16 + rng.random() * 0.24  # between 0.16 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_nodes = 0

    for route in current_solution:
        # consider only real nodes (non-depot)
        route_nodes = [n for n in route if (n is not None) and n != 0]
        L = len(route_nodes)
        if L == 0:
            continue

        total_nodes += L

        # total demand on this route
        route_total_demand = 0
        for node in route_nodes:
            if node < len(demands):
                route_total_demand += demands[node]

        # determine a route center (node with minimal sum of distances to others)
        center_node = None
        if L >= 2:
            best_sum = None
            for cand in route_nodes:
                s = 0
                for other in route_nodes:
                    if other == cand:
                        continue
                    s += distance_matrix[cand][other]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    center_node = cand
        elif L == 1:
            center_node = route_nodes[0]

        for idx, node in enumerate(route_nodes):
            # farthest distance to any other node in this route
            farthest = 0.0
            if L > 1:
                for other in route_nodes:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if d > farthest:
                        farthest = d

            # demand density within the route
            demand = demands[node] if node < len(demands) else 0
            demand_density = (demand / (route_total_demand + 1)) if route_total_demand > 0 else 0.0

            # center distance and centrality
            center_dist = distance_matrix[node][center_node] if center_node is not None else 0.0
            centrality = 1.0 / (center_dist + 1.0)

            # route size factor
            factor = 1.0 + 0.25 * (L - 1)

            # jitter
            jitter = rng.random() * 0.2 - 0.1

            # composite score (distinct combination)
            score = farthest * 0.8 * factor + demand_density * 1.6 * factor + centrality * (1.0 / factor) + jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.15  # between 0.05 and 0.20
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_nodes = 0

    for route in current_solution:
        route_nodes = [n for n in route if n is not None and n != 0]
        m = len(route_nodes)
        if m == 0:
            continue

        # choose a random pivot in this route
        pivot = route_nodes[rng.integers(0, m)]

        # compute distance to pivot for each node
        dist_to_pivot = []
        for node in route_nodes:
            d = distance_matrix[node][pivot] if (node < len(distance_matrix) and pivot < len(distance_matrix[node])) else 0.0
            dist_to_pivot.append((node, d))

        # compute median distance to define two clusters
        dists = [d for (_, d) in dist_to_pivot]
        if len(dists) == 0:
            median_dist = 0.0
        else:
            sorted_d = sorted(dists)
            mid = len(sorted_d) // 2
            median_dist = sorted_d[mid]

        cluster_in = set()
        cluster_out = set()
        for node, d in dist_to_pivot:
            if d <= median_dist:
                cluster_in.add(node)
            else:
                cluster_out.add(node)

        for node, _ in dist_to_pivot:
            total_nodes += 1

            if node in cluster_in:
                in_cluster = cluster_in
                out_cluster = cluster_out
            else:
                in_cluster = cluster_out
                out_cluster = cluster_in

            # intra-cluster mean distance
            if len(in_cluster) <= 1:
                din = 0.0
            else:
                s_in = 0.0
                for other in in_cluster:
                    if other == node:
                        continue
                    s_in += distance_matrix[node][other] if (node < len(distance_matrix) and other < len(distance_matrix[node])) else 0.0
                din = s_in / (len(in_cluster) - 1)

            # cross-cluster mean distance
            if len(out_cluster) == 0:
                dout = 0.0
            else:
                s_out = 0.0
                for other in out_cluster:
                    s_out += distance_matrix[node][other] if (node < len(distance_matrix) and other < len(distance_matrix[node])) else 0.0
                dout = s_out / len(out_cluster)

            demand = demands[node] if node < len(demands) else 0
            jitter = (rng.random() - 0.5) * 0.2  # [-0.1, 0.1)

            score = (dout - din) * 0.9 + demand * 0.25 + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.2  # between 0.15 and 0.35
        k = int(round(total_nodes * frac))
        if k < 1:
            k = 1
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    all_nodes = []

    # collect all non-depot nodes in the solution
    for route in current_solution:
        for n in route:
            if n != 0:
                all_nodes.append(n)

    total_non_dep = len(all_nodes)

    # precompute global centrality: sum of distances from i to all other non-depot nodes
    sum_to_others = {}
    for i in all_nodes:
        s = 0.0
        row_i = distance_matrix[i]
        for j in all_nodes:
            if i == j:
                continue
            s += row_i[j]
        sum_to_others[i] = s

    # precompute route-level info for each node
    node_route_len = {}
    node_route_demand = {}

    for route in current_solution:
        route_nodes = [n for n in route if n != 0]
        m = len(route_nodes)
        route_demand = 0
        for n in route_nodes:
            if n < len(demands):
                route_demand += demands[n]
        for n in route_nodes:
            node_route_len[n] = m
            node_route_demand[n] = route_demand

    # compute scores for each non-depot node
    for route in current_solution:
        route_nodes = [n for n in route if n != 0]
        if not route_nodes:
            continue
        for node in route_nodes:
            sum_others = sum_to_others.get(node, 0.0)
            depot_distance = distance_matrix[node][0] if len(distance_matrix) > 0 and len(distance_matrix[node]) > 0 else 0.0
            demand_node = demands[node] if node < len(demands) else 0
            route_len = node_route_len.get(node, len(route_nodes))
            route_demand = node_route_demand.get(node, 0)

            # logistic-like factor based on slack relative to capacity
            if cap > 0:
                slack_ratio = (cap - route_demand) / cap
                if slack_ratio < 0:
                    slack_ratio = 0.0
                logistic_factor = 1.0 / (1.0 + (2.718281828 ** (-12.0 * (slack_ratio - 0.5))))
            else:
                logistic_factor = 0.5

            route_len_factor = 1.0 + 0.4 * ((route_len - 1) / max(1, route_len))

            jitter = (rng.random() * 0.2) - 0.1  # [-0.1, 0.1)

            score = (sum_others * 0.5 + depot_distance * 0.25 + demand_node * 0.2) * logistic_factor * route_len_factor + jitter
            scores.append((node, score))

    # determine how many nodes to remove
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.22  # between 0.12 and 0.34
        k = int(round(total_non_dep * frac))
        if k < 1:
            k = 1
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    total_nodes = 0
    scores = []

    for route in current_solution:
        if not route:
            continue
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_nodes += L

        for node in non_dep:
            if L > 1:
                dispersion = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    dispersion += d * d
                dispersion_norm = dispersion / (L - 1)
            else:
                dispersion_norm = 0.0

            demand = demands[node] if node < len(demands) else 0
            demand_term = demand * 0.2
            jitter = (rng.random() - 0.5) * 0.05  # [-0.025, 0.025)
            score = dispersion_norm * 0.9 + demand_term + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        max_k = max(1, total_nodes // 4)
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    # Build the global set of non-depot nodes
    all_nodes = []
    for route in current_solution:
        for node in route:
            if node is None:
                continue
            if node == 0:
                continue
            all_nodes.append(node)

    # Precompute, for each node, the sum of its 3 nearest-neighbor distances globally
    K = 3
    nearest_sum = {}
    if len(all_nodes) > 1:
        for node in all_nodes:
            dists = []
            for other in all_nodes:
                if other == node:
                    continue
                dists.append(distance_matrix[node][other])
            dists.sort()
            k_considered = min(K, len(dists))
            nearest_sum[node] = sum(dists[:k_considered])
    else:
        for node in all_nodes:
            nearest_sum[node] = 0.0

    # Compute scores per node, per route
    for route in current_solution:
        if not route:
            continue
        route_nodes = [n for n in route if n is not None and n != 0]
        L = len(route_nodes)
        if L == 0:
            continue

        # route demand
        route_demand = 0
        for node in route_nodes:
            if node < len(demands):
                route_demand += demands[node]

        # route slack factor (influence of removing in more slackful routes)
        slack = cap - route_demand
        if slack < 0:
            slack = 0
        route_influence = 0.4
        if cap and cap > 0:
            slack_share = slack / cap
            # push influence higher for routes with more slack, up to 1.0
            route_influence = 0.4 + 0.6 * max(0.0, min(1.0, slack_share))

        for node in route_nodes:
            total_nodes += 1

            ext_reach = nearest_sum.get(node, 0.0)

            demand = demands[node] if node < len(demands) else 0
            demand_factor = 1.0 / (1.0 + demand)

            jitter = (rng.random() - 0.5) * 0.2  # [-0.1, 0.1)

            score = ext_reach * 1.0 + demand_factor * 0.8 + route_influence * 0.6 + jitter
            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.15  # between 0.10 and 0.25
        k = max(1, int(round(total_nodes * frac)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # vehicle_capacities used only for compatibility; not required for this heuristic
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Compute mean intra-route distance for each node in this route
        mean_intra_map = {}
        for i in non_dep:
            if L > 1:
                s = 0.0
                for j in non_dep:
                    if j == i:
                        continue
                    s += distance_matrix[i][j]
                mean_intra = s / (L - 1)
            else:
                mean_intra = 0.0
            mean_intra_map[i] = mean_intra

        max_mean_intra = max(mean_intra_map.values()) if mean_intra_map else 0.0

        # Compute normalization factors: max distance between non-depots and max distance to depot
        max_pair = 0.0
        for a in non_dep:
            for b in non_dep:
                if a == b:
                    continue
                d = distance_matrix[a][b]
                if d > max_pair:
                    max_pair = d

        max_to_depot = 0.0
        for a in non_dep:
            d = distance_matrix[a][0]
            if d > max_to_depot:
                max_to_depot = d

        max_route_norm = max(max_pair, max_to_depot)
        den_den = max_route_norm if max_route_norm > 0 else 1.0

        max_demand_route = max((demands[n] for n in non_dep), default=0)
        for i in non_dep:
            mean_intra = mean_intra_map[i]
            normalized_intra = (mean_intra / (max_mean_intra + 1e-9)) if max_mean_intra > 0 else 0.0
            depot_dist = distance_matrix[i][0]
            normalized_dep = depot_dist / den_den

            demand = demands[i] if i < len(demands) else 0
            demand_norm = (demand / (max_demand_route + 1e-9)) if max_demand_route > 0 else 0.0

            score = 0.6 * normalized_intra + 0.25 * normalized_dep + 0.15 * demand_norm

            jitter = (rng.random() * 0.2) - 0.1  # [-0.1, 0.1)
            score += jitter

            scores.append((i, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.25  # between 0.12 and 0.37
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0
    if cap <= 0:
        cap = 1

    # global normalization for demands
    max_demand = max(demands) if demands else 0
    if max_demand <= 0:
        max_demand = 1

    scores = []
    total_non_dep = 0

    for route in current_solution:
        if not route:
            continue

        route_nodes = [n for n in route if n is not None and n != 0]
        L = len(route_nodes)
        if L == 0:
            continue

        # route demand
        route_demand = 0
        for n in route_nodes:
            if n < len(demands):
                route_demand += demands[n]

        # route centroid (node with minimal sum of distances to others)
        center_node = None
        if L >= 2:
            best_sum = None
            for cand in route_nodes:
                s = 0
                for other in route_nodes:
                    if other == cand:
                        continue
                    s += distance_matrix[cand][other]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    center_node = cand
        elif L == 1:
            center_node = route_nodes[0]

        # max distance from centroid to normalize centrality
        max_center_dist = 0
        if center_node is not None:
            for other in route_nodes:
                if other == center_node:
                    continue
                d = distance_matrix[center_node][other]
                if d > max_center_dist:
                    max_center_dist = d

        # per-node scoring
        for node in route_nodes:
            total_non_dep += 1

            # centrality component: distance to centroid normalized
            centrality_component = 0.0
            if center_node is not None:
                dist_to_centroid = distance_matrix[node][center_node]
                centrality_component = dist_to_centroid / (max_center_dist + 1.0)

            # demand normalization
            demand = demands[node] if node < len(demands) else 0
            demand_norm = demand / max_demand

            # slack-driven utilization term
            slack = cap - route_demand
            if slack < 0:
                slack = 0
            slack_ratio = slack / cap

            # jitter for diversification
            jitter = (rng.random() - 0.5) * 0.6  # [-0.3, 0.3)

            score = centrality_component * 1.2 + demand_norm * 0.9 + slack_ratio * 0.8 + jitter
            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.15  # between 0.05 and 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
