        # For each node, compute a projected score as mean of signed distances to other nodes in route
        for i in non_dep:
            s = 0.0
            for j in non_dep:
                if j == i:
                    continue
                s += weights[j] * distance_matrix[i][j]
            score = s / (L - 1) if L > 1 else 0.0
            scores.append((i, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.20  # between 0.10 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    node_scores = {}
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Precompute base influence for each node in this route
        base_influence = {}
        for node in non_dep:
            demand = demands[node] if node < len(demands) else 0
            base_influence[node] = 1.0 / (1.0 + 0.5 * demand)

        # Diffusion-like one-step influence: each node i collects contributions from others j
        for i in non_dep:
            score_i = 0.0
            for j in non_dep:
                if j == i:
                    continue
                dist = distance_matrix[i][j]
                weight = 1.0 / (1.0 + dist)
                score_i += base_influence[j] * weight
            node_scores[i] = node_scores.get(i, 0.0) + score_i

    # Build scores list
    for node, sc in node_scores.items():
        scores.append((node, sc))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.15  # 0.05 to 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Build quick mappings
    routes = current_solution
    node_route = {}  # node -> route index
    for r_idx, route in enumerate(routes):
        for n in route:
            if n != 0:
                node_route[n] = r_idx

    # Precompute per-route loads and total demand
    route_loads = {}
    total_demand = 0
    total_routes = 0
    for r_idx, route in enumerate(routes):
        load = 0
        has_node = False
        for n in route:
            if n != 0:
                has_node = True
                demands_n = demands[n] if n < len(demands) else 0
                load += demands_n
        route_loads[r_idx] = load
        if has_node:
            total_routes += 1
        total_demand += load

    # Prepare scores
    scores = []
    total_nodes = 0

    for r_idx, route in enumerate(routes):
        # Count non-depot nodes in this route
        non_dep_nodes = [n for n in route if n != 0]
        if not non_dep_nodes:
            continue

        L = len(non_dep_nodes)
        # For each node, compute global connectivity and cross-route interaction
        for node in non_dep_nodes:
            total_nodes += 1

            # Global connectivity: sum of distances to all other nodes
            sum_dist = 0.0
            for j in range(len(distance_matrix)):
                if j == node:
                    continue
                sum_dist += distance_matrix[node][j]

            # Cross-route interaction: minimum distance to any node in a different route
            cross_min = None
            for j in range(len(distance_matrix)):
                if j == node:
                    continue
                other_route = node_route.get(j, -1)
                if other_route != r_idx:
                    d = distance_matrix[node][j]
                    if cross_min is None or d < cross_min:
                        cross_min = d
            if cross_min is None:
                cross_min = 0.0

            # Route-load imbalance
            route_load = route_loads.get(r_idx, 0)
            if total_routes > 0:
                avg_load = total_demand / total_routes
            else:
                avg_load = 0.0
            load_diff = abs(route_load - avg_load)

            # Score combines global connectivity, cross-route interaction, and load imbalance
            score = sum_dist * 0.25 + cross_min * 0.5 + load_diff * 0.25

            # Small random perturbation
            perturb = rng.random() * 0.05 * (sum_dist + cross_min + 1.0)
            score += perturb

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        frag = 0.10 + rng.random() * 0.15  # between 0.10 and 0.25
        k = max(1, int(round(total_nodes * frag)))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
