    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Determine route medoid (node with minimal sum of distances to others)
        if L > 1:
            medoid_sums = {}
            for c in non_dep:
                s = 0.0
                for o in non_dep:
                    if o == c:
                        continue
                    s += distance_matrix[c][o]
                medoid_sums[c] = s
            center = min(medoid_sums, key=medoid_sums.get)
        else:
            center = non_dep[0]

        # Precompute sums to center for mean distance computation
        if L > 1:
            sums_to_center = {}
            for n in non_dep:
                sums_to_center[n] = distance_matrix[n][center]
            mean_factor = L - 1
        else:
            sums_to_center = {non_dep[0]: 0.0}
            mean_factor = 1  # not used when L == 1

        for node in non_dep:
            if L > 1:
                d_to_center = distance_matrix[node][center]
                mean_pair = sums_to_center[node] / mean_factor
            else:
                d_to_center = 0.0
                mean_pair = 0.0

            demand = demands[node] if node < len(demands) else 0

            # Route size factor grows with sqrt of route length
            route_size_factor = 1.0 + 0.15 * (L ** 0.5)

            # Score combining distance to center, intra-route spread, scaled by route size and inverse of demand
            score = d_to_center * route_size_factor
            score += mean_pair * 0.8
            score /= (1.0 + 0.4 * demand)

            # Small random perturbation
            perturb = rng.random() * 0.04 * (d_to_center + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
