def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Collect all non-depot nodes
    all_non_dep = []
    for route in current_solution:
        for n in route:
            if n != 0:
                all_non_dep.append(n)

    scores = []
    total_nd = len(all_non_dep)
    if total_nd == 0:
        return scores, 0

    # Global isolation sums: sum distance to every other non-depot node
    global_sums = {}
    for i in all_non_dep:
        s = 0.0
        row = distance_matrix[i]
        for j in all_non_dep:
            if j == i:
                continue
            s += row[j]
        global_sums[i] = s

    max_sum = max(global_sums.values()) if global_sums else 1.0
    if max_sum <= 0:
        max_sum = 1.0

    # Normalized base scores
    base_scores = {i: global_sums[i] / max_sum for i in all_non_dep}

    # Compute k as a fraction of total non-depot nodes (15% - 30%)
    frac = 0.15 + rng.random() * 0.15
    k = max(1, int(round(total_nd * frac)))
    if k > total_nd:
        k = total_nd

    # Compute per-node scores, oriented by their route length and demand
    for route in current_solution:
        L = len(route)
        for node in route:
            if node == 0:
                continue
            base = base_scores.get(node, 0.0)
            demand = demands[node] if node < len(demands) else 0
            score = base * (1.0 + 0.4 * (L - 1)) / (1.0 + 0.25 * demand)

            # Small random perturbation to diversify removal
            perturb = rng.random() * 0.05 * (base + 1.0)
            score += perturb

            scores.append((node, score))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 1

    scores = []
    # collect all non-depot nodes and build route mapping and loads
    all_non_dep = []
    node_to_route = {}
    route_loads = []
    for ridx, route in enumerate(current_solution):
        route_nodes = [n for n in route if n != 0]
        if not route_nodes:
            route_loads.append(0)
            continue
        load = 0
        for n in route_nodes:
            node_to_route[n] = ridx
            all_non_dep.append(n)
            if n < len(demands):
                load += demands[n]
        route_loads.append(load)

    total_non_dep = len(all_non_dep)
    if total_non_dep == 0:
        return scores, 0

    # find global center: node with minimal sum of distances to all other non-depot nodes
    center_node = None
    if total_non_dep >= 2:
        best_sum = None
        for candidate in all_non_dep:
            s = 0
            for other in all_non_dep:
                if other == candidate:
                    continue
                d = (distance_matrix[candidate][other]
                     if candidate < len(distance_matrix) and other < len(distance_matrix[candidate])
                     else 0)
                s += d
            if best_sum is None or s < best_sum:
                best_sum = s
                center_node = candidate
    elif total_non_dep == 1:
        center_node = all_non_dep[0]

    # compute per-node scores
    for node in all_non_dep:
        ridx = node_to_route.get(node, None)
        if ridx is None:
            continue
        route_nodes = [n for n in current_solution[ridx] if n != 0]
        L = len(route_nodes)
        route_load = route_loads[ridx]

        # global mean distance to other non-depot nodes
        global_mean = 0.0
        if total_non_dep > 1:
            s = 0.0
            for other in all_non_dep:
                if other == node:
                    continue
                d = (distance_matrix[node][other]
                     if node < len(distance_matrix) and other < len(distance_matrix[node])
                     else 0)
                s += d
            global_mean = s / (total_non_dep - 1)

        center_dist = (distance_matrix[node][center_node]
                       if (center_node is not None and node != center_node)
                       else 0.0)

        demand = demands[node] if node < len(demands) else 0
        route_util = route_load / cap if cap else 0.0
        size_term = 1.0 + (0.25 * ((L - 1) ** 0.5)) if L > 1 else 1.0

        score = (global_mean ** 0.95) * size_term
        score += center_dist * 0.7
        score -= (demand ** 0.6) * 0.6
        score += (1.0 - route_util) * 0.4

        perturb = rng.random() * 0.04 * (global_mean + 1.0)
        score += perturb

        scores.append((node, score))

    frac = 0.08 + rng.random() * 0.14  # between 0.08 and 0.22
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

