    for route in current_solution:
        for node in route:
            if node != 0:
                all_non_dep.append(node)

    total_non_dep = len(all_non_dep)
    # Build a unique global node list for cross-route sampling
    global_nodes = []
    seen = set()
    for n in all_non_dep:
        if n not in seen:
            seen.add(n)
            global_nodes.append(n)
    ng = len(global_nodes)

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue

        for node in non_dep:
            # intra-route maximum distance to capture local isolation
            max_intra = 0.0
            for other in non_dep:
                if other == node:
                    continue
                if node < len(distance_matrix) and other < len(distance_matrix[node]):
                    d = distance_matrix[node][other]
                else:
                    d = 0.0
                if d > max_intra:
                    max_intra = d

            # cross-route dispersion via mean distance to a small random sample of global nodes
            cross_mean = 0.0
            if ng > 1:
                s = min(5, ng - 1)
                sum_dist = 0.0
                count = 0
                for _ in range(s):
                    idx = rng.integers(0, ng)
                    other = global_nodes[idx]
                    if other == node:
                        continue
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        d = distance_matrix[node][other]
                    else:
                        d = 0.0
                    sum_dist += d
                    count += 1
                if count > 0:
                    cross_mean = sum_dist / count

            # distance to depot
            dist_to_depot = distance_matrix[node][0] if (0 < len(distance_matrix) and 0 < len(distance_matrix[node])) else 0.0
            demand = demands[node] if node < len(demands) else 0

            # composite score with a small random perturbation
            score = max_intra * 0.8 + cross_mean * 0.5 + dist_to_depot * 0.3
            score /= (1.0 + 0.6 * demand)
            perturb = rng.random() * 0.1 * (max_intra + cross_mean + dist_to_depot + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.30  # between 0.10 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

