                        continue
                    d = distance_matrix[i][j] if (i < len(distance_matrix) and j < len(distance_matrix[i])) else 0
                    s += d
                sums[i] = s
            medoid = min(non_dep, key=lambda x: sums[x])
        else:
            medoid = non_dep[0]

        # Simple route-length factor: grows with route size
        route_len_factor = 1.0 + 0.25 * (L - 1)

        for node in non_dep:
