def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        # collect non-depot nodes in the route
        route_nodes = [n for n in route if n != 0]
        m = len(route_nodes)
        if m == 0:
            continue

        total_non_dep += m

        # determine route center: node with minimal sum of distances to others
        center_node = None
        if m == 1:
            center_node = route_nodes[0]
        else:
            best_sum = None
            for cand in route_nodes:
                s = 0
                for other in route_nodes:
                    if other == cand:
                        continue
                    s += distance_matrix[cand][other]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    center_node = cand

        # precompute metrics per node
        dist_to_center = {}
        dispersion = {}

        # distances to center
        for node in route_nodes:
            dist_to_center[node] = distance_matrix[node][center_node] if center_node is not None else 0

        # dispersion: max distance to others minus min distance to others
        for node in route_nodes:
            if m > 1:
                dists = [distance_matrix[node][other] for other in route_nodes if other != node]
                if dists:
                    dispersion[node] = max(dists) - min(dists)
                else:
                    dispersion[node] = 0
            else:
                dispersion[node] = 0

        # maxima for normalization
        max_center_dist = max(dist_to_center[node] for node in route_nodes) if route_nodes else 1
        max_dispersion = max(dispersion[node] for node in route_nodes) if route_nodes else 1

        for node in route_nodes:
            dist_center = dist_to_center[node]
            disp = dispersion[node]

            norm_center = dist_center / max_center_dist if max_center_dist > 0 else 0.0
            norm_disp = disp / max_dispersion if max_dispersion > 0 else 0.0

            demand = demands[node] if node < len(demands) else 0

            # Score components: route-centered proximity, local dispersion, inverted demand
            score = (0.4 * norm_center) + (0.3 * norm_disp) + (0.2 * (1.0 / (1.0 + demand)))

            # small jitter to diversify
            jitter = (rng.random() * 0.04) - 0.02  # [-0.02, 0.02)
            score += jitter

            scores.append((node, score))

    # determine how many to remove
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.18  # between 0.08 and 0.26
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

