                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if d > max_to_others:
                        max_to_others = d
            else:
                max_to_others = 0.0

            demand = demands[node] if node < len(demands) else 0

            score = (max_to_others ** 1.3) * factor / (1.0 + 0.5 * demand)

            perturb = rng.random() * 0.05 * (max_to_others + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.09 + rng.random() * 0.18  # between 0.09 and 0.27
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_non_dep = 0

    for route in current_solution:
        if not route:
            continue

        route_nodes = [n for n in route if n is not None and n != 0]
        L = len(route_nodes)
        if L == 0:
            continue

        total_non_dep += L

        # determine route center (node with minimal sum of distances to others)
        center_node = None
        if L >= 2:
            best_sum = None
            for cand in route_nodes:
                s = 0
                for other in route_nodes:
                    if other == cand:
                        continue
                    s += distance_matrix[cand][other]
                if best_sum is None or s < best_sum:
                    best_sum = s
                    center_node = cand
        elif L == 1:
            center_node = route_nodes[0]

        # compute per-node dispersion, center distance, depot distance, and demand
        dispersions = {}
        center_dists = {}
        depot_dists = {}
        node_demands = {}
        for node in route_nodes:
            disp = 0.0
            for other in route_nodes:
                if other == node:
                    continue
                disp += distance_matrix[node][other]
            dispersions[node] = disp
            center_dists[node] = distance_matrix[node][center_node] if center_node is not None else 0.0
            depot_dists[node] = distance_matrix[node][0]
            node_demands[node] = demands[node] if node < len(demands) else 0

        max_disp = max(dispersions.values()) if dispersions else 0.0
        max_center = max(center_dists.values()) if center_dists else 0.0
        max_depot = max(depot_dists.values()) if depot_dists else 0.0
        max_demand = max(node_demands.values()) if node_demands else 0

        for node in route_nodes:
            disp_norm = dispersions[node] / (max_disp + 1.0)
            center_norm = center_dists[node] / (max_center + 1.0)
            depot_norm = depot_dists[node] / (max_depot + 1.0)
            demand_norm = node_demands[node] / (max_demand + 1.0) if max_demand > 0 else 0.0

            jitter = (rng.random() * 0.08) - 0.04  # [-0.04, +0.04)

            score = (disp_norm * 1.0) + ((1.0 - center_norm) * 0.6) + (depot_norm * 0.4) - (demand_norm * 0.5) + jitter
            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.22  # between 0.12 and 0.34
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

