        total_non_dep += L

        if L == 0:
            continue

        # Route-level factors
        route_demand = 0
        for node in non_dep:
            if node < len(demands):
                route_demand += demands[node]

        route_factor = 1.0 + 0.25 * (L - 1)

        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            demand = demands[node] if node < len(demands) else 0
            dist_component = (mean_distance ** 1.1)
            score = dist_component * route_factor

            if route_demand > 0:
                demand_ratio = demand / route_demand
            else:
                demand_ratio = 0.0

            score *= (1.0 + (0.5 - demand_ratio))

            jitter = rng.random() * 0.05 * (mean_distance + 1.0)
            score += jitter

            scores.append((node, score))

    if total_non_dep == 0:
