def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # New route-size factor grows linearly with route length
        factor = 1.0 + 0.15 * (L - 1)

        # Determine capacity for this route
        if r_idx < len(vehicle_capacities):
            cap = float(vehicle_capacities[r_idx])
        elif len(vehicle_capacities) > 0:
            cap = float(vehicle_capacities[0])
        else:
            cap = 1.0
        if cap <= 0.0:
            cap = 1.0

        # Route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for node in non_dep:
            # Compute average distance to two nearest neighbors within the route
            INF = float('inf')
            min1 = INF
            min2 = INF
            for other in non_dep:
                if other == node:
                    continue
                d = distance_matrix[node][other]
                if d < min1:
                    min2 = min1
                    min1 = d
                elif d < min2:
                    min2 = d
            if min1 == INF:
                mean_nearest = 0.0
            elif min2 == INF:
                mean_nearest = min1
            else:
                mean_nearest = (min1 + min2) / 2.0

            # Capacity scaling: penalize high route demand relative to capacity
            scale = 1.0 / (1.0 + (route_demand / cap))

            demand = demands[node] if node < len(demands) else 0

            # Score with exponent, route-size factor, and capacity scaling
            score = (mean_nearest ** 1.2) * factor * scale

            # Small random perturbation to diversify removal
            perturb = rng.random() * 0.05 * (mean_nearest + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.12  # between 0.08 and 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

