def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    max_capacity = max(vehicle_caps) if vehicle_caps else 1

    # compute global max distance for normalization
    max_dist = 0
    for row in distance_matrix:
        for val in row:
            if val > max_dist:
                max_dist = val

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # route-size factor: growth with L using a sublinear power
        if L > 1:
            size_factor = 1.0 + 0.25 * (L ** 0.25)
        else:
            size_factor = 1.0

        # current load on the route
        current_load = 0
        for n in non_dep:
            if n < len(demands):
                current_load += demands[n]

        for node in non_dep:
            # mean distance to other nodes in the same route
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            demand = demands[node] if node < len(demands) else 0
            dist_to_depot = distance_matrix[node][0] if len(distance_matrix[node]) > 0 else 0
            dist_to_depot_norm = dist_to_depot / max_dist if max_dist > 0 else 0.0

            cap = max_capacity if max_capacity > 0 else 1
            load_ratio = current_load / cap

            score = (mean_distance ** 0.95) * size_factor
            score *= (1.0 + 0.6 * dist_to_depot_norm)
            score *= (1.0 + 0.8 * load_ratio)

            perturb = rng.random() * 0.08 * (mean_distance + dist_to_depot + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.10  # between 0.05 and 0.15
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
