        if L == 0:
            continue

        total_non_dep += L
        route_size_factor = 1.0 + 0.05 * (L - 1)

        for node in non_dep:
            if L > 1:
                sum_dist = 0.0
                max_dist = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    sum_dist += d
                    if d > max_dist:
                        max_dist = d
                mean_distance = sum_dist / (L - 1)
            else:
                mean_distance = 0.0
                max_dist = 0.0

            demand = demands[node] if node < len(demands) else 0

            score_base = 0.6 * max_dist + 0.4 * mean_distance
            if demand > 0:
                score_base /= (1.0 + 0.6 * demand)

            perturb = rng.random() * 0.08 * (max_dist + mean_distance + 1.0)
            score = (score_base + perturb) * route_size_factor

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.10  # between 0.05 and 0.15
        k = max(1, int(round(total_non_dep * frac)))
