def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    scores = []
    total_nodes = 0

    for route in current_solution:
        if not route:
            continue

        route_nodes = [n for n in route if n is not None and n != 0]
        m = len(route_nodes)
        if m == 0:
            continue

        route_demand = 0
        for node in route_nodes:
            if node < len(demands):
                route_demand += demands[node]

        # minimax center (node with smallest maximum distance to others)
        center_node = None
        if len(route_nodes) >= 2:
            best_max = None
            for cand in route_nodes:
                max_dist = 0
                for other in route_nodes:
                    if other == cand:
                        continue
                    d = distance_matrix[cand][other]
                    if d > max_dist:
                        max_dist = d
                if best_max is None or max_dist < best_max:
                    best_max = max_dist
                    center_node = cand
        elif len(route_nodes) == 1:
            center_node = route_nodes[0]

        for idx, node in enumerate(route_nodes):
            total_nodes += 1

            if m == 1:
                savings = 0.0
            elif idx == 0:
                next_node = route_nodes[1]
                savings = distance_matrix[node][next_node]
            elif idx == m - 1:
                prev_node = route_nodes[idx - 1]
                savings = distance_matrix[prev_node][node]
            else:
                prev_node = route_nodes[idx - 1]
                next_node = route_nodes[idx + 1]
                savings = (distance_matrix[prev_node][node] +
                           distance_matrix[node][next_node] -
                           distance_matrix[prev_node][next_node])

            slack = cap - route_demand
            if slack < 0:
                slack = 0
            ratio = slack / cap if cap > 0 else 0.0
            # quadratic slack penalty
            factor = 1.0 - (ratio ** 2)

            demand = demands[node] if node < len(demands) else 0
            demand_term = (demand ** 0.9) * 0.9

            if center_node is not None:
                center_dist = distance_matrix[node][center_node]
                center_proximity = 1.0 / (center_dist + 1.0)
            else:
                center_proximity = 0.0

            jitter = (rng.random() * 0.4) - 0.2  # [-0.2, 0.2)

            score = savings * 0.5 + demand_term * 0.8 + center_proximity * 0.6 + jitter

            scores.append((node, score))

    max_k = max(1, total_nodes // 4) if total_nodes > 0 else 0
    if total_nodes == 0:
        k = 0
    else:
        k = int(rng.integers(1, max_k + 1))

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue
        total_non_dep += L

        cap = vehicle_capacities[idx] if idx < len(vehicle_capacities) else 0
        total_demand = 0
        for node in non_dep:
            if node < len(demands):
                total_demand += demands[node]
        remaining_cap = cap - total_demand
        slack_frac = 0.0
        if cap > 0:
            slack_frac = max(0.0, min(1.0, remaining_cap / cap))

        for node in non_dep:
            if L > 1:
                sum_dist = 0.0
                max_dist = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    sum_dist += d
                    if d > max_dist:
                        max_dist = d
                mean_dist = sum_dist / (L - 1)
            else:
                mean_dist = 0.0
                max_dist = 0.0

            spread = max_dist / (mean_dist + 1e-9)
            dnode = demands[node] if node < len(demands) else 0
            demand_ratio = dnode / (1.0 + dnode)
            if cap > 0:
                score = spread * (1.0 + 0.5 * demand_ratio) * (1.0 + (1.0 - slack_frac))
            else:
                score = spread * (1.0 + 0.5 * demand_ratio)
            perturb = rng.random() * 0.05 * (spread + 1.0)
            score += perturb
            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.18  # between 0.12 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

