        # Route-length factor grows with route size
        factor = 1.0 + 0.4 * (L - 1)

        for node in non_dep:
            # Distances to other non-depot nodes in this route
            others = [other for other in non_dep if other != node]
            dists = []
            for other in others:
                dists.append(distance_matrix[node][other])

            if len(dists) == 0:
                mean_distance = 0.0
            else:
                # Compute the mean of the two smallest distances (or the single if only one)
                if len(dists) == 1:
                    mean_distance = dists[0]
                else:
                    first = float('inf')
                    second = float('inf')
                    for dd in dists:
                        if dd < first:
                            second = first
                            first = dd
                        elif dd < second:
                            second = dd
                    mean_distance = (first + second) / 2.0

            demand = demands[node] if node < len(demands) else 0
            score = mean_distance * factor / (1.0 + demand)

            # Small random perturbation
            perturb = rng.random() * 0.05 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
