            if node < len(demands):
                route_demand += demands[node]

        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        if capacity <= 0:
            remaining_ratio = 0.0
        else:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0

        # New, faster-growing diversity
        diversity = 1.0 + 0.05 * (L - 1)

        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            node_demand = demands[node] if node < len(demands) else 0

            # Different weighting: increase emphasis on remaining capacity
            load_factor = 1.0 + 0.6 * (1.0 - remaining_ratio)

            score = (mean_distance ** 1.2) * diversity * load_factor
            score /= (1.0 + 0.4 * node_demand)

            perturb = rng.random() * 0.04 * (mean_distance + 1.0)
