        non_depot_total += len(non_dep)

        route_load = 0.0
        for n in non_dep:
            if n < len(demands):
                route_load += demands[n]

        route_len = len(route)

        for i in non_dep:
            sum_dist = 0.0
            for j in non_dep:
                if j == i:
                    continue
                d = distance_matrix[i][j] if (i < len(distance_matrix) and j < len(distance_matrix[i])) else 0
                sum_dist += d
            if len(non_dep) > 1:
                avg_dist = sum_dist / (len(non_dep) - 1)
            else:
                avg_dist = 0.0

            p = 1.2
            avg_term = avg_dist ** p

            route_len_factor = 1.0 + 0.8 * ((route_len - 1) ** 0.5)

            rem_cap_factor = 1.0 / (1.0 + route_load)

            perturbation = rng.random() * 0.01 * (avg_dist + 1.0)

            score = avg_term * route_len_factor * rem_cap_factor + perturbation

            scores.append((i, score))

    if non_depot_total == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.25  # between 0.10 and 0.35
        k = max(1, int(round(non_depot_total * frac)))
