def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    capacities = data.get('vehicle_capacities', [])

    # Collect all non-depot nodes
    all_nodes = []
    for route in current_solution:
        for n in route:
            if n != 0:
                all_nodes.append(n)
    total_non_dep = len(all_nodes)

    scores = []

    # Build a small set of landmark nodes (global)
    landmarks = []
    max_landmarks = 6
    if total_non_dep > 0:
        m = min(max_landmarks, total_non_dep)
        perm = rng.permutation(total_non_dep)
        for t in range(m):
            landmarks.append(all_nodes[perm[t]])

    # Precompute per-route loads and capacities
    route_loads = {}
    route_caps = {}
    for ri, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        s = 0
        for n in non_dep:
            if n < len(demands):
                s += demands[n]
        route_loads[ri] = s
        cap = capacities[ri % len(capacities)] if capacities else 0
        route_caps[ri] = cap

    # Loop over routes and nodes to compute scores
    for ri, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        for node in non_dep:
            # Landmark dispersion score
            if landmarks:
                s = 0.0
                for lm in landmarks:
                    s += distance_matrix[node][lm]
                mean_landmark_dist = s / len(landmarks)
            else:
                mean_landmark_dist = 0.0

            dist_to_depot = distance_matrix[node][0]

            # Intra-route max/distance summary to capture node's influence within its route
            max_intra = 0.0
            s_intra = 0.0
            for other in non_dep:
                if other == node:
                    continue
                d = distance_matrix[node][other]
                if d > max_intra:
                    max_intra = d
                s_intra += d
            mean_intra = s_intra / (L - 1) if L > 1 else 0.0

            # Route load awareness
            load = route_loads[ri]
            cap = route_caps[ri]
            load_ratio = (load / cap) if cap > 0 else 0.0
            if load_ratio > 1.0:
                load_ratio = 1.0

            # Distinct scoring: combine global dispersion, depot proximity, intra-route distances,
            # and route load, then apply random perturbation
            score = (mean_landmark_dist * 0.5) + (dist_to_depot * 0.2) + (max_intra * 0.2) + (mean_intra * 0.1)
            score *= (1.0 + 0.7 * load_ratio)

            perturb = rng.random() * 0.1 * (mean_landmark_dist + dist_to_depot + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.10  # between 0.12 and 0.22
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    # Build list of non-depot nodes per route
    routes_nodes = []
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        routes_nodes.append(non_dep)

    total_non_dep = sum(len(nodes) for nodes in routes_nodes)

    # Map node -> route id for quick lookup
    route_of = {}
    for rid, nodes in enumerate(routes_nodes):
        for n in nodes:
            route_of[n] = rid

    # Precompute route demands (optional, could be unused but kept for potential extension)
    route_demands = []
    for nodes in routes_nodes:
        s = 0
        for n in nodes:
            if n < len(demands):
                s += demands[n]
        route_demands.append(s)

    scores = []

    # Compute scores for each node
    for rid, nodes in enumerate(routes_nodes):
        L = len(nodes)
        if L == 0:
            continue

        for node in nodes:
            # Minimum distance to any node in a different route
            min_cross = None
            for other_rid, other_nodes in enumerate(routes_nodes):
                if other_rid == rid or not other_nodes:
                    continue
                for j in other_nodes:
                    d = distance_matrix[node][j] if (node < len(distance_matrix) and j < len(distance_matrix[node])) else 0
                    if min_cross is None or d < min_cross:
                        min_cross = d
            if min_cross is None:
                min_cross = 0.0

            # Distance to depot
            depot_dist = distance_matrix[node][0] if (node < len(distance_matrix) and 0 < len(distance_matrix[node])) else 0.0

            # Demand of the node
            demand = demands[node] if node < len(demands) else 0

            # Route length factor (sqrt-growth)
            factor = 1.0 + 0.6 * (L ** 0.5)

            # Score with cross-route proximity, depot distance, and demand weighting
            score = (min_cross * 0.7 + depot_dist * 0.3) * factor / (1.0 + demand)

            # Small random perturbation
            perturb = rng.random() * 0.05 * (min_cross + depot_dist + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.1 + rng.random() * 0.25  # between 0.10 and 0.35
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    # Build mapping of nodes to their routes and collect all non-depot nodes
    route_to_nodes = []
    node_to_route = {}
    all_non_dep = []

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        route_to_nodes.append(non_dep)
        for n in non_dep:
            node_to_route[n] = r_idx
            all_non_dep.append(n)

    scores = []
    total_non_dep = len(all_non_dep)

    if total_non_dep == 0:
        return scores, 0

    # Compute a radius from the median of all inter-node distances
    dist_pairs = []
    n_nodes = len(all_non_dep)
    for idx_i in range(n_nodes):
        i = all_non_dep[idx_i]
        row_i = distance_matrix[i]
        for idx_j in range(idx_i + 1, n_nodes):
            j = all_non_dep[idx_j]
            dist_pairs.append(row_i[j])

    if len(dist_pairs) == 0:
        radius = 0.0
    else:
        sorted_d = sorted(dist_pairs)
        m = sorted_d[len(sorted_d) // 2]
        if len(sorted_d) % 2 == 0:
            m = 0.5 * (sorted_d[len(sorted_d) // 2 - 1] + sorted_d[len(sorted_d) // 2])
        radius = max(0.0, m * 0.9)

    # For each non-depot node, compute cross-route proximity and intra-route neighborhood
    for i in all_non_dep:
        # cross-route proximity (number of nearby nodes across all routes within radius)
        cross_count = 0
        if radius > 0:
            for j in all_non_dep:
                if j == i:
                    continue
                if distance_matrix[i][j] <= radius:
                    cross_count += 1

        # intra-route nearest-neighbor sum
        r = node_to_route[i]
        route_nodes = route_to_nodes[r]
        intra_sum = 0.0
        if len(route_nodes) > 1:
            neigh_dists = []
            for other in route_nodes:
                if other == i:
                    continue
                neigh_dists.append(distance_matrix[i][other])
            k_nearest = int(round((len(route_nodes) - 1) ** 0.5))
            if k_nearest < 0:
                k_nearest = 0
            if k_nearest > len(neigh_dists):
                k_nearest = len(neigh_dists)
            if k_nearest > 0:
                neigh_dists.sort()
                intra_sum = sum(neigh_dists[:k_nearest])

        score = float(cross_count) + 0.8 * intra_sum
        perturb = rng.random() * 0.05 * (cross_count + intra_sum + 1.0)
        score += perturb

        scores.append((i, score))

    # Determine how many nodes to remove
    frac = 0.18 + rng.random() * 0.32  # random fraction in [0.18, 0.50)
    k = max(1, int(round(total_non_dep * frac)))
    if k > total_non_dep:
        k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    all_non_dep = []
    route_len = {}     # node -> route length (L)
    intra_mean = {}    # node -> intra-route mean distance

    # First pass: collect non-depot nodes, route lengths, and intra-route means
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        for node in non_dep:
            route_len[node] = L

        if L > 1:
            for node in non_dep:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                intra_mean[node] = s / (L - 1)
        else:
            for node in non_dep:
                intra_mean[node] = 0.0

        all_non_dep.extend(non_dep)

    N = len(all_non_dep)

    # Global mean distances to all other non-depot nodes
    global_mean = {}
    if N > 1:
        for i in all_non_dep:
            s = 0.0
            for j in all_non_dep:
                if j == i:
                    continue
                s += distance_matrix[i][j]
            global_mean[i] = s / (N - 1)
    else:
        for i in all_non_dep:
            global_mean[i] = 0.0

    # Compute scores for each non-depot node
    for i in all_non_dep:
        gm = global_mean.get(i, 0.0)
        im = intra_mean.get(i, 0.0)
        L = route_len.get(i, 1)
        delta = gm - im
        factor = 1.0 + 0.25 * (L - 1)
        score = delta * factor
        perturb = rng.random() * 0.25 * (abs(delta) + 1.0)
        score += perturb
        scores.append((i, score))

    total_non_dep = N
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

