    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for r_index, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        if vehicle_capacities:
            cap = vehicle_capacities[r_index % len(vehicle_capacities)]
        else:
            cap = 1000000

        route_demand = 0
        for node in non_dep:
            if node < len(demands):
                route_demand += demands[node]

        for node in non_dep:
            max_dist = 0.0
            for other in non_dep:
                if other == node:
                    continue
                d = distance_matrix[node][other]
                if d > max_dist:
                    max_dist = d

            depot_dist = distance_matrix[node][0] if 0 < len(distance_matrix) else 0.0
            node_demand = demands[node] if node < len(demands) else 0

            remaining_after_removal = cap - (route_demand - node_demand)
            rem_ratio = 0.0
            if cap > 0:
                rem_ratio = remaining_after_removal / cap
                if rem_ratio < 0.0:
                    rem_ratio = 0.0
                if rem_ratio > 1.0:
                    rem_ratio = 1.0

            score = max_dist * 0.9 + depot_dist * 0.4 + (1.0 - rem_ratio) * 2.0

            perturb = rng.random() * 0.05 * (max_dist + depot_dist + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.15
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # Build one anchor per route (medoid-like per-route anchor)
    anchors = []
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L
        if L == 0:
            continue
        if L == 1:
            anchors.append(non_dep[0])
        else:
            best_anchor = None
            best_sum = None
            for a in non_dep:
                s = 0.0
                for b in non_dep:
                    if b == a:
                        continue
                    s += distance_matrix[a][b]
                if (best_sum is None) or (s < best_sum):
                    best_sum = s
                    best_anchor = a
            anchors.append(best_anchor)

    # Compute scores for each non-depot node using distances to anchors
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        for node in non_dep:
            if len(anchors) > 0:
                s = 0.0
                for a in anchors:
                    s += distance_matrix[node][a]
                avg_dist_to_anchors = s / len(anchors)
            else:
                avg_dist_to_anchors = 0.0

            route_factor = 1.0 + 0.4 * (L - 1)

            demand = demands[node] if node < len(demands) else 0

            score = (avg_dist_to_anchors ** 1.2) * route_factor
            score /= (1.0 + 0.25 * demand)

            jitter = rng.random() * 0.05 * (avg_dist_to_anchors + 1.0)
            score += jitter

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.06 + rng.random() * 0.08  # between 0.06 and 0.14
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0
    n_nodes = len(distance_matrix)

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Different route-size factor (new form)
        factor = 1.0 + 0.25 * (L ** 0.4) + 0.12 * (L - 1)

        non_dep_set = set(non_dep)

        for node in non_dep:
            if L > 1:
                s = 0.0
                maxd = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    s += d
                    if d > maxd:
                        maxd = d
                intra_mean = s / (L - 1)
            else:
                intra_mean = 0.0
                maxd = 0.0

            depot_distance = distance_matrix[node][0]
            demand = demands[node] if node < len(demands) else 0

            # Cross-route proximity: nearest node outside this route
            min_out = float('inf')
            for other in range(n_nodes):
                if other == node:
                    continue
                if other in non_dep_set:
                    continue
                d = distance_matrix[node][other]
                if d < min_out:
                    min_out = d
            if min_out == float('inf'):
                cross_dist = depot_distance
            else:
                cross_dist = min_out

            score = (0.45 * intra_mean + 0.25 * maxd + 0.20 * depot_distance + 0.15 * cross_dist) * factor
            score /= (1.0 + demand)

            perturb = rng.random() * 0.05 * (intra_mean + 1.0 + maxd + depot_distance)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.05 + rng.random() * 0.25  # between 0.05 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

