        # Max demand among nodes in this route (for normalization)
        max_demand_in_route = 0
        for node in non_dep:
            if node < len(demands) and demands[node] > max_demand_in_route:
                max_demand_in_route = demands[node]

        # Route demand
        route_demand = 0
        for node in non_dep:
            if node < len(demands):
                route_demand += demands[node]
        remaining = cap - route_demand
        if remaining < 0:
            remaining = 0
        capacity_factor = 0.5 + 0.5 * (remaining / cap)

        # Precompute max distance per node to peers in this route
        max_distances = {}
        for node in non_dep:
            max_d = 0.0
            for other in non_dep:
                if other == node:
                    continue
                d = distance_matrix[node][other]
                if d > max_d:
                    max_d = d
            max_distances[node] = max_d

        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    s += (max_distances[node] - d)
                divergence = s / (L - 1)
            else:
                divergence = 0.0

            if max_demand_in_route > 0:
                demand_factor = 0.5 + 0.5 * (demands[node] / (max_demand_in_route + 1e-9))
            else:
                demand_factor = 0.5

            score = divergence * capacity_factor * demand_factor

            perturb = rng.random() * 0.05 * (divergence + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.18  # between 0.12 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    total_non_dep = 0
    scores = []

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)

        if L == 0:
            continue

        total_non_dep += L

        # Determine route center: node with minimum total distance to all other nodes in the route
        if L > 1:
            sums = []
            for i in range(L):
                node_i = non_dep[i]
                s = 0
                for j in range(L):
                    if i == j:
                        continue
                    other = non_dep[j]
                    s += distance_matrix[node_i][other]
                sums.append((node_i, s))
            center_node = min(sums, key=lambda x: x[1])[0]
        else:
            center_node = non_dep[0]

        # Precompute distance to center for each node in the route
        dist_to_center = {}
        if L > 1:
            for n in non_dep:
                dist_to_center[n] = distance_matrix[n][center_node]
        else:
            for n in non_dep:
                dist_to_center[n] = 0

        route_len_factor = 1.0 + (0.8 * L) / (L + 3)

        for node in non_dep:
            d_to_center = dist_to_center[node]
            d_to_depot = distance_matrix[node][0]
            demand = demands[node] if node < len(demands) else 0

            score = (d_to_center ** 1.1) * route_len_factor
            score /= (1.0 + 0.5 * demand)
            score += (d_to_depot ** 0.6) * 0.6

            perturb = rng.random() * 0.08 * (d_to_center + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.1 + rng.random() * 0.2  # between 0.1 and 0.3
        k = max(1, int(round(total_non_dep * frac)))
