        total_non_dep += L

        if L == 0:
            continue

        for node in non_dep:
            others = [n for n in non_dep if n != node]
            if len(others) > 0:
                s_count = 3
                if len(others) <= s_count:
                    sample = others
                else:
                    sample = rng.choice(others, size=s_count, replace=False)
                s = 0.0
                for other in sample:
                    s += distance_matrix[node][other]
                mean_intra = s / len(sample)
            else:
                mean_intra = 0.0

            distance_to_depot = distance_matrix[node][0]
            demand = demands[node] if node < len(demands) else 0

            score = 0.6 * (mean_intra ** 1.1) + 0.4 * (distance_to_depot ** 1.0)
            score /= (1.0 + 0.4 * demand)

            perturb = rng.random() * 0.15 * (mean_intra + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
