def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Identify medoid: node with minimal sum of distances to others in the route
        medoid = None
        if L > 0:
            best_sum = None
            for node in non_dep:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                if (best_sum is None) or (s < best_sum):
                    best_sum = s
                    medoid = node

        for node in non_dep:
            if L > 1:
                s = 0.0
                max_d = 0.0
                min_d = None
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    s += d
                    if d > max_d:
                        max_d = d
                    if min_d is None or d < min_d:
                        min_d = d
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0
                max_d = 0.0
                min_d = 0.0

            dist_to_medoid = distance_matrix[node][medoid] if medoid is not None else 0.0

            spread_factor = 0.0
            if L > 1:
                spread_factor = (max_d - min_d)

            node_demand = demands[node] if node < len(demands) else 0

            # Distinct scoring: emphasize nodes with larger mean distance and larger distance to medoid
            score = (mean_distance ** 0.6) * (1.0 + dist_to_medoid / (1.0 + max_d))
            score *= (1.0 + 0.4 * (spread_factor / (1.0 + max_d)) if max_d > 0 else 1.0)
            score /= (1.0 + 0.65 * node_demand)

            perturb = rng.random() * 0.05 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.18  # between 0.08 and 0.26
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    capacities = data.get('vehicle_capacities', [])

    # Map each non-depot node to its route index and compute per-route demands
    node_to_route = {}
    route_demands = []
    route_capacities = []
    for r_idx, route in enumerate(current_solution):
        cap = capacities[r_idx] if r_idx < len(capacities) else 0
        route_capacities.append(cap)
        rd = 0.0
        for n in route:
            if n != 0:
                node_to_route[n] = r_idx
                rd += demands[n] if n < len(demands) else 0.0
        route_demands.append(rd)

    # Ensure capacities are positive
    max_cap = max(capacities) if capacities else max(demands) if demands else 1.0
    for idx, cap in enumerate(route_capacities):
        if cap <= 0:
            route_capacities[idx] = max_cap if max_cap > 0 else 1.0

    # Gather all non-depot nodes
    non_dep_nodes = []
    for route in current_solution:
        for n in route:
            if n != 0:
                non_dep_nodes.append(n)

    total_non_dep = len(non_dep_nodes)

    # Precompute load factor for the route of each node
    route_load_factor = {}
    for n in non_dep_nodes:
        r = node_to_route.get(n, None)
        if r is None:
            route_load_factor[n] = 0.0
        else:
            cap = route_capacities[r]
            denom = cap if cap > 0 else 1.0
            route_load_factor[n] = route_demands[r] / denom

    # Compute scores
    scores = []
    for i in non_dep_nodes:
        s = 0.0
        for j in non_dep_nodes:
            if j == i:
                continue
            dist = distance_matrix[i][j]
            inv = 1.0 / (1.0 + dist)
            dem = demands[j] if j < len(demands) else 0.0
            demand_factor = 1.0 + dem / (1.0 + 1e-6)
            factor = 1.0 + route_load_factor.get(j, 0.0)
            s += inv * demand_factor * factor
        perturb = rng.random() * 0.01 * (1.0 + len(non_dep_nodes) * 0.5)
        score = s + perturb
        scores.append((i, score))

    # Determine k
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.20  # between 0.10 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    # Compute global max distance for depot influence normalization
    max_dist = 0
    n = len(distance_matrix)
    for i in range(n):
        row = distance_matrix[i]
        for j in range(len(row)):
            if row[j] > max_dist:
                max_dist = row[j]
    if max_dist <= 0:
        max_dist = 1

    for route in current_solution:
        non_dep = [node for node in route if node != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        for node in non_dep:
            outward = 0.0
            if L > 1:
                for other in non_dep:
                    if other == node:
                        continue
                    d = 0.0
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        d = distance_matrix[node][other]
                    outward += d * d

            depot_distance = 0.0
            if node < len(distance_matrix) and 0 < len(distance_matrix[node]):
                depot_distance = distance_matrix[node][0]

            demand = demands[node] if node < len(demands) else 0
            depot_factor = 1.0 + (depot_distance / max_dist)

            score = outward * depot_factor / (1.0 + demand)

            perturb = rng.random() * 0.05 * (outward + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.20  # between 0.12 and 0.32
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    # Build per-route lists of non-depot nodes
    route_nodes = []
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        route_nodes.append(non_dep)

    total_non_dep = sum(len(n) for n in route_nodes)

    scores = []

    # Precompute: for cross-route distances, we will reference all other routes' nodes
    for i, non_dep in enumerate(route_nodes):
        L = len(non_dep)
        if L == 0:
            continue

        for node in non_dep:
            # Nearest intra-route neighbor distance
            if L > 1:
                min_within = None
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if (min_within is None) or (d < min_within):
                        min_within = d
                if min_within is None:
                    min_within = 0.0
            else:
                min_within = 0.0

            # Nearest cross-route distance to any node in other routes
            min_cross = None
            for j, other_non_dep in enumerate(route_nodes):
                if j == i:
                    continue
                for other in other_non_dep:
                    d = distance_matrix[node][other]
                    if (min_cross is None) or (d < min_cross):
                        min_cross = d
            if min_cross is None:
                min_cross = 0.0

            depot_dist = distance_matrix[node][0]
            demand = demands[node] if node < len(demands) else 0

            # Route-length factor (gently increasing with route size)
            route_factor = 1.0 + 0.15 * (L - 1)

            # Components with distinct influence
            within_term = 1.0 / (1.0 + min_within)  # higher when nearest neighbor is far
            cross_term = min_cross / (1.0 + min_cross)  # saturating effect
            depot_term = depot_dist / (1.0 + depot_dist)

            score = (0.4 * within_term + 0.4 * cross_term + 0.2 * depot_term) * route_factor
            score /= (1.0 + 0.5 * demand)

            perturb = rng.random() * 0.05 * (min_within + min_cross + depot_dist + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.14  # between 0.08 and 0.22
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    routes = current_solution

    scores = []

    # Build mapping from node to its route index for quick reference
    route_of_node = {}
    for r_idx, route in enumerate(routes):
        for n in route:
            if n != 0:
                route_of_node[n] = r_idx

    # Radius R for cross-route diversity (derived from global average pairwise distance)
    n_nodes = len(distance_matrix)
    total = 0.0
    count = 0
    for i in range(n_nodes):
        for j in range(i + 1, n_nodes):
            total += distance_matrix[i][j]
            count += 1
    avg_pair = total / count if count > 0 else 0.0
    R = 0.6 * avg_pair
    if R <= 0:
        R = 1.0

    # Iterate over each route and each non-depot node to compute score
    for r_idx, route in enumerate(routes):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        for node in non_dep:
            # Mean distance to the two nearest intra-route neighbors
            others = [m for m in non_dep if m != node]
            if others:
                dists = [distance_matrix[node][other] for other in others]
                if len(dists) >= 2:
                    dists_sorted = sorted(dists)
                    mean_nearest = (dists_sorted[0] + dists_sorted[1]) / 2.0
                else:
                    mean_nearest = dists[0]
            else:
                mean_nearest = 0.0

            dist_to_depot = distance_matrix[node][0]

            demand = demands[node] if node < len(demands) else 0
            route_len = len(route)
            factor = 1.0 + 0.3 * (route_len - 1)

            # Cross-route diversity term: proportion of other routes having a node within radius R of this node
            own_route = route_of_node.get(node, r_idx)
            other_routes = [idx for idx in range(len(routes)) if idx != own_route]
            cross_routes = 0
            for or_idx in other_routes:
                other_route = routes[or_idx]
                found = False
                for j in other_route:
                    if j == 0:
                        continue
                    if distance_matrix[node][j] <= R:
                        found = True
                        break
                if found:
                    cross_routes += 1
            num_other_routes = len(routes) - 1 if len(routes) > 1 else 1
            cross_term = cross_routes / max(1, num_other_routes)

            score = (0.5 * mean_nearest + 0.25 * dist_to_depot + 0.25 * cross_term) * factor
            score /= (1.0 + demand)

            perturb = rng.random() * 0.05 * (mean_nearest + dist_to_depot + 1.0)
            score += perturb

            scores.append((node, score))

    total_non_dep = sum(len([n for n in route if n != 0]) for route in routes)
    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        # Route-size factor grows with route length
        factor = 1.0 + 0.25 * (L - 1)

        for node in non_dep:
            # Intra-route spread: mean of squared distances to other nodes in the same route
            if L > 1:
                s2 = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    s2 += d * d
                intra_spread = s2 / (L - 1)
            else:
                intra_spread = 0.0

            # Cross-route isolation: distance to the nearest node in any other route
            cross_min = float('inf')
            for r2_idx, route2 in enumerate(current_solution):
                if r2_idx == r_idx:
                    continue
                for other in route2:
                    if other == 0:
                        continue
                    d = distance_matrix[node][other]
                    if d < cross_min:
                        cross_min = d
            if cross_min == float('inf'):
                cross_min = 0.0

            # Depot distance
            depot_dist = distance_matrix[node][0]

            demand = demands[node] if node < len(demands) else 0

            # New scoring: combine intra_spread, cross_min, and depot_dist with route-size factor
            score = (0.6 * intra_spread + 0.25 * cross_min + 0.15 * depot_dist) * factor
            score /= (1.0 + demand)

            # Small random perturbation
            perturb = rng.random() * 0.04 * (intra_spread + cross_min + depot_dist + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.14  # between 0.08 and 0.22
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    # Prepare per-route non-depot lists
    routes_non_dep = []
    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        routes_non_dep.append(non_dep)
        total_non_dep += len(non_dep)

    # Compute scores per node
    for route_idx, non_dep in enumerate(routes_non_dep):
        L = len(non_dep)
        if L == 0:
            continue

        # Collect all nodes from other routes for cross-route distance
        other_nodes = []
        for idx, other_non_dep in enumerate(routes_non_dep):
            if idx == route_idx:
                continue
            other_nodes.extend(other_non_dep)

        for node in non_dep:
            # Maximum intra-route distance
            max_intra = 0.0
            if L > 1:
                for other in non_dep:
                    if other == node:
                        continue
                    d = distance_matrix[node][other]
                    if d > max_intra:
                        max_intra = d

            # Minimum distance to any node in other routes
            min_cross = 0.0
            if other_nodes:
                min_cross = float('inf')
                for other in other_nodes:
                    d = distance_matrix[node][other]
                    if d < min_cross:
                        min_cross = d
                if min_cross == float('inf'):
                    min_cross = 0.0
            else:
                min_cross = 0.0

            # Route-size factor
            factor = 1.0 + 0.25 * (L - 1)

            # Demand damping
            demand = demands[node] if node < len(demands) else 0
            score = (0.6 * max_intra + 0.4 * min_cross) * factor
            score /= (1.0 + demand)

            # Small random perturbation
            perturb = rng.random() * 0.05 * (max_intra + min_cross + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.22  # between 0.08 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        for node in non_dep:
            # Intra-route sum of distances to peers in the same route
            if L > 1:
                intra_sum = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    intra_sum += distance_matrix[node][other]
            else:
                intra_sum = 0.0

            # Cross-route influence: sum of minimum distances to each other route
            inter_sum = 0.0
            for other_r_idx, other_route in enumerate(current_solution):
                if other_r_idx == r_idx:
                    continue
                other_nodes = [n for n in other_route if n != 0]
                if not other_nodes:
                    continue
                min_d = None
                for other in other_nodes:
                    d = distance_matrix[node][other]
                    if (min_d is None) or (d < min_d):
                        min_d = d
                if min_d is not None:
                    inter_sum += min_d

            # Route-size factor (saturating with route length)
            factor = 1.0 + 0.8 * ((L - 1) / (L + 2))

            score = (intra_sum + 1e-9) * (1.0 + inter_sum) * factor

            # Small random perturbation to diversify removal
            perturb = rng.random() * 0.05 * (intra_sum + inter_sum + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.10 + rng.random() * 0.20  # between 0.10 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    non_dep_total = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue
        non_dep_total += len(non_dep)

        for i in non_dep:
            dists = []
            for j in non_dep:
                if j == i:
                    continue
                if i < len(distance_matrix) and j < len(distance_matrix[i]):
                    d = distance_matrix[i][j]
                else:
                    d = 0
                dists.append(d)

            if len(dists) > 0:
                avg_dist = sum(dists) / len(dists)
                max_dist = max(dists)
                dispersion = max_dist - avg_dist
            else:
                dispersion = 0.0

            demand = demands[i] if i < len(demands) else 0
            factor = 1.0 + 0.6 * (len(route) - 1)
            score = dispersion * factor / (1.0 + 0.7 * demand)
            score += rng.random() * 0.02 * (dispersion + 1.0)
            scores.append((i, score))

    if non_dep_total == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(non_dep_total * frac)))
        if k > non_dep_total:
            k = non_dep_total

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Compute route total demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        # Compute mean distance from each node to others in the route
        mean_distances = {}
        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distances[node] = s / (L - 1)
            else:
                mean_distances[node] = 0.0

        max_mean = max(mean_distances.values()) if mean_distances else 0.0

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # Local bypass saving if removing this node
            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0

            mean_distance = mean_distances[node]
            centrality_norm = mean_distance / max_mean if max_mean > 0.0 else 0.0

            demand = demands[node] if node < len(demands) else 0.0
            load_ratio = demand / route_demand if route_demand > 0.0 else 0.0

            # New scoring: emphasize high local saving and high centrality, with a load penalty
            score = (saving + 1.0) * (1.0 + 0.6 * centrality_norm)
            if route_demand > 0.0:
                score *= (1.0 / (1.0 + load_ratio))

            perturb = rng.random() * 0.05 * (saving + mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.12 + rng.random() * 0.18  # between 0.12 and 0.30
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_capacities = data.get('vehicle_capacities', [])

    scores = []
    total_non_dep = 0

    for r_idx, route in enumerate(current_solution):
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        if L == 0:
            continue

        total_non_dep += L

        route_demand = sum(demands[node] if node < len(demands) else 0 for node in non_dep)
        capacity = vehicle_capacities[r_idx] if r_idx < len(vehicle_capacities) else 0
        if capacity <= 0:
            remaining_ratio = 0.0
        else:
            remaining_ratio = (capacity - route_demand) / capacity
            if remaining_ratio < 0.0:
                remaining_ratio = 0.0
            if remaining_ratio > 1.0:
                remaining_ratio = 1.0

        diversity = 1.0 + 0.02 * (L - 1)

        for node in non_dep:
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            node_demand = demands[node] if node < len(demands) else 0

            load_factor = 1.0 + 0.6 * (1.0 - remaining_ratio)

            score = (mean_distance ** 1.25) * diversity * load_factor
            score /= (1.0 + 0.5 * node_demand)

            perturb = rng.random() * 0.04 * (mean_distance + 1.0)
            score += perturb

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.20
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

