    vehicle_capacities = data.get('vehicle_capacities', [])
    max_capacity = max(vehicle_capacities) if vehicle_capacities else 1

    scores = []
    non_dep_total = 0

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        if not non_dep:
            continue
        non_dep_total += len(non_dep)

        # Compute total route load from non-depot nodes
        route_load = 0
        for n in non_dep:
            if n < len(demands):
                route_load += demands[n]

        for i in non_dep:
            # Sum distances from i to all other non-depot nodes in the same route
            sum_dist = 0.0
            for j in non_dep:
                if j == i:
                    continue
                sum_dist += distance_matrix[i][j]
            if len(non_dep) > 1:
                avg_dist = sum_dist / (len(non_dep) - 1)
            else:
                avg_dist = 0.0

            demand_i = demands[i] if i < len(demands) else 0
            utilization = route_load / max_capacity if max_capacity > 0 else 0.0
            factor = 1.0 + 0.8 * utilization + 0.25 * (len(route) - 1)
            score = avg_dist * factor

            if demand_i > 0:
                score = score / (1.0 + 0.4 * demand_i)

            perturb = rng.random() * 0.03 * (avg_dist + 1.0)
            score += perturb

            scores.append((i, score))

    if non_dep_total == 0:
        k = 0
    else:
        frac = 0.15 + rng.random() * 0.25  # between 0.15 and 0.40
        k = max(1, int(round(non_dep_total * frac)))
        if k > non_dep_total:
            k = non_dep_total

    return scores, k

